pub const RUN_LIFECYCLE_UNCONFIGURED_ERROR_CODE: &str = "run_lifecycle_unconfigured";
pub const SSE_HEARTBEAT_INTERVAL_SECS: u64 = 15;
fn validate_execution_cancellation_statuses(expected_statuses: &[&str]) -> Result<(), String> {
    if expected_statuses.is_empty() {
        return Err("execution cancellation requires an active expected status".to_string());
    }
    if let Some(status) = expected_statuses
        .iter()
        .find(|status| !matches!(**status, STATUS_RUNNING | STATUS_WAITING | STATUS_PAUSED))
    {
        return Err(format!(
            "execution cancellation cannot be admitted from non-active status {status}"
        ));
    }
    Ok(())
}

pub fn is_run_lifecycle_unconfigured_error(status: StatusCode, error: &ErrorResponse) -> bool {
    status == StatusCode::NOT_IMPLEMENTED
        && error.error_code.as_deref() == Some(RUN_LIFECYCLE_UNCONFIGURED_ERROR_CODE)
}

#[async_trait]
pub trait RunLifecycleService: Send + Sync {
    /// Return the process-wide durable run-owner identity, when this
    /// lifecycle implementation uses shared run leases.
    ///
    /// Background recovery must construct its store with the same identity as
    /// the live lifecycle. Reconstructing a database store with its default
    /// random identity splits lease/control authority and makes a healthy
    /// process look orphaned as soon as a lease expires.
    fn execution_owner_pod_id(&self) -> Option<&str> {
        None
    }

    async fn create_run(
        &self,
        user_id: String,
        request: ChatRequestData,
    ) -> Result<ChatRunRecord, (StatusCode, Json<ErrorResponse>)>;

    async fn stream_chat(
        &self,
        user_id: String,
        request: ChatRequestData,
    ) -> Result<ChatStreamRecord, (StatusCode, Json<ErrorResponse>)>;

    async fn get_run_status(
        &self,
        run_id: String,
        user_id: String,
    ) -> Result<RunStatusRecord, (StatusCode, Json<ErrorResponse>)>;

    async fn get_run_projection(
        &self,
        _run_id: String,
        _user_id: String,
        _recent_limit: u32,
    ) -> Result<RunProjectionRecord, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Run projection not supported",
        ))
    }

    async fn repair_run_projection(
        &self,
        _run_id: String,
        _user_id: String,
        _recent_limit: u32,
    ) -> Result<RunProjectionRecord, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Run projection repair not supported",
        ))
    }

    async fn stream_run(
        &self,
        run_id: String,
        user_id: String,
        last_index: u32,
    ) -> Result<Vec<serde_json::Value>, (StatusCode, Json<ErrorResponse>)>;

    async fn stream_run_live(
        &self,
        run_id: String,
        user_id: String,
        last_index: u32,
    ) -> Result<ChatStreamRecord, (StatusCode, Json<ErrorResponse>)> {
        let events = self.stream_run(run_id.clone(), user_id, last_index).await?;
        Ok(ChatStreamRecord {
            session_id: String::new(),
            run_id,
            events,
            event_rx: None,
        })
    }

    async fn cancel_run(
        &self,
        run_id: String,
        user_id: String,
    ) -> Result<CancelRunRecord, (StatusCode, Json<ErrorResponse>)>;

    async fn cancel_session_runs(
        &self,
        _session_id: String,
        _user_id: String,
    ) -> Result<Vec<CancelRunRecord>, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Session run cancellation not supported",
        ))
    }

    async fn list_runs_cursor(
        &self,
        user_id: String,
        limit: u32,
        cursor: Option<RunListCursor>,
    ) -> Result<RunListRecord, (StatusCode, Json<ErrorResponse>)>;

    /// Return a bounded authoritative snapshot of one session's durable runs.
    /// Active work is retained ahead of terminal history when the snapshot is
    /// truncated. The route layer is responsible for projecting wire types.
    async fn list_session_runs(
        &self,
        _user_id: String,
        _session_id: String,
        _limit: u32,
    ) -> Result<DurableSessionRunPage, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Session run tree not supported",
        ))
    }

    /// Pause an active run. Default: NOT_IMPLEMENTED.
    async fn pause_run(
        &self,
        _run_id: String,
        _user_id: String,
    ) -> Result<RunMutationRecord, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Pause not supported",
        ))
    }

    /// Resume a paused run. Default: NOT_IMPLEMENTED.
    async fn resume_run(
        &self,
        _run_id: String,
        _user_id: String,
    ) -> Result<RunMutationRecord, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Resume not supported",
        ))
    }

    async fn submit_run_user_intent(
        &self,
        _run_id: String,
        _user_id: String,
        _input: RunUserIntentData,
    ) -> Result<RunUserIntentRecord, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Active-run user intents are not supported",
        ))
    }

    /// Drain pending tool approval requests for a run.
    ///
    /// Returns JSON objects with `request_id`, `tool`, `args` fields.
    /// The WS handler calls this during its polling loop to forward
    /// approval requests to the client.
    ///
    /// Default: no-op (returns empty vec).
    async fn drain_approval_requests(&self, _run_id: &str) -> Vec<serde_json::Value> {
        vec![]
    }

    /// Drain pending ask_user prompt requests for a run.
    ///
    /// Returns JSON objects with `request_id`, `question`, `choices`, `default`,
    /// and `context` fields. The WS handler calls this during its polling loop to
    /// forward prompts to the client.
    ///
    /// Default: no-op (returns empty vec).
    async fn drain_user_prompt_requests(&self, _run_id: &str) -> Vec<serde_json::Value> {
        vec![]
    }

    async fn get_run_interaction_event(
        &self,
        _run_id: String,
        _user_id: String,
        _request_id: String,
        _event_type: String,
    ) -> Result<Option<serde_json::Value>, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Durable run interactions are not supported",
        ))
    }

    async fn resolve_run_interaction(
        &self,
        _run_id: String,
        _user_id: String,
        _expected_session_id: String,
        _request_id: String,
        _kind: DurableRunInteractionKind,
        _response_data: serde_json::Value,
    ) -> Result<DurableRunInteractionResolveOutcome, (StatusCode, Json<ErrorResponse>)> {
        Err(error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Durable run interactions are not supported",
        ))
    }

    /// Drain pending tool progress events for a run.
    ///
    /// Returns JSON objects with `kind` field (`started`, `delta`, `completed`).
    /// The WS handler calls this during its polling loop to forward
    /// progress events to the client.
    ///
    /// Default: no-op (returns empty vec).
    async fn drain_progress_events(&self, _run_id: &str) -> Vec<serde_json::Value> {
        vec![]
    }

    /// Wait for in-flight background tasks to finish during graceful shutdown.
    /// Returns `true` if all tasks drained within the timeout.
    /// Default: no-op (returns true immediately).
    async fn drain_background_tasks(&self, _timeout: std::time::Duration) -> bool {
        true
    }

    /// Stop in-flight producers after the passive graceful-drain/checkpoint
    /// window. Implementations must not reuse user-cancellation authority for
    /// server shutdown; process-local abort is allowed so resource-owner Drop
    /// guards run while the database and reconciliation workers are still alive.
    async fn stop_background_tasks_for_shutdown(&self, timeout: std::time::Duration) -> bool {
        self.drain_background_tasks(timeout).await
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExecutionBudget {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub initial_turns: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub hard_turn_limit: Option<u32>,
}

/// Request-local snapshot of the wall-clock slice still available for useful
/// agent execution.
///
/// This is intentionally independent from [`ExecutionBudget`]: round limits
/// may auto-expand as the runtime makes progress, while elapsed wall time must
/// never be replenished. A missing value preserves the legacy unbounded
/// wall-clock behavior. Servers must treat this client-provided value as an
/// upper bound and monotonically decrease it at later model boundaries.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExecutionTimeBudget {
    pub remaining_seconds: u64,
}

/// Request-scoped execution controls.
///
/// Turn-intent classification policy for callers that explicitly need a
/// server-side semantic admission decision before any primary-agent action.
///
/// Primary user turns use one bounded semantic admission concurrently with
/// the primary request by default. The result is awaited only before an
/// executable/completion boundary, so ordinary latency can overlap while a
/// Work-required goal cannot silently degrade into untracked execution.
/// Delegated sub-runs explicitly use [`TurnIntentExecutionPolicy::FixedDefault`]
/// because their parent already owns the lifecycle decision.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ExecutionPolicyRequest {
    #[serde(default)]
    pub turn_intent: TurnIntentExecutionPolicy,
    #[serde(default)]
    pub skill_auto_route: SkillAutoRouteExecutionPolicy,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TurnIntentExecutionPolicy {
    /// Run Astra's auxiliary TurnIntent LLM before the primary agent. This is
    /// an explicit strict-admission mode for callers that require a semantic
    /// decision before ordinary root tool selection.
    #[default]
    Auto,
    /// Do not add a serial auxiliary model boundary. The primary agent makes
    /// the semantic Work choice through visible typed tools; all resulting
    /// lifecycle effects remain runtime-owned and deterministic.
    FixedDefault,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SkillAutoRouteExecutionPolicy {
    #[default]
    Auto,
    /// Do not call Astra's auxiliary skill auto-route LLM. Skills remain
    /// visible to the primary model and can still be invoked explicitly.
    Disabled,
}

