#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RunStartIdempotencyKind {
    ProviderTask,
    WorkTurn,
}

/// Selects who owns model choice for one internal run-start request.
///
/// Public chat transports always use [`Self::ExplicitOffering`]. Product
/// boundaries such as Work may instead ask the Server to apply its existing
/// default Offering policy without exposing model routing in their wire DTO.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum ModelSelectionMode {
    #[default]
    ExplicitOffering,
    ServerDefault,
}

/// Server-derived exact identity for a logical run start.
///
/// This is deliberately absent from public chat DTOs. Product boundaries
/// derive it from their typed, authenticated mutation identity so the shared
/// run lifecycle can claim or replay exactly one durable run.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RunStartIdempotency {
    kind: RunStartIdempotencyKind,
    run_id: String,
    request_fingerprint: String,
}

impl RunStartIdempotency {
    pub fn new(
        kind: RunStartIdempotencyKind,
        run_id: impl Into<String>,
        request_fingerprint: impl Into<String>,
    ) -> Result<Self, &'static str> {
        let run_id = run_id.into();
        if run_id.is_empty()
            || run_id.len() > 64
            || !run_id
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-'))
        {
            return Err("run start identity must use 1..=64 ASCII resource characters");
        }
        let request_fingerprint = request_fingerprint.into();
        if request_fingerprint.len() != 64
            || !request_fingerprint
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit())
        {
            return Err("run start request fingerprint must be 64 hexadecimal characters");
        }
        Ok(Self {
            kind,
            run_id,
            request_fingerprint: request_fingerprint.to_ascii_lowercase(),
        })
    }

    pub fn kind(&self) -> RunStartIdempotencyKind {
        self.kind
    }

    pub fn run_id(&self) -> &str {
        &self.run_id
    }

    pub fn request_fingerprint(&self) -> &str {
        &self.request_fingerprint
    }
}

