const DEFAULT_RETRY_SCOPE: &str = "node";
const MAX_TOOL_OUTPUT_BATCH_ROWS: usize = 500;
const MAX_TOOL_OUTPUT_BATCH_BYTES: usize = 16 * 1024 * 1024;
const FALLBACK_PREVIEW_BYTES: usize = 400;
const BUILTIN_GENERIC_PREVIEW_BYTES: usize = 1200;

#[derive(Clone, Debug)]
struct ToolPreviewContract {
    max_preview_bytes: usize,
    normalize_version: String,
    found: bool,
}

fn default_tool_preview_contract(tool_name: &str) -> ToolPreviewContract {
    if astra_runtime_env::ToolRegistry::builtins()
        .get(tool_name)
        .is_some()
    {
        // A built-in without a specialized normalizer still has a complete,
        // code-owned preview contract. The registry is the authority for
        // built-in identity; absence from the optional DB specialization
        // table must not become a durable runtime warning.
        ToolPreviewContract {
            max_preview_bytes: BUILTIN_GENERIC_PREVIEW_BYTES,
            normalize_version: "text_v1".to_string(),
            found: true,
        }
    } else {
        ToolPreviewContract {
            max_preview_bytes: FALLBACK_PREVIEW_BYTES,
            normalize_version: "raw_v1".to_string(),
            found: false,
        }
    }
}

#[derive(Clone, Debug)]
struct ToolOutputPreviewRow {
    payload: String,
    preview_text: String,
    preview_status: String,
    artifact_ref: Option<String>,
    content_hash: String,
    normalize_version: String,
    parent_output_id: Option<String>,
}

#[derive(Debug, Error)]
pub enum DatabaseRunStateStoreError {
    #[error("database operation failed: operation={operation}, entity={entity}, source={source}")]
    Database {
        operation: &'static str,
        entity: String,
        #[source]
        source: sqlx::Error,
    },
    #[error("invalid retry_scope for run {run_id}: {retry_scope}")]
    InvalidRetryScope { run_id: String, retry_scope: String },
    #[error("tool output batch too large: run_id={run_id}, rows={rows}, bytes={bytes}")]
    ToolOutputBatchTooLarge {
        run_id: String,
        rows: usize,
        bytes: usize,
    },
    #[error("JSON serialization failed: operation={operation}, entity={entity}, source={source}")]
    Json {
        operation: &'static str,
        entity: String,
        #[source]
        source: serde_json::Error,
    },
    #[error("invalid durable tool output: output_id={output_id}, source={source}")]
    InvalidToolOutput {
        output_id: String,
        #[source]
        source: ToolInvocationContractError,
    },
}

type DbStoreResult<T> = Result<T, DatabaseRunStateStoreError>;

const RUN_CONTROL_DB_ATTEMPT_TIMEOUT: Duration = Duration::from_secs(5);
const RUN_CONTROL_LOCK_WAIT_TIMEOUT_SECS: i64 = 3;

/// A checked-out shared-pool connection that is reusable only after its
/// caller explicitly proves the MySQL protocol is synchronized.
///
/// Dropping a future while SQLx is awaiting a MySQL response can otherwise
/// return a connection with an in-flight exchange to the pool. Normal paths
/// call [`Self::release`] after completing every query; timeout/cancellation
/// paths reach `Drop` and close only that physical connection.
struct CancellationSafePoolConnection {
    connection: Option<PoolConnection<MySql>>,
}

impl CancellationSafePoolConnection {
    async fn acquire(
        pool: &SharedPool,
        deadline: tokio::time::Instant,
        operation: &'static str,
        entity: &str,
    ) -> Result<Self, String> {
        let connection = tokio::time::timeout_at(deadline, pool.get().acquire())
            .await
            .map_err(|_| bounded_run_control_timeout(operation, entity))?
            .map_err(|source| db_error(operation, entity, source).to_string())?;
        Ok(Self {
            connection: Some(connection),
        })
    }

    fn connection_mut(&mut self) -> &mut sqlx::MySqlConnection {
        self.connection
            .as_deref_mut()
            .expect("cancellation-safe connection already released")
    }

    fn release(mut self) {
        drop(self.connection.take());
    }
}

impl Drop for CancellationSafePoolConnection {
    fn drop(&mut self) {
        if let Some(connection) = self.connection.as_mut() {
            connection.close_on_drop();
        }
    }
}

struct BoundedRunControlConnection {
    connection: CancellationSafePoolConnection,
    original_lock_wait_timeout: i64,
}

impl BoundedRunControlConnection {
    async fn acquire(
        pool: &SharedPool,
        deadline: tokio::time::Instant,
        operation: &'static str,
        entity: &str,
    ) -> Result<Self, String> {
        let mut connection =
            CancellationSafePoolConnection::acquire(pool, deadline, operation, entity).await?;
        let original_lock_wait_timeout = match tokio::time::timeout_at(
            deadline,
            sqlx::query_scalar::<_, String>("SELECT @@session.lock_wait_timeout")
                .fetch_one(connection.connection_mut()),
        )
        .await
        {
            Ok(Ok(value)) => value,
            Ok(Err(source)) => {
                connection.release();
                return Err(db_error(operation, entity, source).to_string());
            }
            Err(_) => return Err(bounded_run_control_timeout(operation, entity)),
        };
        let original_lock_wait_timeout = match original_lock_wait_timeout.parse::<i64>() {
            Ok(value) if value >= 0 => value,
            Ok(value) => {
                connection.release();
                return Err(format!(
                    "{operation} read negative session lock_wait_timeout {value} for {entity}"
                ));
            }
            Err(source) => {
                connection.release();
                return Err(format!(
                    "{operation} could not decode session lock_wait_timeout for {entity}: {source}"
                ));
            }
        };
        let bounded_lock_wait =
            format!("SET SESSION lock_wait_timeout = {RUN_CONTROL_LOCK_WAIT_TIMEOUT_SECS}");
        match tokio::time::timeout_at(
            deadline,
            connection
                .connection_mut()
                .execute(bounded_lock_wait.as_str()),
        )
        .await
        {
            Ok(Ok(_)) => Ok(Self {
                connection,
                original_lock_wait_timeout,
            }),
            Ok(Err(source)) => {
                connection.release();
                Err(db_error(operation, entity, source).to_string())
            }
            Err(_) => Err(bounded_run_control_timeout(operation, entity)),
        }
    }

    fn connection_mut(&mut self) -> &mut sqlx::MySqlConnection {
        self.connection.connection_mut()
    }

    /// Restore the checkout's prior session state and return it to the shared
    /// pool. A failed or cancelled reset leaves the guard armed, so only that
    /// connection is discarded.
    async fn restore_and_release(
        mut self,
        deadline: tokio::time::Instant,
        operation: &'static str,
        entity: &str,
    ) -> Result<(), String> {
        let reset = format!(
            "SET SESSION lock_wait_timeout = {}",
            self.original_lock_wait_timeout
        );
        match tokio::time::timeout_at(
            deadline,
            self.connection.connection_mut().execute(reset.as_str()),
        )
        .await
        {
            Ok(Ok(_)) => {
                self.connection.release();
                Ok(())
            }
            Ok(Err(source)) => Err(db_error(operation, entity, source).to_string()),
            Err(_) => Err(bounded_run_control_timeout(operation, entity)),
        }
    }
}

fn bounded_run_control_timeout(operation: &'static str, entity: &str) -> String {
    format!(
        "{operation} timed out after {} seconds for {entity}",
        RUN_CONTROL_DB_ATTEMPT_TIMEOUT.as_secs()
    )
}

enum StagedExecutionOwnerCancellation {
    Rollback(AtomicExecutionOwnerCancellation),
    Commit { terminal_event: serde_json::Value },
}

enum ExecutionOwnerCancellationAttempt {
    Resolved(Result<AtomicExecutionOwnerCancellation, String>),
    DiscardConnection(String),
    CommitAmbiguous {
        error: String,
        terminal_event: serde_json::Value,
    },
}

enum CancellationMarkerAttempt {
    Resolved(Result<bool, String>),
    DiscardConnection(String),
    CommitAmbiguous(String),
}

