fn decode_run_checkpoint_record_from_row(
    row: &impl RunStateDbRow,
) -> DbStoreResult<DurableRunCheckpointRecord> {
    let operation = "decode_run_checkpoint_row";
    let table = "run_checkpoints";
    Ok(DurableRunCheckpointRecord {
        checkpoint_id: run_row_string(row, operation, table, "checkpoint_id")?,
        run_id: run_row_string(row, operation, table, "run_id")?,
        user_id: run_row_string(row, operation, table, "user_id")?,
        session_id: run_row_string(row, operation, table, "session_id")?,
        node_seq: run_row_non_negative_i64(row, operation, table, "node_seq")?,
        checkpoint_kind: run_row_string(row, operation, table, "checkpoint_kind")?,
        checkpoint_version: run_row_string(row, operation, table, "checkpoint_version")?,
        idempotency_key: run_row_string(row, operation, table, "idempotency_key")?,
        checkpoint_json: run_row_string(row, operation, table, "checkpoint_json")?,
        created_at: run_row_datetime_string(row, operation, table, "created_at")?,
    })
}

fn decode_run_event_payload(
    row: &impl RunStateDbRow,
    run_id: &str,
) -> DbStoreResult<serde_json::Value> {
    let operation = "decode_run_event_row";
    let table = "agent_run_events";
    let payload = run_row_string(row, operation, table, "payload_json")?;
    let event_idx = run_row_non_negative_i64(row, operation, table, "event_idx")?;
    let mut value = serde_json::from_str::<serde_json::Value>(&payload).map_err(|source| {
        DatabaseRunStateStoreError::Json {
            operation: "decode_run_event_payload",
            entity: format!("{table}.payload_json:{run_id}:{event_idx}"),
            source,
        }
    })?;
    if let Some(obj) = value.as_object_mut() {
        // The row key is authoritative. Payload-provided indices are stream
        // metadata and must never override durable cursor/ack identity.
        obj.insert("index".to_string(), serde_json::json!(event_idx));
    }
    Ok(value)
}

pub fn extract_event_type(event: &serde_json::Value) -> String {
    extract_optional_string(event, "event_type")
        .or_else(|| extract_optional_string(event, "type"))
        .unwrap_or_else(|| "unknown".to_string())
}

fn extract_optional_string(event: &serde_json::Value, key: &str) -> Option<String> {
    event
        .get(key)
        .and_then(serde_json::Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(ToOwned::to_owned)
}

fn extract_interaction_request_id(event: &serde_json::Value) -> Option<String> {
    extract_optional_string(event, "request_id").or_else(|| {
        event
            .get("data")
            .and_then(|data| extract_optional_string(data, "request_id"))
    })
}

fn validate_run_guidance_admission_request(
    request: AtomicRunGuidanceAdmissionRequest<'_>,
) -> Result<(), String> {
    validate_expected_run_session_id(request.expected_session_id)?;
    if request.intent_id.trim().is_empty() {
        return Err("guidance intent_id must not be empty".to_string());
    }
    if extract_event_type(request.event) != "user_intent" {
        return Err("guidance admission requires a user_intent event".to_string());
    }
    let expected_key = format!("user_intent:{}", request.intent_id);
    if extract_optional_string(request.event, "idempotency_key").as_deref()
        != Some(expected_key.as_str())
    {
        return Err("guidance event idempotency key does not match intent_id".to_string());
    }
    if request
        .event
        .get("data")
        .and_then(|data| extract_optional_string(data, "intent_id"))
        .as_deref()
        != Some(request.intent_id)
    {
        return Err("guidance event payload does not match intent_id".to_string());
    }
    Ok(())
}

fn run_guidance_event_matches(existing: &serde_json::Value, requested: &serde_json::Value) -> bool {
    extract_event_type(existing) == "user_intent"
        && extract_event_type(requested) == "user_intent"
        && extract_optional_string(existing, "idempotency_key")
            == extract_optional_string(requested, "idempotency_key")
        && existing.get("data") == requested.get("data")
}

fn run_guidance_admission_is_fenced(events: &[serde_json::Value]) -> bool {
    events
        .iter()
        .rev()
        .find_map(|event| match extract_event_type(event).as_str() {
            "user_intent_settlement_fenced" => Some(true),
            "user_intent_admission_reopened" => Some(false),
            _ => None,
        })
        .unwrap_or(false)
}

fn run_event_data_or_self(
    event: &serde_json::Value,
) -> Option<&serde_json::Map<String, serde_json::Value>> {
    if event.get("event_type").is_some() {
        event.get("data").and_then(serde_json::Value::as_object)
    } else {
        event.as_object()
    }
}

fn run_status_snapshot_from_run(run: &DurableRunRecord) -> DurableRunStatusSnapshot {
    let binding = run_status_binding_from_events(&run.events);
    let accounting = run
        .events
        .iter()
        .rev()
        .find_map(|event| {
            (extract_event_type(event) == "run_accounting_finalized")
                .then(|| event.get("data").cloned())
                .flatten()
        })
        .or_else(|| {
            run.events.iter().rev().find_map(|event| {
                (extract_event_type(event) == "run_finished")
                    .then(|| event.get("data").cloned())
                    .flatten()
            })
        });
    DurableRunStatusSnapshot {
        run_id: run.run_id.clone(),
        user_id: run.user_id.clone(),
        session_id: run.session_id.clone(),
        parent_run_id: run.parent_run_id.clone(),
        root_run_id: run.root_run_id.clone(),
        depth: run.depth,
        status: run.status.clone(),
        waiting_for: run.waiting_for.clone(),
        run_generation: run.run_generation,
        last_event_idx: run.last_event_idx,
        total_prompt_tokens: run.total_prompt_tokens,
        total_completion_tokens: run.total_completion_tokens,
        total_tool_calls: run.total_tool_calls,
        work_binding: run.work_binding.clone(),
        workspace: binding
            .as_ref()
            .and_then(|data| data.get("workspace").cloned()),
        executor: binding
            .as_ref()
            .and_then(|data| data.get("executor").cloned()),
        transport: binding
            .as_ref()
            .and_then(|data| data.get("transport"))
            .and_then(serde_json::Value::as_str)
            .map(ToString::to_string),
        accounting,
    }
}

/// Reconstruct the run-level execution binding with the same authority rule
/// used by the runtime projection: only canonical binding events participate,
/// and the first value for each field wins. Tool-route metadata and later
/// server-local observations cannot rebind an already-started run.
fn run_status_binding_from_events(events: &[serde_json::Value]) -> Option<serde_json::Value> {
    let mut binding = serde_json::Map::new();
    for event in events {
        if !matches!(
            extract_event_type(event).as_str(),
            "run_started" | "workspace_bound" | "executor_bound"
        ) {
            continue;
        }
        let Some(data) = run_event_data_or_self(event) else {
            continue;
        };
        for key in ["workspace", "executor", "transport"] {
            if !binding.contains_key(key)
                && let Some(value) = data.get(key)
            {
                binding.insert(key.to_string(), value.clone());
            }
        }
    }
    (!binding.is_empty()).then_some(serde_json::Value::Object(binding))
}

fn interaction_idempotency_key(
    kind: DurableRunInteractionKind,
    request_id: &str,
    suffix: &str,
) -> String {
    let identity = sha256_hex(request_id.as_bytes());
    format!(
        "interaction:{}:{identity}:{suffix}",
        kind.idempotency_namespace()
    )
}

fn interaction_resolution_events(
    kind: DurableRunInteractionKind,
    request_id: &str,
    response_data: serde_json::Value,
    include_resume: bool,
) -> Vec<serde_json::Value> {
    let outcome = response_data
        .get("outcome")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("resolved");
    let mut events = vec![serde_json::json!({
        "event_type": kind.resolved_event_type(),
        "idempotency_key": interaction_idempotency_key(kind, request_id, "terminal"),
        "data": response_data,
    })];
    if include_resume {
        events.push(serde_json::json!({
            "event_type": "run_resumed",
            "idempotency_key": interaction_idempotency_key(kind, request_id, "resume"),
            "data": {
                "reason": kind.waiting_for(),
                "request_id": request_id,
                "interaction_outcome": outcome,
            }
        }));
    }
    events
}

const APPROVAL_DECISION_QUEUED_EVENT_TYPE: &str = "approval_decision_queued";

fn approval_decision_queued_event(
    request_id: &str,
    response_data: serde_json::Value,
) -> serde_json::Value {
    serde_json::json!({
        "event_type": APPROVAL_DECISION_QUEUED_EVENT_TYPE,
        "idempotency_key": interaction_idempotency_key(
            DurableRunInteractionKind::Approval,
            request_id,
            "queued",
        ),
        "data": response_data,
    })
}

fn queued_approval_response_matches(
    existing: &serde_json::Value,
    response_data: &serde_json::Value,
) -> bool {
    existing.get("data") == Some(response_data)
}

fn exact_queued_approval<'a>(
    events: &'a [serde_json::Value],
    request_id: &str,
) -> Option<&'a serde_json::Value> {
    events.iter().rev().find(|event| {
        extract_event_type(event) == APPROVAL_DECISION_QUEUED_EVENT_TYPE
            && extract_interaction_request_id(event).as_deref() == Some(request_id)
    })
}

fn in_memory_registration_authority_disposition(
    run: &DurableRunRecord,
    authority: &InteractionRegistrationAuthority,
) -> Result<Option<InteractionResolutionDisposition>, String> {
    if !matches!(run.status.as_str(), STATUS_RUNNING | STATUS_WAITING) {
        return Ok(Some(InteractionResolutionDisposition::AuthorityLost(
            DurableRunInteractionAuthorityLoss::Inactive {
                status: run.status.clone(),
            },
        )));
    }
    if run.run_generation != authority.expected_owner_generation {
        return Ok(Some(InteractionResolutionDisposition::AuthorityLost(
            DurableRunInteractionAuthorityLoss::OwnerGenerationMismatch {
                actual_owner_generation: run.run_generation,
            },
        )));
    }
    if run.owner_pod_id != authority.expected_owner_pod_id {
        return Ok(Some(InteractionResolutionDisposition::AuthorityLost(
            DurableRunInteractionAuthorityLoss::OwnerMismatch {
                actual_owner_pod_id: run.owner_pod_id.clone(),
            },
        )));
    }
    if !in_memory_action_owner_lease_is_active(run)? {
        return Ok(Some(InteractionResolutionDisposition::AuthorityLost(
            DurableRunInteractionAuthorityLoss::OwnerLeaseExpired,
        )));
    }
    if authority.expected_control_epoch > run.last_event_idx {
        return Err(format!(
            "registered interaction control epoch {} is ahead of durable run {} event index {}",
            authority.expected_control_epoch, run.run_id, run.last_event_idx
        ));
    }
    if let Some((index, _)) = run.events.iter().enumerate().find(|(index, event)| {
        *index as i64 > authority.expected_control_epoch
            && extract_event_type(event) == "user_intent"
    }) {
        return Ok(Some(InteractionResolutionDisposition::Superseded {
            user_intent_event_index: index as i64,
        }));
    }
    Ok(None)
}

const INTERACTION_RESOLUTION_RECEIPT_FIELD: &str = "_durable_resolution";

#[derive(Clone, Debug, PartialEq, Eq)]
enum InteractionResolutionDisposition {
    Resumed,
    AuthorityLost(DurableRunInteractionAuthorityLoss),
    Superseded { user_intent_event_index: i64 },
}

fn authority_loss_receipt(reason: &DurableRunInteractionAuthorityLoss) -> serde_json::Value {
    match reason {
        DurableRunInteractionAuthorityLoss::Inactive { status } => serde_json::json!({
            "kind": "inactive",
            "status": status,
        }),
        DurableRunInteractionAuthorityLoss::OwnerGenerationMismatch {
            actual_owner_generation,
        } => serde_json::json!({
            "kind": "owner_generation_mismatch",
            "actual_owner_generation": actual_owner_generation,
        }),
        DurableRunInteractionAuthorityLoss::OwnerMismatch {
            actual_owner_pod_id,
        } => serde_json::json!({
            "kind": "owner_mismatch",
            "actual_owner_pod_id": actual_owner_pod_id,
        }),
        DurableRunInteractionAuthorityLoss::OwnerLeaseExpired => serde_json::json!({
            "kind": "owner_lease_expired",
        }),
        DurableRunInteractionAuthorityLoss::FrontierChanged => serde_json::json!({
            "kind": "frontier_changed",
        }),
    }
}

fn authority_loss_from_receipt(
    receipt: &serde_json::Value,
) -> Option<DurableRunInteractionAuthorityLoss> {
    let reason = receipt.get("authority_loss")?;
    match reason.get("kind")?.as_str()? {
        "inactive" => Some(DurableRunInteractionAuthorityLoss::Inactive {
            status: reason.get("status")?.as_str()?.to_string(),
        }),
        "owner_generation_mismatch" => Some(
            DurableRunInteractionAuthorityLoss::OwnerGenerationMismatch {
                actual_owner_generation: reason.get("actual_owner_generation")?.as_u64()?,
            },
        ),
        "owner_mismatch" => Some(DurableRunInteractionAuthorityLoss::OwnerMismatch {
            actual_owner_pod_id: reason
                .get("actual_owner_pod_id")
                .and_then(serde_json::Value::as_str)
                .map(ToString::to_string),
        }),
        "owner_lease_expired" => Some(DurableRunInteractionAuthorityLoss::OwnerLeaseExpired),
        "frontier_changed" => Some(DurableRunInteractionAuthorityLoss::FrontierChanged),
        _ => None,
    }
}

fn interaction_resolution_disposition(
    resume_wait: bool,
    authority_loss: Option<DurableRunInteractionAuthorityLoss>,
    superseded_by: Option<i64>,
) -> InteractionResolutionDisposition {
    if let Some(user_intent_event_index) = superseded_by {
        InteractionResolutionDisposition::Superseded {
            user_intent_event_index,
        }
    } else if let Some(reason) = authority_loss {
        InteractionResolutionDisposition::AuthorityLost(reason)
    } else if resume_wait {
        InteractionResolutionDisposition::Resumed
    } else {
        InteractionResolutionDisposition::AuthorityLost(
            DurableRunInteractionAuthorityLoss::FrontierChanged,
        )
    }
}

fn interaction_response_with_receipt(
    mut response_data: serde_json::Value,
    disposition: &InteractionResolutionDisposition,
    wait_authority: Option<&InteractionWaitAuthority>,
    run: Option<&DurableRunRecord>,
) -> serde_json::Value {
    let disposition_name = match disposition {
        InteractionResolutionDisposition::Resumed => "resumed",
        InteractionResolutionDisposition::AuthorityLost(_) => "authority_lost",
        InteractionResolutionDisposition::Superseded { .. } => "superseded",
    };
    let mut receipt = serde_json::json!({
        "disposition": disposition_name,
        "expected_owner_generation": wait_authority.map(|authority| authority.expected_owner_generation),
        "expected_owner_pod_id": wait_authority.and_then(|authority| authority.expected_owner_pod_id.as_deref()),
        "expected_control_epoch": wait_authority.map(|authority| authority.expected_control_epoch),
        "actual_owner_generation": run.map(|run| run.run_generation),
        "actual_owner_pod_id": run.and_then(|run| run.owner_pod_id.as_deref()),
        "actual_status": run.map(|run| run.status.as_str()),
        "actual_waiting_for": run.and_then(|run| run.waiting_for.as_deref()),
    });
    match disposition {
        InteractionResolutionDisposition::AuthorityLost(reason) => {
            receipt["authority_loss"] = authority_loss_receipt(reason);
        }
        InteractionResolutionDisposition::Superseded {
            user_intent_event_index,
        } => {
            receipt["user_intent_event_index"] = serde_json::json!(user_intent_event_index);
        }
        InteractionResolutionDisposition::Resumed => {}
    }
    if let Some(data) = response_data.as_object_mut() {
        data.insert(INTERACTION_RESOLUTION_RECEIPT_FIELD.to_string(), receipt);
        response_data
    } else {
        serde_json::json!({
            "response": response_data,
            INTERACTION_RESOLUTION_RECEIPT_FIELD: receipt,
        })
    }
}

fn interaction_resolution_receipt(event: &serde_json::Value) -> Option<&serde_json::Value> {
    event
        .get("data")
        .and_then(|data| data.get(INTERACTION_RESOLUTION_RECEIPT_FIELD))
}

fn interaction_outcome_from_durable_receipt(
    event: serde_json::Value,
    fresh: bool,
) -> DurableRunInteractionResolveOutcome {
    let Some(receipt) = interaction_resolution_receipt(&event) else {
        return DurableRunInteractionResolveOutcome::AuthorityLost {
            event,
            reason: DurableRunInteractionAuthorityLoss::FrontierChanged,
        };
    };
    match receipt
        .get("disposition")
        .and_then(serde_json::Value::as_str)
    {
        Some("authority_lost") => DurableRunInteractionResolveOutcome::AuthorityLost {
            reason: authority_loss_from_receipt(receipt)
                .unwrap_or(DurableRunInteractionAuthorityLoss::FrontierChanged),
            event,
        },
        Some("superseded") => DurableRunInteractionResolveOutcome::Superseded {
            user_intent_event_index: receipt
                .get("user_intent_event_index")
                .and_then(serde_json::Value::as_i64)
                .unwrap_or(-1),
            event,
        },
        Some("resumed") if fresh => DurableRunInteractionResolveOutcome::Resolved(event),
        Some("resumed") => DurableRunInteractionResolveOutcome::Idempotent(event),
        _ => DurableRunInteractionResolveOutcome::AuthorityLost {
            event,
            reason: DurableRunInteractionAuthorityLoss::FrontierChanged,
        },
    }
}

fn interaction_wait_started_event(
    kind: DurableRunInteractionKind,
    request_id: &str,
    expected_owner_generation: u64,
    expected_owner_pod_id: Option<&str>,
    expected_control_epoch: i64,
) -> serde_json::Value {
    serde_json::json!({
        "event_type": "interaction_wait_started",
        "idempotency_key": interaction_idempotency_key(kind, request_id, "wait"),
        "data": {
            "request_id": request_id,
            "waiting_for": kind.waiting_for(),
            "expected_owner_generation": expected_owner_generation,
            "expected_owner_pod_id": expected_owner_pod_id,
            "expected_control_epoch": expected_control_epoch,
        }
    })
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct InteractionWaitAuthority {
    expected_owner_generation: u64,
    expected_owner_pod_id: Option<String>,
    expected_control_epoch: i64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct InteractionRegistrationAuthority {
    expected_owner_generation: u64,
    expected_owner_pod_id: Option<String>,
    expected_control_epoch: i64,
}

fn interaction_registration_authority(
    event: &serde_json::Value,
) -> Option<InteractionRegistrationAuthority> {
    let data = event.get("data")?;
    Some(InteractionRegistrationAuthority {
        expected_owner_generation: data.get("expected_owner_generation")?.as_u64()?,
        expected_owner_pod_id: data
            .get("expected_owner_pod_id")
            .and_then(serde_json::Value::as_str)
            .map(ToString::to_string),
        expected_control_epoch: data.get("expected_control_epoch")?.as_i64()?,
    })
}

impl From<&InteractionRegistrationAuthority> for InteractionWaitAuthority {
    fn from(authority: &InteractionRegistrationAuthority) -> Self {
        Self {
            expected_owner_generation: authority.expected_owner_generation,
            expected_owner_pod_id: authority.expected_owner_pod_id.clone(),
            expected_control_epoch: authority.expected_control_epoch,
        }
    }
}

fn interaction_wait_authority(event: &serde_json::Value) -> Option<InteractionWaitAuthority> {
    let data = event.get("data")?;
    Some(InteractionWaitAuthority {
        expected_owner_generation: data.get("expected_owner_generation")?.as_u64()?,
        expected_owner_pod_id: data
            .get("expected_owner_pod_id")
            .and_then(serde_json::Value::as_str)
            .map(ToString::to_string),
        expected_control_epoch: data.get("expected_control_epoch")?.as_i64()?,
    })
}

fn exact_interaction_wait_authority(
    events: &[serde_json::Value],
    kind: DurableRunInteractionKind,
    request_id: &str,
) -> Option<InteractionWaitAuthority> {
    events.iter().rev().find_map(|event| {
        (extract_event_type(event) == "interaction_wait_started"
            && extract_interaction_request_id(event).as_deref() == Some(request_id)
            && event
                .pointer("/data/waiting_for")
                .and_then(serde_json::Value::as_str)
                == Some(kind.waiting_for()))
        .then(|| interaction_wait_authority(event))
        .flatten()
    })
}

fn earliest_unresolved_interaction_request_id(
    events: &[serde_json::Value],
    kind: DurableRunInteractionKind,
) -> Option<String> {
    let resolved = events
        .iter()
        .filter(|event| extract_event_type(event) == kind.resolved_event_type())
        .filter_map(extract_interaction_request_id)
        .collect::<HashSet<_>>();
    events.iter().find_map(|event| {
        (extract_event_type(event) == kind.required_event_type())
            .then(|| extract_interaction_request_id(event))
            .flatten()
            .filter(|request_id| !resolved.contains(request_id))
    })
}

fn exact_interaction_wait_frontier(
    events: &[serde_json::Value],
    kind: DurableRunInteractionKind,
) -> Option<String> {
    events.iter().rev().find_map(|event| {
        (extract_event_type(event) == "interaction_wait_started"
            && event
                .get("data")
                .and_then(|data| data.get("waiting_for"))
                .and_then(serde_json::Value::as_str)
                == Some(kind.waiting_for()))
        .then(|| extract_interaction_request_id(event))
        .flatten()
    })
}

fn interaction_response_matches(
    existing: &serde_json::Value,
    response_data: &serde_json::Value,
) -> bool {
    let mut durable_response = existing.get("data").cloned();
    if let Some(serde_json::Value::Object(data)) = durable_response.as_mut() {
        data.remove(INTERACTION_RESOLUTION_RECEIPT_FIELD);
    }
    durable_response.as_ref() == Some(response_data)
}

fn existing_interaction_resolution_outcome(
    existing: serde_json::Value,
    response_data: &serde_json::Value,
) -> DurableRunInteractionResolveOutcome {
    let durable = interaction_outcome_from_durable_receipt(existing.clone(), false);
    if matches!(
        durable,
        DurableRunInteractionResolveOutcome::AuthorityLost { .. }
            | DurableRunInteractionResolveOutcome::Superseded { .. }
    ) || interaction_response_matches(&existing, response_data)
    {
        durable
    } else {
        DurableRunInteractionResolveOutcome::Conflict(existing)
    }
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    format!("{digest:x}")
}

#[derive(Debug)]
struct RunEventInsertRow {
    id: String,
    run_id: String,
    event_idx: i64,
    user_id: String,
    session_id: String,
    event_type: String,
    event_id: String,
    agent_id: String,
    subject_run_id: Option<String>,
    interaction_request_id: Option<String>,
    idempotency_key: Option<String>,
    event_hash: String,
    producer_pod_id: String,
    request_id: Option<String>,
    payload_json: String,
}

impl RunEventInsertRow {
    fn nullable_shape(&self) -> [bool; 4] {
        [
            self.subject_run_id.is_some(),
            self.interaction_request_id.is_some(),
            self.idempotency_key.is_some(),
            self.request_id.is_some(),
        ]
    }
}

#[derive(Debug)]
struct RecoveredInteractionEvent {
    id: String,
    run_id: String,
    event_idx: i64,
    user_id: String,
    session_id: String,
    event_type: String,
    event_id: String,
    agent_id: String,
    subject_run_id: Option<String>,
    interaction_request_id: Option<String>,
    idempotency_key: Option<String>,
    event_hash: String,
    producer_pod_id: String,
    payload_json: String,
    payload: serde_json::Value,
}

#[derive(Debug, PartialEq, Eq)]
enum GuidanceCommitRecovery {
    ThisAttempt(i64),
    Equivalent(i64),
    Conflict,
    NotCommitted,
}

#[derive(Debug)]
struct RecoveredRunControlEvent {
    id: String,
    event_idx: i64,
    event_type: String,
    event_id: String,
    idempotency_key: String,
    event_hash: String,
    producer_pod_id: String,
    payload_json: String,
    payload: serde_json::Value,
}

#[derive(Debug, PartialEq, Eq)]
enum UserIntentAdmissionTransitionRecovery {
    ThisAttempt(i64),
    Equivalent(i64),
    Conflict,
    NotCommitted,
    Inactive { status: String },
    OwnerGenerationMismatch { actual_owner_generation: u64 },
    OwnerMismatch { actual_owner_pod_id: Option<String> },
    OwnerLeaseExpired,
    Missing,
}

fn classify_user_intent_admission_transition_recovery(
    recovered: &[RecoveredRunControlEvent],
    expected_event: &serde_json::Value,
    expected_row: &RunEventInsertRow,
) -> UserIntentAdmissionTransitionRecovery {
    let Some(recovered) = recovered.first() else {
        return UserIntentAdmissionTransitionRecovery::NotCommitted;
    };
    let Some(key) = expected_row.idempotency_key.as_deref() else {
        return UserIntentAdmissionTransitionRecovery::Conflict;
    };
    if !recovered_run_control_event_is_equivalent(recovered, expected_event, key) {
        return UserIntentAdmissionTransitionRecovery::Conflict;
    }
    if recovered_run_control_event_is_exact(recovered, expected_row) {
        UserIntentAdmissionTransitionRecovery::ThisAttempt(recovered.event_idx)
    } else {
        UserIntentAdmissionTransitionRecovery::Equivalent(recovered.event_idx)
    }
}

#[derive(Debug, PartialEq, Eq)]
enum TerminalIntentReturnRecovery {
    ThisAttempt(Vec<i64>),
    Equivalent(Vec<i64>),
    Conflict,
    NotCommitted,
}

#[derive(Debug, PartialEq, Eq)]
enum UserIntentApplyRecovery {
    ThisAttempt(Vec<i64>),
    Equivalent(Vec<i64>),
    Conflict,
    NotCommitted,
    OwnerGenerationMismatch { actual_owner_generation: u64 },
    OwnerMismatch { actual_owner_pod_id: Option<String> },
    Missing,
}

fn decode_recovered_run_control_events(
    rows: Vec<sqlx::mysql::MySqlRow>,
    run_id: &str,
) -> Result<Vec<RecoveredRunControlEvent>, String> {
    rows.into_iter()
        .map(|row| {
            let payload_json: String = row.try_get("payload_json").map_err(|source| {
                db_error("decode_run_control_event_payload", run_id, source).to_string()
            })?;
            let payload = serde_json::from_str(&payload_json).map_err(|source| {
                DatabaseRunStateStoreError::Json {
                    operation: "decode_run_control_event_payload",
                    entity: run_id.to_string(),
                    source,
                }
                .to_string()
            })?;
            Ok(RecoveredRunControlEvent {
                id: row.try_get("id").map_err(|source| {
                    db_error("decode_run_control_event_id", run_id, source).to_string()
                })?,
                event_idx: row.try_get("event_idx").map_err(|source| {
                    db_error("decode_run_control_event_index", run_id, source).to_string()
                })?,
                event_type: row.try_get("event_type").map_err(|source| {
                    db_error("decode_run_control_event_type", run_id, source).to_string()
                })?,
                event_id: row.try_get("event_id").map_err(|source| {
                    db_error("decode_run_control_event_event_id", run_id, source).to_string()
                })?,
                idempotency_key: row.try_get("idempotency_key").map_err(|source| {
                    db_error("decode_run_control_event_key", run_id, source).to_string()
                })?,
                event_hash: row.try_get("event_hash").map_err(|source| {
                    db_error("decode_run_control_event_hash", run_id, source).to_string()
                })?,
                producer_pod_id: row.try_get("producer_pod_id").map_err(|source| {
                    db_error("decode_run_control_event_producer", run_id, source).to_string()
                })?,
                payload_json,
                payload,
            })
        })
        .collect()
}

fn recovered_run_control_event_is_exact(
    recovered: &RecoveredRunControlEvent,
    expected: &RunEventInsertRow,
) -> bool {
    recovered.id == expected.id
        && recovered.event_idx == expected.event_idx
        && recovered.event_type == expected.event_type
        && recovered.event_id == expected.event_id
        && recovered.idempotency_key == expected.idempotency_key.as_deref().unwrap_or_default()
        && recovered.event_hash == expected.event_hash
        && recovered.producer_pod_id == expected.producer_pod_id
        && recovered.payload_json == expected.payload_json
}

fn recovered_run_control_event_is_equivalent(
    recovered: &RecoveredRunControlEvent,
    expected_event: &serde_json::Value,
    expected_key: &str,
) -> bool {
    recovered.idempotency_key == expected_key
        && recovered.event_type == extract_event_type(expected_event)
        && recovered.event_hash == sha256_hex(recovered.payload_json.as_bytes())
        && run_events_have_same_immutable_payload(&recovered.payload, expected_event)
}

#[derive(Debug, PartialEq)]
enum InteractionCommitRecovery {
    ThisAttemptExact(serde_json::Value),
    EquivalentConcurrentWinner(serde_json::Value),
    Conflict(serde_json::Value),
    NotCommitted,
}

#[derive(Debug, PartialEq, Eq)]
enum InteractionBatchCommitRecovery {
    Exact,
    Missing { exact: usize, missing: usize },
    Conflict { idempotency_key: String },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RecoveredInteractionBatchFact {
    event_idx: i64,
    event_hash: String,
    registration_batch_id: Option<String>,
}

fn classify_interaction_batch_commit_recovery(
    expected: &[RunEventInsertRow],
    recovered: &HashMap<String, RecoveredInteractionBatchFact>,
) -> InteractionBatchCommitRecovery {
    let mut exact = 0usize;
    let mut missing = 0usize;
    for event in expected {
        let key = event
            .idempotency_key
            .as_deref()
            .expect("guarded interaction event has stable identity");
        match recovered.get(key) {
            Some(fact)
                if fact.event_hash == event.event_hash
                    && fact.event_idx == event.event_idx
                    && fact.registration_batch_id == event.request_id =>
            {
                exact += 1
            }
            Some(_) => {
                return InteractionBatchCommitRecovery::Conflict {
                    idempotency_key: key.to_string(),
                };
            }
            None => missing += 1,
        }
    }
    if exact == expected.len() {
        InteractionBatchCommitRecovery::Exact
    } else {
        InteractionBatchCommitRecovery::Missing { exact, missing }
    }
}

fn recovered_interaction_event_matches(
    recovered: &RecoveredInteractionEvent,
    expected: &RunEventInsertRow,
) -> bool {
    recovered.id == expected.id
        && recovered.run_id == expected.run_id
        && recovered.event_idx == expected.event_idx
        && recovered.user_id == expected.user_id
        && recovered.session_id == expected.session_id
        && recovered.event_type == expected.event_type
        && recovered.event_id == expected.event_id
        && recovered.agent_id == expected.agent_id
        && recovered.subject_run_id == expected.subject_run_id
        && recovered.interaction_request_id == expected.interaction_request_id
        && recovered.idempotency_key == expected.idempotency_key
        && recovered.event_hash == expected.event_hash
        && recovered.producer_pod_id == expected.producer_pod_id
        && recovered.payload_json == expected.payload_json
}

fn recovered_interaction_event_is_equivalent(
    recovered: &RecoveredInteractionEvent,
    expected: &RunEventInsertRow,
) -> bool {
    let Ok(expected_payload) = serde_json::from_str::<serde_json::Value>(&expected.payload_json)
    else {
        return false;
    };
    let Ok(recovered_payload) = serde_json::from_str::<serde_json::Value>(&recovered.payload_json)
    else {
        return false;
    };
    recovered.run_id == expected.run_id
        && recovered.user_id == expected.user_id
        && recovered.session_id == expected.session_id
        && recovered.event_type == expected.event_type
        && recovered.agent_id == expected.agent_id
        && recovered.subject_run_id == expected.subject_run_id
        && recovered.interaction_request_id == expected.interaction_request_id
        && recovered.idempotency_key == expected.idempotency_key
        && recovered.event_hash == sha256_hex(recovered.payload_json.as_bytes())
        && recovered.payload == recovered_payload
        && recovered_payload == expected_payload
}

fn classify_interaction_commit_recovery(
    run_status: &str,
    waiting_for: Option<&str>,
    run_last_event_idx: i64,
    run_session_id: &str,
    expected: &[RunEventInsertRow],
    recovered: &[RecoveredInteractionEvent],
) -> InteractionCommitRecovery {
    let Some(expected_terminal) = expected.first() else {
        return if recovered.is_empty() {
            InteractionCommitRecovery::NotCommitted
        } else {
            InteractionCommitRecovery::Conflict(recovered[0].payload.clone())
        };
    };
    let Some(terminal) = recovered
        .iter()
        .find(|event| event.event_type == expected_terminal.event_type)
    else {
        return if recovered.is_empty() {
            InteractionCommitRecovery::NotCommitted
        } else {
            InteractionCommitRecovery::Conflict(recovered[0].payload.clone())
        };
    };
    if expected.len() == 1 {
        if recovered.len() != 1
            || run_session_id != expected_terminal.session_id
            || run_last_event_idx < terminal.event_idx
        {
            return InteractionCommitRecovery::Conflict(terminal.payload.clone());
        }
        if recovered_interaction_event_matches(terminal, expected_terminal) {
            return InteractionCommitRecovery::ThisAttemptExact(terminal.payload.clone());
        }
        if recovered_interaction_event_is_equivalent(terminal, expected_terminal) {
            return InteractionCommitRecovery::EquivalentConcurrentWinner(terminal.payload.clone());
        }
        return InteractionCommitRecovery::Conflict(terminal.payload.clone());
    }
    let Some(expected_resume) = expected.get(1) else {
        return InteractionCommitRecovery::Conflict(terminal.payload.clone());
    };
    let Some(resume) = recovered
        .iter()
        .find(|event| event.event_type == expected_resume.event_type)
    else {
        return InteractionCommitRecovery::Conflict(terminal.payload.clone());
    };
    if expected.len() != 2 || recovered.len() != 2 {
        return InteractionCommitRecovery::Conflict(terminal.payload.clone());
    }
    let resumed = waiting_for.is_none()
        && run_status != STATUS_WAITING
        && run_session_id == expected_terminal.session_id
        && terminal.event_idx.checked_add(1) == Some(resume.event_idx)
        && run_last_event_idx >= resume.event_idx;
    if !resumed {
        return InteractionCommitRecovery::Conflict(terminal.payload.clone());
    }
    if recovered
        .iter()
        .zip(expected)
        .all(|(actual, expected)| recovered_interaction_event_matches(actual, expected))
    {
        return InteractionCommitRecovery::ThisAttemptExact(terminal.payload.clone());
    }
    if recovered_interaction_event_is_equivalent(terminal, expected_terminal)
        && recovered_interaction_event_is_equivalent(resume, expected_resume)
    {
        return InteractionCommitRecovery::EquivalentConcurrentWinner(terminal.payload.clone());
    }
    InteractionCommitRecovery::Conflict(terminal.payload.clone())
}

fn build_run_event_insert_row(
    user_id: &str,
    run_id: &str,
    session_id: &str,
    agent_id: Option<&str>,
    event_idx: i64,
    owner_pod_id: &str,
    event: &serde_json::Value,
) -> DbStoreResult<RunEventInsertRow> {
    let payload_json =
        serde_json::to_string(event).map_err(|source| DatabaseRunStateStoreError::Json {
            operation: "serialize_run_event",
            entity: run_id.to_string(),
            source,
        })?;
    let event_type = extract_event_type(event);
    let subject_run_id = matches!(event_type.as_str(), "agent_spawned")
        .then(|| extract_optional_string(event, "run_id"))
        .flatten();
    let interaction_request_id = extract_interaction_request_id(event);
    let event_id = extract_optional_string(event, "event_id")
        .or_else(|| extract_optional_string(event, "id"))
        .unwrap_or_else(|| Uuid::new_v4().to_string());
    let event_hash = sha256_hex(payload_json.as_bytes());
    let idempotency_key = extract_optional_string(event, "idempotency_key");

    Ok(RunEventInsertRow {
        id: Uuid::new_v4().to_string(),
        run_id: run_id.to_string(),
        event_idx,
        user_id: user_id.to_string(),
        session_id: session_id.to_string(),
        event_type,
        event_id,
        agent_id: agent_id.unwrap_or_default().to_string(),
        subject_run_id,
        interaction_request_id,
        idempotency_key,
        event_hash,
        producer_pod_id: owner_pod_id.to_string(),
        request_id: None,
        payload_json,
    })
}

/// Known client-facing event `type` values that are safe to surface
/// on the external `/chat/turn` SSE stream. Anything outside this
/// allowlist is dropped — it's either an internal diagnostic event
/// (e.g. `injection_freshness`) whose stability no external
/// consumer should depend on, or a future event that hasn't been
/// explicitly opted into the public surface.
///
/// wip-7 motivation: the pre-allowlist code path pass-through'd any
/// `{"type": ...}`-shaped event unchanged. wip-5's
/// `injection_freshness` event carried raw channel text for
/// observation purposes — that text leaked to any authenticated
/// `/chat/turn` client. The wip-7 bridge emits fingerprints only,
/// but the allowlist is the defence-in-depth so a future diagnostic
/// event can't accidentally leak either.
///
/// Adding a new public event: add its `type` string here AND, if the
/// event also arrives in `{"event_type": ..., "data": ...}` shape
/// from the journal, add a dedicated `match` arm below so the
/// transform shapes it consistently.
const EXTERNAL_CLIENT_ALLOWLIST: &[&str] = &[
    // Streaming assistant content.
    "text_delta",
    "text_done",
    "thinking_delta",
    "thinking_done",
    "reasoning_delta",
    "reasoning_done",
    "reasoning_message_content",
    // Tool-call lifecycle.
    "tool_call",
    "tool_call_start",
    "tool_call_end",
    "tool_request",
    "approval_required",
    "approval_batch_required",
    "user_prompt_required",
    // Run lifecycle + framing.
    "run_started",
    "run_error",
    "run_interrupted",
    "run_finished",
    "run_waiting",
    "run_blocked",
    "run_paused",
    "run_resumed",
    "runtime.control.handoff.requested",
    "runtime.control.handoff.rejected",
    "user_intent_accepted",
    "user_intent_applied",
    "user_intent_returned",
    "context_meta",
    "compaction",
    "session_info",
    "turn_complete",
    "turn_done",
    "user_input",
    "usage",
    "explain",
    "error",
    "ping",
    // Canonical, bounded post-ingest runtime observation. Clients consume the
    // server-authored frame instead of reconstructing it from progress,
    // usage, or terminal events.
    "runtime_feedback",
    // Work-surface execution binding and transport lifecycle.
    "workspace_bound",
    "executor_bound",
    "executor_status_changed",
    "tool_routing_decision",
    "tool_transport_started",
    "tool_transport_completed",
    "tool_transport_failed",
    // Plan / delegation surface (public admin features).
    "plan_created",
    "plan_step_start",
    "plan_step_done",
    "plan_revised",
    "agent_delegated",
    "agent_communication",
    "agent_spawned",
    "agent_live_event",
    "agent_progress",
    "agent_completed",
    "agent_failed",
    "agent_waiting",
    "agent_cancelled",
    "agent_interrupted",
    "task_board_snapshot",
    // Versioned canonical Work lifecycle projection. This is emitted only
    // after the corresponding Work mutation commits and drives the compact
    // live task board in every interactive client.
    "work_task_board_update",
    // Bounded execution-phase receipt used by Explain/trace projections.
    "turn_phase",
];

fn project_runtime_feedback(event: serde_json::Value) -> serde_json::Value {
    let Some(frame) = event
        .get("runtime_feedback")
        .filter(|frame| frame.is_object())
        .cloned()
    else {
        return serde_json::Value::Null;
    };
    serde_json::json!({
        "type": "runtime_feedback",
        "runtime_feedback": frame,
    })
}

fn insert_if_present(
    out: &mut serde_json::Map<String, serde_json::Value>,
    data: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) {
    if let Some(value) = data.get(key).cloned() {
        out.insert(key.to_string(), value);
    }
}

const EXTERNAL_EXECUTION_BOUNDARY_FIELDS: &[&str] = &[
    "workspace",
    "executor",
    "transport",
    "route",
    "status",
    "success",
    "duration_ms",
    "error_kind",
    "reason",
    "blocked",
    "skipped",
    "cancelled",
    "agent_id",
    "agent_status",
];

fn copy_execution_boundary_fields(
    out: &mut serde_json::Map<String, serde_json::Value>,
    data: &serde_json::Map<String, serde_json::Value>,
) {
    for key in EXTERNAL_EXECUTION_BOUNDARY_FIELDS {
        insert_if_present(out, data, key);
    }
}

fn is_external_client_event_type(event_type: &str) -> bool {
    EXTERNAL_CLIENT_ALLOWLIST.contains(&event_type)
}

fn run_error_client_surface(error_kind: &str) -> Option<(&'static str, bool, Option<u64>)> {
    match error_kind {
        "rate_limit" => Some(("LLM_RATE_LIMIT", true, Some(5_000))),
        "server_error" => Some(("SERVER_ERROR", true, Some(2_000))),
        "stream_idle" | "tool_timeout" => Some(("LLM_TIMEOUT", true, Some(0))),
        "stream_transport" => Some(("LLM_TRANSPORT_ERROR", true, Some(1_000))),
        "network" => Some(("LLM_TRANSPORT_ERROR", true, Some(3_000))),
        "budget_exhausted" => Some(("BUDGET_EXCEEDED", false, None)),
        "auth" => Some(("AUTH_ERROR", false, None)),
        "context_window" => Some(("CONTEXT_WINDOW_EXCEEDED", false, None)),
        "invalid_request" => Some(("LLM_INVALID_REQUEST", false, None)),
        "cancelled" => Some(("CANCELLED", false, None)),
        _ => None,
    }
}

fn data_string(data: &serde_json::Map<String, serde_json::Value>, key: &str) -> Option<String> {
    data.get(key)
        .and_then(serde_json::Value::as_str)
        .map(ToOwned::to_owned)
}

fn run_error_code_from_data(data: &serde_json::Map<String, serde_json::Value>) -> Option<String> {
    data_string(data, "error_code").or_else(|| data_string(data, "error_kind"))
}

fn run_error_code_from_event(event: &serde_json::Value) -> Option<String> {
    let event_type = event
        .get("event_type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    if event_type != "run_error" && event_type != "run_finished" {
        return None;
    }
    event
        .get("data")
        .and_then(serde_json::Value::as_object)
        .or_else(|| event.as_object())
        .and_then(run_error_code_from_data)
}

fn terminal_error_code_from_events(status: &str, events: &[serde_json::Value]) -> Option<String> {
    if status != STATUS_FAILED {
        return None;
    }
    events.iter().rev().find_map(run_error_code_from_event)
}

fn terminal_error_code_from_message(status: &str, error_message: Option<&str>) -> Option<String> {
    if status != STATUS_FAILED {
        return None;
    }
    let message = error_message?.trim();
    if message.is_empty() {
        return None;
    }
    Some(
        astra_core::ClassifiedError::from(message.to_string())
            .kind
            .as_str()
            .to_string(),
    )
}

fn terminal_error_code_from_transition(
    status: &str,
    error_message: Option<&str>,
    events: &[serde_json::Value],
) -> Option<String> {
    terminal_error_code_from_events(status, events)
        .or_else(|| terminal_error_code_from_message(status, error_message))
}

pub fn transform_run_event_for_client(event: serde_json::Value) -> serde_json::Value {
    // Already-client-ready shape (`{"type": ..., ...}`): allowlist the
    // `type` value. Drop anything not explicitly safe for external
    // consumption.
    if event
        .get("event_type")
        .and_then(serde_json::Value::as_str)
        .is_none()
        && let Some(client_type) = event.get("type").and_then(serde_json::Value::as_str)
    {
        let is_external = is_external_client_event_type(client_type);
        let is_tool_call_end = client_type == "tool_call_end";
        let is_work_task_board_update = client_type == "work_task_board_update";
        let is_turn_phase = client_type == "turn_phase";
        let is_runtime_feedback = client_type == "runtime_feedback";
        if is_external {
            return if is_tool_call_end {
                project_external_tool_call_end(event)
            } else if is_work_task_board_update {
                project_work_task_board_update(event)
            } else if is_turn_phase {
                project_turn_phase(event)
            } else if is_runtime_feedback {
                project_runtime_feedback(event)
            } else {
                event
            };
        }
        // Unknown / internal event — drop.
        return serde_json::Value::Null;
    }

    let event_type = event
        .get("event_type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let data = event
        .get("data")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .unwrap_or_default();

    match event_type {
        "text_delta" => serde_json::json!({
            "type": "text_delta",
            "content": data.get("chunk").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "assistant_delta" => serde_json::json!({
            "type": "text_delta",
            "content": data
                .get("text")
                .or_else(|| data.get("chunk"))
                .cloned()
                .unwrap_or(serde_json::Value::String(String::new())),
        }),
        "text_done" => serde_json::json!({
            "type": "text_done",
            "full_text": data.get("full_text").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "reasoning_message_content" => serde_json::json!({
            "type": "reasoning_message_content",
            "content": data.get("content").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "thinking_delta" => serde_json::json!({
            "type": "thinking_delta",
            "content": data.get("chunk").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "thinking_done" | "reasoning_done" => serde_json::json!({ "type": event_type }),
        "tool_call_start" => {
            let mut out = serde_json::Map::from_iter([(
                "type".to_string(),
                serde_json::Value::String("tool_call_start".to_string()),
            )]);
            out.insert(
                "tool".to_string(),
                data.get("tool")
                    .or_else(|| data.get("name"))
                    .cloned()
                    .unwrap_or(serde_json::Value::String(String::new())),
            );
            out.insert(
                "call_id".to_string(),
                data.get("call_id")
                    .or_else(|| data.get("tool_call_id"))
                    .cloned()
                    .unwrap_or(serde_json::Value::String(String::new())),
            );
            out.insert(
                "arguments".to_string(),
                data.get("arguments")
                    .or_else(|| data.get("args"))
                    .cloned()
                    .unwrap_or(serde_json::Value::Null),
            );
            copy_execution_boundary_fields(&mut out, &data);
            serde_json::Value::Object(out)
        }
        "tool_result" => {
            let mut out = serde_json::Map::from_iter([(
                "type".to_string(),
                serde_json::Value::String("tool_call_end".to_string()),
            )]);
            out.insert(
                "call_id".to_string(),
                data.get("call_id")
                    .or_else(|| data.get("tool_call_id"))
                    .cloned()
                    .unwrap_or(serde_json::Value::String(String::new())),
            );
            if let Some(tool) = data.get("tool").or_else(|| data.get("name")).cloned() {
                out.insert("tool".to_string(), tool);
            }
            let result = data
                .get("result")
                .or_else(|| data.get("output"))
                .cloned()
                .unwrap_or(serde_json::Value::String(String::new()));
            out.insert("result".to_string(), result);
            copy_explicit_artifacts(&mut out, &data);
            copy_execution_boundary_fields(&mut out, &data);
            project_external_tool_call_end(serde_json::Value::Object(out))
        }
        "run_started" => {
            let mut out = serde_json::json!({ "type": "run_started" });
            if let Some(obj) = out.as_object_mut() {
                if let Some(run_id) = data.get("run_id").cloned() {
                    obj.insert("run_id".to_string(), run_id);
                }
                if let Some(session_id) = data.get("session_id").cloned() {
                    obj.insert("session_id".to_string(), session_id);
                }
                if let Some(interaction_mode) = data.get("interaction_mode").cloned() {
                    obj.insert("interaction_mode".to_string(), interaction_mode);
                }
                if let Some(interactive_client) = data.get("interactive_client").cloned() {
                    obj.insert("interactive_client".to_string(), interactive_client);
                }
                if let Some(turn_intent_policy) = data.get("turn_intent_policy").cloned() {
                    obj.insert("turn_intent_policy".to_string(), turn_intent_policy);
                }
                if let Some(workspace) = data.get("workspace").cloned() {
                    obj.insert("workspace".to_string(), workspace);
                }
                if let Some(executor) = data.get("executor").cloned() {
                    obj.insert("executor".to_string(), executor);
                }
                if let Some(transport) = data.get("transport").cloned() {
                    obj.insert("transport".to_string(), transport);
                }
            }
            out
        }
        "run_finished" => {
            let mut out = serde_json::json!({ "type": "run_finished" });
            if let Some(obj) = out.as_object_mut() {
                for key in [
                    "run_id",
                    "status",
                    "outcome",
                    "finish_reason",
                    "error",
                    "error_code",
                    "error_kind",
                    "interrupted",
                    "interruption_kind",
                    "resumable",
                    "waiting_for",
                ] {
                    insert_if_present(obj, &data, key);
                }
            }
            out
        }
        "run_error" => {
            let message = data
                .get("error")
                .or_else(|| data.get("message"))
                .cloned()
                .unwrap_or(serde_json::Value::String("Unknown error".to_string()));
            let surface = data
                .get("error_kind")
                .and_then(serde_json::Value::as_str)
                .and_then(run_error_client_surface);
            let code = surface.map_or("RUN_ERROR", |(code, _, _)| code);
            let error_code = run_error_code_from_data(&data);
            let mut out = serde_json::Map::from_iter([
                (
                    "type".to_string(),
                    serde_json::Value::String("run_error".to_string()),
                ),
                ("message".to_string(), message.clone()),
                ("error".to_string(), message),
                (
                    "code".to_string(),
                    serde_json::Value::String(code.to_string()),
                ),
            ]);
            if let Some(error_code) = error_code {
                out.insert(
                    "error_code".to_string(),
                    serde_json::Value::String(error_code),
                );
            }
            if let Some((_, retryable, retry_after_ms)) = surface {
                out.insert("retryable".to_string(), serde_json::Value::Bool(retryable));
                if let Some(retry_after_ms) = retry_after_ms {
                    out.insert(
                        "retry_after_ms".to_string(),
                        serde_json::Value::from(retry_after_ms),
                    );
                }
            }
            for key in ["run_id", "error_kind", "reason", "blocked"] {
                insert_if_present(&mut out, &data, key);
            }
            serde_json::Value::Object(out)
        }
        "run_interrupted" => {
            let mut out = serde_json::Map::from_iter([(
                "type".to_string(),
                serde_json::Value::String("run_interrupted".to_string()),
            )]);
            for (k, v) in &data {
                out.insert(k.clone(), v.clone());
            }
            if !out.contains_key("message")
                && let Some(user_message) = data.get("user_message").cloned()
            {
                out.insert("message".to_string(), user_message);
            }
            serde_json::Value::Object(out)
        }
        "approval_request" | "approval_required" => {
            let mut out = serde_json::json!({ "type": "approval_required" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "tool_request" => {
            let mut out = serde_json::json!({ "type": "tool_request" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "ask_user_prompted" | "user_prompt_required" => {
            let mut out = serde_json::json!({ "type": "user_prompt_required" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "user_input" => {
            let mut out = serde_json::json!({ "type": "user_input" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        // Turn-completion events carry the authoritative assistant
        // text for client reconciliation (the streaming deltas may be
        // stale if the server recovered mid-turn). Pass through with
        // the full data payload merged into the client-shaped event.
        "turn_complete" | "turn_done" => {
            let mut out = serde_json::json!({ "type": event_type });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "context_meta" => {
            let mut out = serde_json::json!({ "type": "context_meta" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "compaction" => {
            let mut out = serde_json::json!({ "type": "compaction" });
            if let Some(obj) = out.as_object_mut() {
                for (key, value) in &data {
                    obj.insert(key.clone(), value.clone());
                }
            }
            out
        }
        "run_paused" => {
            // Pause/resume lifecycle events had been falling through
            // the `_` catch-all in pre-wip-7 code, which relied on
            // passthrough. wip-7's allowlist drops the catch-all, so
            // pause/resume need explicit arms — `run_handlers` also
            // injects `run_id` for these.
            let mut out = serde_json::json!({ "type": "run_paused" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "run_waiting" => {
            let mut out = serde_json::json!({ "type": "run_waiting" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "run_resumed" => {
            let mut out = serde_json::json!({ "type": "run_resumed" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "user_intent" => {
            let mut out = serde_json::json!({
                "type": "user_intent_accepted",
                "status": UserIntentStatus::AcceptedRemote,
            });
            if let Some(obj) = out.as_object_mut() {
                for key in ["intent_id", "delivery"] {
                    insert_if_present(obj, &data, key);
                }
            }
            out
        }
        "user_intent_applied" => {
            let mut out = serde_json::json!({ "type": "user_intent_applied" });
            if let Some(obj) = out.as_object_mut() {
                for key in ["intent_id", "delivery", "status", "event_index", "content"] {
                    insert_if_present(obj, &data, key);
                }
            }
            out
        }
        "user_intent_returned" => {
            let mut out = serde_json::json!({ "type": "user_intent_returned" });
            if let Some(obj) = out.as_object_mut() {
                for key in ["intent_id", "delivery", "status", "event_index", "content"] {
                    insert_if_present(obj, &data, key);
                }
            }
            out
        }
        "run_blocked" => {
            let mut out = serde_json::json!({ "type": "run_blocked" });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "plan_created" => serde_json::json!({
            "type": "plan_created",
            "plan": data.get("plan").cloned().unwrap_or(serde_json::json!({})),
        }),
        "plan_step_start" => serde_json::json!({
            "type": "plan_step_start",
            "step": data.get("step").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "plan_step_done" => serde_json::json!({
            "type": "plan_step_done",
            "step": data.get("step").cloned().unwrap_or(serde_json::Value::String(String::new())),
            "result": data.get("result").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "plan_revised" => serde_json::json!({
            "type": "plan_revised",
            "plan": data.get("plan").cloned().unwrap_or(serde_json::json!({})),
        }),
        "agent_delegated" => serde_json::json!({
            "type": "agent_delegated",
            "agent_id": data.get("agent_id").cloned().unwrap_or(serde_json::Value::String(String::new())),
            "task": data.get("task").cloned().unwrap_or(serde_json::Value::String(String::new())),
        }),
        "agent_communication"
        | "agent_spawned"
        | "agent_progress"
        | "agent_completed"
        | "agent_failed"
        | "agent_waiting"
        | "agent_cancelled"
        | "agent_interrupted" => {
            let mut out = serde_json::json!({ "type": event_type });
            if let Some(obj) = out.as_object_mut() {
                for (k, v) in &data {
                    obj.insert(k.clone(), v.clone());
                }
            }
            out
        }
        "work_task_board_update" => {
            // Keep the task board an explicit public protocol surface rather
            // than relying on the raw-event pass-through used by the live
            // lane. Durable replay arrives as `event_type` + `data`, and must
            // reconstruct exactly the same shape for reconnecting clients.
            project_work_task_board_update(serde_json::Value::Object(data))
        }
        "turn_phase" => project_turn_phase(serde_json::Value::Object(data)),
        "keepalive" => serde_json::json!({ "type": "ping" }),
        _ => {
            // wip-7 allowlist: unknown internal event_types are
            // dropped. Adding a new event type means adding it
            // explicitly above (and, for client-facing events,
            // adding its `type` to `EXTERNAL_CLIENT_ALLOWLIST`).
            serde_json::Value::Null
        }
    }
}

/// The live Work board is a bounded, versioned protocol receipt. Project its
/// small public schema explicitly so an internal extension cannot become a
/// new client field merely because it shares the `type` envelope.
fn project_work_task_board_update(event: serde_json::Value) -> serde_json::Value {
    let Some(source) = event.as_object() else {
        return serde_json::Value::Null;
    };
    let Some(task_board_update) = source.get("task_board_update").cloned() else {
        return serde_json::Value::Null;
    };

    let mut out = serde_json::Map::from_iter([(
        "type".to_string(),
        serde_json::Value::String("work_task_board_update".to_string()),
    )]);
    for key in ["session_id", "tool_call_id"] {
        insert_if_present(&mut out, source, key);
    }
    out.insert("task_board_update".to_string(), task_board_update);
    serde_json::Value::Object(out)
}

/// A phase receipt is intentionally smaller than an arbitrary diagnostic. It
/// has no prompt, model, tool output, or provider detail; those remain in the
/// correlated trace/log record. Keeping the replay and live shape identical
/// makes Explain trustworthy after reconnect as well as during a live turn.
fn project_turn_phase(event: serde_json::Value) -> serde_json::Value {
    let Some(source) = event.as_object() else {
        return serde_json::Value::Null;
    };
    let payload = serde_json::Map::from_iter([
        (
            "schema_version".to_string(),
            source.get("schema_version").cloned().unwrap_or_default(),
        ),
        (
            "phase".to_string(),
            source.get("phase").cloned().unwrap_or_default(),
        ),
        (
            "round_index".to_string(),
            source.get("round_index").cloned().unwrap_or_default(),
        ),
        (
            "attempt_index".to_string(),
            source
                .get("attempt_index")
                .cloned()
                .unwrap_or_else(|| serde_json::json!(0)),
        ),
        (
            "outcome".to_string(),
            source.get("outcome").cloned().unwrap_or_default(),
        ),
        (
            "duration_ms".to_string(),
            source.get("duration_ms").cloned().unwrap_or_default(),
        ),
    ]);
    let Ok(receipt) = serde_json::from_value::<astra_turn_types::TurnPhaseReceiptV1>(
        serde_json::Value::Object(payload),
    ) else {
        return serde_json::Value::Null;
    };
    if !receipt.is_valid() {
        return serde_json::Value::Null;
    }
    serde_json::json!({
        "type": astra_turn_types::TURN_PHASE_EVENT_TYPE,
        "schema_version": receipt.schema_version,
        "phase": receipt.phase,
        "round_index": receipt.round_index,
        "attempt_index": receipt.attempt_index,
        "outcome": receipt.outcome,
        "duration_ms": receipt.duration_ms,
    })
}

const EXTERNAL_TOOL_EVENT_MAX_BYTES: usize = 64 * 1024;
const EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES: usize = 48 * 1024;
const EXTERNAL_TOOL_RESULT_PREVIEW_MAX_BYTES: usize = 8 * 1024;
const EXTERNAL_TOOL_ARGUMENTS_INLINE_MAX_BYTES: usize = 8 * 1024;
const EXTERNAL_TOOL_ARGUMENTS_PREVIEW_MAX_BYTES: usize = 2 * 1024;

fn project_external_tool_call_end(event: serde_json::Value) -> serde_json::Value {
    let original_event_bytes = encoded_json_len(&event);
    let original_event_sha256 = sha256_hex(
        serde_json::to_string(&event)
            .expect("serializing a serde_json::Value must not fail")
            .as_bytes(),
    );
    let Some(source) = event.as_object() else {
        return event;
    };

    let mut out = serde_json::Map::from_iter([(
        "type".to_string(),
        serde_json::Value::String("tool_call_end".to_string()),
    )]);
    for key in ["call_id", "tool"]
        .into_iter()
        .chain(EXTERNAL_EXECUTION_BOUNDARY_FIELDS.iter().copied())
    {
        if let Some(value) = source.get(key) {
            out.insert(key.to_string(), value.clone());
        }
    }
    copy_explicit_artifacts(&mut out, source);

    if let Some(result) = source.get("result").or_else(|| source.get("output")) {
        let (result, evidence) = project_external_tool_result(result.clone());
        out.insert("result".to_string(), result);
        if let Some((original_bytes, content_sha256)) = evidence {
            out.insert(
                "result_truncated".to_string(),
                serde_json::Value::Bool(true),
            );
            out.insert(
                "result_bytes".to_string(),
                serde_json::json!(original_bytes),
            );
            out.insert(
                "result_sha256".to_string(),
                serde_json::Value::String(content_sha256.clone()),
            );
            out.insert(
                "result_integrity".to_string(),
                serde_json::json!({
                    "content_sha256": content_sha256,
                    "sha256_encoding": "json",
                }),
            );
        }
    }
    if let Some(arguments) = source.get("arguments").or_else(|| source.get("args")) {
        out.insert(
            "arguments".to_string(),
            project_external_tool_arguments(arguments.clone()),
        );
    }

    if (source.contains_key("result") && source.contains_key("output"))
        || source.contains_key("structuredContent")
    {
        out.insert(
            "payload_truncated".to_string(),
            serde_json::Value::Bool(true),
        );
        out.insert(
            "event_bytes".to_string(),
            serde_json::json!(original_event_bytes),
        );
    }

    let mut projected = serde_json::Value::Object(out);
    if encoded_json_len(&projected) > EXTERNAL_TOOL_EVENT_MAX_BYTES {
        let call_id = source
            .get("call_id")
            .and_then(serde_json::Value::as_str)
            .map(|value| truncate_utf8_bytes(value, 1024))
            .unwrap_or_default();
        let tool = source
            .get("tool")
            .and_then(serde_json::Value::as_str)
            .map(|value| truncate_utf8_bytes(value, 1024))
            .unwrap_or_default();
        let projected_result = projected.get("result").cloned();
        let projected_arguments = projected.get("arguments").cloned();
        let projected_status = bounded_terminal_scalar(projected.get("status").cloned());
        let projected_success = bounded_terminal_scalar(projected.get("success").cloned());
        let projected_duration_ms = bounded_terminal_scalar(projected.get("duration_ms").cloned());
        let projected_error_kind = bounded_terminal_scalar(projected.get("error_kind").cloned());
        let mut fallback = serde_json::json!({
            "type": "tool_call_end",
            "call_id": call_id,
            "tool": tool,
            "payload_truncated": true,
            "event_bytes": original_event_bytes,
            "event_sha256": original_event_sha256,
        });
        let fallback_obj = fallback
            .as_object_mut()
            .expect("tool terminal fallback is an object");
        for (key, value) in [
            ("result", projected_result),
            ("arguments", projected_arguments),
            ("status", projected_status),
            ("success", projected_success),
            ("duration_ms", projected_duration_ms),
            ("error_kind", projected_error_kind),
        ] {
            if let Some(value) = value {
                fallback_obj.insert(key.to_string(), value);
            }
        }
        projected = fallback;
    }
    assert!(
        encoded_json_len(&projected) <= EXTERNAL_TOOL_EVENT_MAX_BYTES,
        "external tool event projection exceeded its hard byte limit"
    );
    projected
}

fn copy_explicit_artifacts(
    out: &mut serde_json::Map<String, serde_json::Value>,
    source: &serde_json::Map<String, serde_json::Value>,
) {
    if let Some(artifacts) = source
        .get("artifacts")
        .and_then(crate::external_artifacts::project_external_artifacts)
    {
        out.insert("artifacts".to_string(), artifacts);
    }
}

fn project_external_tool_result(
    result: serde_json::Value,
) -> (serde_json::Value, Option<(usize, String)>) {
    let encoded =
        serde_json::to_string(&result).expect("serializing a serde_json::Value must not fail");
    if encoded.len() <= EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES {
        return (result, None);
    }

    let original_bytes = encoded.len();
    let content_sha256 = sha256_hex(encoded.as_bytes());
    if let Some(projected) =
        project_external_lifecycle_result(&result, original_bytes, content_sha256.as_str())
    {
        return (projected, Some((original_bytes, content_sha256)));
    }
    let preview = truncate_utf8_bytes(&encoded, EXTERNAL_TOOL_RESULT_PREVIEW_MAX_BYTES);
    (
        serde_json::json!({
            "type": "astra.external_tool_result_summary.v1",
            "truncated": true,
            "original_bytes": original_bytes,
            "content_sha256": content_sha256,
            "preview": preview,
        }),
        Some((original_bytes, content_sha256)),
    )
}

/// Preserve bounded control identity when a large structured tool result is
/// projected onto the external SSE surface. A generic byte preview is useful
/// for data tools, but it is insufficient for lifecycle tools: clients must
/// still be able to identify and control the accepted Work unit. Selection is
/// driven by the versioned Work observation, not by tool names or prose.
fn project_external_lifecycle_result(
    result: &serde_json::Value,
    original_bytes: usize,
    content_sha256: &str,
) -> Option<serde_json::Value> {
    let parsed = match result {
        serde_json::Value::String(output) => serde_json::from_str(output).ok()?,
        serde_json::Value::Object(_) => result.clone(),
        _ => return None,
    };
    let observation = parsed
        .get(astra_core::work_unit::WORK_UNIT_OBSERVATION_FIELD)
        .and_then(|value| {
            serde_json::from_value::<astra_core::work_unit::WorkUnitObservation>(value.clone()).ok()
        })
        .filter(astra_core::work_unit::WorkUnitObservation::is_valid)?;

    let mut compact = serde_json::Map::from_iter([
        (
            "type".to_string(),
            serde_json::Value::String("astra.external_tool_lifecycle_summary.v1".to_string()),
        ),
        (
            astra_core::work_unit::WORK_UNIT_OBSERVATION_FIELD.to_string(),
            observation.to_value(),
        ),
        ("truncated".to_string(), serde_json::Value::Bool(true)),
        (
            "original_bytes".to_string(),
            serde_json::json!(original_bytes),
        ),
        (
            "content_sha256".to_string(),
            serde_json::Value::String(content_sha256.to_string()),
        ),
    ]);
    for key in [
        "status",
        "agent_id",
        "run_id",
        "group_id",
        "title",
        "target_count",
        "transcript_location",
        "parent_run_id",
    ] {
        if let Some(value) = bounded_terminal_scalar(parsed.get(key).cloned()) {
            compact.insert(key.to_string(), value);
        }
    }
    if encoded_json_len(&serde_json::Value::Object(compact.clone()))
        > EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES
    {
        // A syntactically valid observation may contain future extension
        // fields. Treat its byte size as untrusted input and fall back to the
        // generic bounded projection rather than exporting an oversized
        // lifecycle event to every subscriber of this run.
        return None;
    }
    // Membership is small in normal operation (fanout target_count is
    // bounded), but never let an extension turn this projection into an
    // unbounded event. Deliverables/results are intentionally not copied.
    for key in ["agents", "fanout"] {
        let Some(value) = parsed.get(key).cloned() else {
            continue;
        };
        compact.insert(key.to_string(), value);
        if encoded_json_len(&serde_json::Value::Object(compact.clone()))
            > EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES
        {
            compact.remove(key);
            compact.insert(
                "control_membership_omitted".to_string(),
                serde_json::Value::String("oversized".to_string()),
            );
            break;
        }
    }
    let compact = serde_json::Value::Object(compact);
    debug_assert!(encoded_json_len(&compact) <= EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES);
    Some(compact)
}

fn project_external_tool_arguments(arguments: serde_json::Value) -> serde_json::Value {
    let encoded = serde_json::to_string(&arguments)
        .expect("serializing tool arguments from a serde_json::Value must not fail");
    if encoded.len() <= EXTERNAL_TOOL_ARGUMENTS_INLINE_MAX_BYTES {
        return arguments;
    }
    serde_json::json!({
        "type": "astra.external_tool_arguments_summary.v1",
        "truncated": true,
        "original_bytes": encoded.len(),
        "preview": truncate_utf8_bytes(&encoded, EXTERNAL_TOOL_ARGUMENTS_PREVIEW_MAX_BYTES),
    })
}

fn encoded_json_len(value: &serde_json::Value) -> usize {
    serde_json::to_vec(value)
        .expect("serializing a serde_json::Value must not fail")
        .len()
}

fn bounded_terminal_scalar(value: Option<serde_json::Value>) -> Option<serde_json::Value> {
    match value? {
        serde_json::Value::String(value) => {
            Some(serde_json::Value::String(truncate_utf8_bytes(&value, 1024)))
        }
        value @ (serde_json::Value::Bool(_) | serde_json::Value::Number(_)) => Some(value),
        serde_json::Value::Null | serde_json::Value::Array(_) | serde_json::Value::Object(_) => {
            None
        }
    }
}

