    fn execution_owner_cancel_request(
        run_id: &str,
        owner_generation: u64,
    ) -> AtomicExecutionOwnerCancellationRequest<'_> {
        AtomicExecutionOwnerCancellationRequest {
            user_id: "u1",
            run_id,
            expected_session_id: "s1",
            expected_owner_generation: owner_generation,
            expected_statuses: &[STATUS_RUNNING, STATUS_WAITING, STATUS_PAUSED],
            origin: ExecutionOwnerCancellationOrigin::Runtime,
            reason: "deterministic runtime stop",
        }
    }

    fn durable_child_run_record(run_id: &str, root_run_id: &str) -> DurableRunRecord {
        let mut run = durable_run_record(run_id);
        run.parent_run_id = Some(root_run_id.to_string());
        run.root_run_id = Some(root_run_id.to_string());
        run.ancestor_path = Some(format!("{root_run_id}/{run_id}"));
        run.depth = 1;
        run
    }

    #[tokio::test]
    async fn in_memory_exact_live_owner_cancellation_is_one_terminal_commit() {
        let store = InMemoryRunStateStore::new()
            .with_execution_owner("cancel-owner", Duration::from_secs(60));
        let mut run = durable_run_record("cancel-live");
        run.run_generation = 7;
        store.insert_run(run).await.unwrap();

        assert_eq!(
            store
                .cancel_if_exact_live_owner(execution_owner_cancel_request("cancel-live", 7))
                .await
                .unwrap(),
            AtomicExecutionOwnerCancellation::Committed
        );
        assert_eq!(
            store
                .cancel_if_exact_live_owner(execution_owner_cancel_request("cancel-live", 7))
                .await
                .unwrap(),
            AtomicExecutionOwnerCancellation::SupersededTerminal {
                status: STATUS_CANCELLED.to_string(),
                owner_generation: 7,
            }
        );

        let runs = store.runs.read().await;
        let durable = &runs["cancel-live"];
        assert_eq!(durable.status, STATUS_CANCELLED);
        assert!(durable.owner_pod_id.is_none());
        assert!(durable.owner_lease_expires_at.is_none());
        let terminal = durable.events.last().unwrap();
        assert_eq!(extract_event_type(terminal), "run_finished");
        assert_eq!(
            terminal
                .pointer("/data/cancellation_origin")
                .and_then(serde_json::Value::as_str),
            Some("runtime")
        );
        assert_eq!(store.load_run_call_count(), 0);
    }

    #[tokio::test]
    async fn in_memory_execution_owner_cancellation_rejects_wrong_pod_generation_and_lease() {
        let store = InMemoryRunStateStore::new()
            .with_execution_owner("cancel-owner", Duration::from_secs(60));
        let mut run = durable_run_record("cancel-fenced");
        run.run_generation = 11;
        store.insert_run(run).await.unwrap();
        store
            .runs
            .write()
            .await
            .get_mut("cancel-fenced")
            .unwrap()
            .owner_pod_id = Some("foreign-owner".to_string());

        assert!(matches!(
            store
                .cancel_if_exact_live_owner(execution_owner_cancel_request("cancel-fenced", 11))
                .await
                .unwrap(),
            AtomicExecutionOwnerCancellation::NotOwnedActive { .. }
        ));
        store
            .runs
            .write()
            .await
            .get_mut("cancel-fenced")
            .unwrap()
            .owner_pod_id = Some("cancel-owner".to_string());
        assert!(matches!(
            store
                .cancel_if_exact_live_owner(execution_owner_cancel_request("cancel-fenced", 10))
                .await
                .unwrap(),
            AtomicExecutionOwnerCancellation::NotOwnedActive { .. }
        ));
        store
            .runs
            .write()
            .await
            .get_mut("cancel-fenced")
            .unwrap()
            .owner_lease_expires_at = Some("1970-01-01T00:00:00Z".to_string());
        assert!(matches!(
            store
                .cancel_if_exact_live_owner(execution_owner_cancel_request("cancel-fenced", 11))
                .await
                .unwrap(),
            AtomicExecutionOwnerCancellation::NotOwnedActive { .. }
        ));
        let runs = store.runs.read().await;
        let durable = &runs["cancel-fenced"];
        assert_eq!(durable.status, STATUS_RUNNING);
        assert!(durable.events.is_empty());
        assert_eq!(store.load_run_call_count(), 0);
    }

