    async fn setup_database_run_state_store_it() -> (DatabaseRunStateStore, astra_core::SharedPool)
    {
        let _ = dotenvy::dotenv();
        assert_eq!(
            std::env::var("ASTRA_TEST_DB_IT").as_deref(),
            Ok("1"),
            "set ASTRA_TEST_DB_IT=1 for ignored integration tests"
        );
        let settings = MATRIXONE_RUN_STORE_BOOTSTRAP
            .get_or_init(|| async {
                let mut settings = astra_core::MatrixOneSettings::from_env();
                settings.db_pool_max_connections = settings.db_pool_max_connections.min(8);
                settings.db_pool_min_connections = settings
                    .db_pool_min_connections
                    .min(settings.db_pool_max_connections);
                // These integration tests validate transaction correctness under
                // contention, not production overload admission. Keep the pool
                // deliberately small, but leave enough of the 30-second nextest
                // budget for queued operations to acquire one of its eight slots.
                settings.db_pool_acquire_timeout_secs =
                    settings.db_pool_acquire_timeout_secs.max(15);
                let catalog = std::env::var("ASTRA_DATABASE_BOOTSTRAP_CATALOG")
                    .unwrap_or_else(|_| "mysql".to_string());
                crate::storage::ensure_core_schema(&settings, &catalog)
                    .await
                    .expect("ensure_core_schema");
                settings
            })
            .await
            .clone();
        let pool = astra_core::SharedPool::new(&settings)
            .await
            .expect("SharedPool::new");
        (
            DatabaseRunStateStore::new(pool.clone()).with_owner_pod_id("runs-it-pod"),
            pool,
        )
    }

