    async fn database_session_lock_wait_timeout(connection: &mut sqlx::MySqlConnection) -> i64 {
        let raw: String = sqlx::query_scalar("SELECT @@session.lock_wait_timeout")
            .fetch_one(connection)
            .await
            .expect("read MatrixOne session lock timeout");
        raw.parse()
            .expect("MatrixOne session lock timeout must be an integer")
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_run_control_reuses_connection_and_restores_lock_wait_timeout_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let nonce = Uuid::new_v4();
        let user_id = format!("run-control-reuse-u-{nonce}");
        let session_id = format!("run-control-reuse-s-{nonce}");
        let run_id = format!("run-control-reuse-r-{nonce}");
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert reusable run");

        // Saturate every other pool slot so both the API and the assertion
        // must use this exact physical connection. Replacing it after every
        // request would expose the server default instead of the seeded value.
        let max_connections = pool.stats().max_connections as usize;
        assert!(max_connections > 0);
        let mut held = Vec::with_capacity(max_connections);
        for _ in 0..max_connections {
            held.push(
                tokio::time::timeout(Duration::from_secs(5), pool.get().acquire())
                    .await
                    .expect("acquire shared-pool connection before test deadline")
                    .expect("acquire shared-pool connection"),
            );
        }
        let mut target = held.pop().expect("one target connection");
        let original = database_session_lock_wait_timeout(&mut target).await;
        let seeded = if original == 17 { 117 } else { 17 };
        target
            .execute(format!("SET SESSION lock_wait_timeout = {seeded}").as_str())
            .await
            .expect("seed target session setting");
        drop(target);

        assert!(
            store
                .request_run_cancellation(&user_id, &run_id)
                .await
                .expect("persist cancellation through the sole idle checkout")
        );
        let mut reused = tokio::time::timeout(Duration::from_secs(5), pool.get().acquire())
            .await
            .expect("reacquire before deadline")
            .expect("reacquire exact shared-pool checkout");
        let observed = database_session_lock_wait_timeout(&mut reused).await;
        assert_eq!(observed, seeded, "request path leaked its bounded setting");
        reused
            .execute(format!("SET SESSION lock_wait_timeout = {original}").as_str())
            .await
            .expect("restore fixture session setting");
        drop(reused);
        drop(held);

        assert!(
            store
                .clone()
                .with_cancellation_marker_commit_ack_loss_once()
                .request_run_cancellation(&user_id, &run_id)
                .await
                .expect("reconcile cancellation marker commit acknowledgement")
        );
        sqlx::query(
            "DELETE FROM agent_session_execution_slots WHERE user_id = ? AND session_id = ?",
        )
        .bind(&user_id)
        .bind(&session_id)
        .execute(pool.get())
        .await
        .expect("clean reusable execution slot");
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
            .bind(&user_id)
            .bind(&session_id)
            .execute(pool.get())
            .await
            .expect("clean reusable session");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_execution_owner_cancellation_timeout_isolated_from_unrelated_session_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let nonce = Uuid::new_v4();
        let user_a = format!("owner-cancel-blocked-u-{nonce}");
        let session_a = format!("owner-cancel-blocked-s-{nonce}");
        let run_a = format!("owner-cancel-blocked-r-{nonce}");
        let user_b = format!("owner-cancel-unrelated-u-{nonce}");
        let session_b = format!("owner-cancel-unrelated-s-{nonce}");
        let run_b = format!("owner-cancel-unrelated-r-{nonce}");
        for (user_id, session_id, run_id, generation) in [
            (&user_a, &session_a, &run_a, 31_u64),
            (&user_b, &session_b, &run_b, 41_u64),
        ] {
            insert_active_database_session_fixture(&pool, user_id, session_id).await;
            let mut run = durable_run_record(run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            run.run_generation = generation;
            store.insert_run(run).await.expect("insert owned run");
        }
        let blocked_baseline = store.load_run(&user_a, &run_a).await.unwrap().unwrap();

        let mut blocker = pool.get().begin().await.expect("begin exact-row blocker");
        sqlx::query(
            "SELECT run_id FROM agent_runs WHERE user_id = ? AND session_id = ? AND run_id = ? FOR UPDATE",
        )
        .bind(&user_a)
        .bind(&session_a)
        .bind(&run_a)
        .fetch_one(&mut *blocker)
        .await
        .expect("lock only the blocked run row");

        // Leave precisely two shared-pool checkouts for the two run-control
        // calls. Unique session settings prove both healthy protocol sessions
        // survive and are reset even when one receives a server lock timeout.
        let max_connections = pool.stats().max_connections as usize;
        assert!(
            max_connections >= 3,
            "concurrency regression needs three pool slots"
        );
        let mut held = Vec::with_capacity(max_connections - 1);
        for _ in 0..(max_connections - 1) {
            held.push(
                tokio::time::timeout(Duration::from_secs(5), pool.get().acquire())
                    .await
                    .expect("acquire shared-pool connection before deadline")
                    .expect("acquire shared-pool connection"),
            );
        }
        let mut worker_a = held.pop().expect("first run-control worker");
        let mut worker_b = held.pop().expect("second run-control worker");
        let original_a = database_session_lock_wait_timeout(&mut worker_a).await;
        let original_b = database_session_lock_wait_timeout(&mut worker_b).await;
        let seeded_a = if original_a == 17 { 117 } else { 17 };
        let seeded_b = if original_b == 19 || seeded_a == 19 {
            119
        } else {
            19
        };
        worker_a
            .execute(format!("SET SESSION lock_wait_timeout = {seeded_a}").as_str())
            .await
            .expect("seed first worker");
        worker_b
            .execute(format!("SET SESSION lock_wait_timeout = {seeded_b}").as_str())
            .await
            .expect("seed second worker");
        drop(worker_a);
        drop(worker_b);

        let blocked_store = store.clone();
        let blocked_user = user_a.clone();
        let blocked_session = session_a.clone();
        let blocked_run = run_a.clone();
        let blocked = tokio::spawn(async move {
            let started = tokio::time::Instant::now();
            let outcome = blocked_store
                .cancel_if_exact_live_owner(AtomicExecutionOwnerCancellationRequest {
                    user_id: &blocked_user,
                    run_id: &blocked_run,
                    expected_session_id: &blocked_session,
                    expected_owner_generation: 31,
                    expected_statuses: &[STATUS_RUNNING, STATUS_WAITING, STATUS_PAUSED],
                    origin: ExecutionOwnerCancellationOrigin::Runtime,
                    reason: "bounded locked-row regression",
                })
                .await;
            (started.elapsed(), outcome)
        });
        tokio::time::sleep(Duration::from_millis(150)).await;
        assert!(
            !blocked.is_finished(),
            "blocked run did not reach its row fence"
        );

        let unrelated_started = tokio::time::Instant::now();
        let unrelated = tokio::time::timeout(
            Duration::from_secs(2),
            store.cancel_if_exact_live_owner(AtomicExecutionOwnerCancellationRequest {
                user_id: &user_b,
                run_id: &run_b,
                expected_session_id: &session_b,
                expected_owner_generation: 41,
                expected_statuses: &[STATUS_RUNNING, STATUS_WAITING, STATUS_PAUSED],
                origin: ExecutionOwnerCancellationOrigin::Unverified,
                reason: "unrelated-session regression",
            }),
        )
        .await
        .expect("unrelated session must not inherit the blocked row wait")
        .expect("unrelated execution-owner cancellation");
        assert_eq!(unrelated, AtomicExecutionOwnerCancellation::Committed);
        assert!(unrelated_started.elapsed() < Duration::from_secs(2));

        let (blocked_elapsed, blocked_outcome) =
            tokio::time::timeout(Duration::from_secs(6), blocked)
                .await
                .expect("absolute run-control deadline")
                .expect("join blocked cancellation");
        assert!(
            blocked_outcome.is_err(),
            "locked row cannot commit cancellation"
        );
        assert!(
            blocked_elapsed >= Duration::from_secs(2)
                && blocked_elapsed < RUN_CONTROL_DB_ATTEMPT_TIMEOUT,
            "server lock wait must be bounded inside the absolute deadline: {blocked_elapsed:?}"
        );

        let mut restored = Vec::with_capacity(2);
        for _ in 0..2 {
            restored.push(
                tokio::time::timeout(Duration::from_secs(5), pool.get().acquire())
                    .await
                    .expect("reacquire run-control worker before deadline")
                    .expect("reacquire run-control worker"),
            );
        }
        let mut observed = Vec::with_capacity(2);
        for connection in &mut restored {
            observed.push(database_session_lock_wait_timeout(connection).await);
        }
        observed.sort_unstable();
        let mut expected = vec![seeded_a, seeded_b];
        expected.sort_unstable();
        assert_eq!(
            observed, expected,
            "a run-control checkout churned or leaked setting"
        );
        for connection in &mut restored {
            let value = database_session_lock_wait_timeout(connection).await;
            let original = if value == seeded_a {
                original_a
            } else if value == seeded_b {
                original_b
            } else {
                panic!("unexpected restored worker setting {value}");
            };
            connection
                .execute(format!("SET SESSION lock_wait_timeout = {original}").as_str())
                .await
                .expect("restore worker fixture setting");
        }
        drop(restored);
        blocker.rollback().await.expect("release blocked run row");
        drop(held);

        let still_active = store.load_run(&user_a, &run_a).await.unwrap().unwrap();
        assert_eq!(still_active.status, STATUS_RUNNING);
        assert_eq!(
            still_active.events, blocked_baseline.events,
            "blocked transaction changed the canonical event stream"
        );
        assert_eq!(still_active.last_event_idx, blocked_baseline.last_event_idx);
        let cancelled = store.load_run(&user_b, &run_b).await.unwrap().unwrap();
        assert_eq!(cancelled.status, STATUS_CANCELLED);
        assert_eq!(
            cancelled.events.last().unwrap()["event_type"],
            "run_finished"
        );
        let projection = store
            .load_run_projection(&user_b, &run_b)
            .await
            .expect("load unrelated cancellation projection")
            .expect("unrelated cancellation projection exists");
        assert_eq!(projection.status, STATUS_CANCELLED);
        assert_eq!(projection.projection_event_idx, cancelled.last_event_idx);
        assert_eq!(
            projection.latest_event_type.as_deref(),
            Some("run_finished")
        );
        assert_eq!(
            store
                .cancel_if_exact_live_owner(AtomicExecutionOwnerCancellationRequest {
                    user_id: &user_a,
                    run_id: &run_a,
                    expected_session_id: &session_a,
                    expected_owner_generation: 31,
                    expected_statuses: &[STATUS_RUNNING, STATUS_WAITING, STATUS_PAUSED],
                    origin: ExecutionOwnerCancellationOrigin::Runtime,
                    reason: "retry after bounded lock release",
                })
                .await
                .expect("retry exact live owner after lock release"),
            AtomicExecutionOwnerCancellation::Committed
        );

        for (user_id, session_id, run_id) in
            [(&user_a, &session_a, &run_a), (&user_b, &session_b, &run_b)]
        {
            sqlx::query(
                "DELETE FROM agent_session_execution_slots WHERE user_id = ? AND session_id = ?",
            )
            .bind(user_id)
            .bind(session_id)
            .execute(pool.get())
            .await
            .expect("clean execution slot");
            cleanup_database_run_fixture(&pool, user_id, run_id).await;
            sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
                .bind(user_id)
                .bind(session_id)
                .execute(pool.get())
                .await
                .expect("clean run-control session");
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_root_user_marker_linearizes_before_remote_child_runtime_cancellation() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let nonce = Uuid::new_v4();
        let user_id = format!("root-child-cancel-u-{nonce}");
        let session_id = format!("root-child-cancel-s-{nonce}");
        let root_run_id = format!("root-child-cancel-root-{nonce}");
        let child_run_id = format!("root-child-cancel-child-{nonce}");
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut root = durable_run_record(&root_run_id);
        root.user_id = user_id.clone();
        root.session_id = session_id.clone();
        store.insert_run(root).await.expect("insert root run");
        let mut child = durable_child_run_record(&child_run_id, &root_run_id);
        child.user_id = user_id.clone();
        child.session_id = session_id.clone();
        child.run_generation = 7;
        store.insert_run(child).await.expect("insert child run");
        let child_baseline = store
            .load_run(&user_id, &child_run_id)
            .await
            .unwrap()
            .unwrap();

        let mut marker_tx = pool.get().begin().await.expect("begin root marker");
        assert_eq!(
            sqlx::query(
                "UPDATE agent_runs
                 SET cancellation_requested_at = NOW(6), updated_at = NOW(6)
                 WHERE user_id = ? AND run_id = ? AND status = 'running'",
            )
            .bind(&user_id)
            .bind(&root_run_id)
            .execute(&mut *marker_tx)
            .await
            .expect("stage root marker")
            .rows_affected(),
            1
        );

        let cancel_store = store.clone();
        let cancel_user = user_id.clone();
        let cancel_session = session_id.clone();
        let cancel_child = child_run_id.clone();
        let mut cancellation = tokio::spawn(async move {
            cancel_store
                .cancel_if_exact_live_owner(AtomicExecutionOwnerCancellationRequest {
                    user_id: &cancel_user,
                    run_id: &cancel_child,
                    expected_session_id: &cancel_session,
                    expected_owner_generation: 7,
                    expected_statuses: &[STATUS_RUNNING, STATUS_WAITING, STATUS_PAUSED],
                    origin: ExecutionOwnerCancellationOrigin::Runtime,
                    reason: "remote child runtime cancellation race",
                })
                .await
        });
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert!(
            !cancellation.is_finished(),
            "child cancellation bypassed the uncommitted ancestor marker lock"
        );
        marker_tx.commit().await.expect("commit root marker");
        let outcome = tokio::time::timeout(Duration::from_secs(5), &mut cancellation)
            .await
            .expect("child cancellation resumes after root commit")
            .expect("join child cancellation")
            .expect("classify child cancellation");
        assert!(matches!(
            outcome,
            AtomicExecutionOwnerCancellation::NotOwnedActive { .. }
        ));
        let child = store
            .load_run(&user_id, &child_run_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(child.status, STATUS_RUNNING);
        assert_eq!(child.events, child_baseline.events);
        assert_eq!(child.last_event_idx, child_baseline.last_event_idx);

        sqlx::query(
            "DELETE FROM agent_session_execution_slots WHERE user_id = ? AND session_id = ?",
        )
        .bind(&user_id)
        .bind(&session_id)
        .execute(pool.get())
        .await
        .expect("clean root-child execution slot");
        cleanup_database_run_fixture(&pool, &user_id, &child_run_id).await;
        cleanup_database_run_fixture(&pool, &user_id, &root_run_id).await;
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
            .bind(&user_id)
            .bind(&session_id)
            .execute(pool.get())
            .await
            .expect("clean root-child session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_execution_slot_requires_exact_active_session_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("runs-it-session-owner-{}", Uuid::new_v4());
        let foreign_user_id = format!("runs-it-session-foreign-{}", Uuid::new_v4());

        for (case, stored_owner, status, expected) in [
            ("missing", None, None, false),
            (
                "foreign",
                Some(foreign_user_id.as_str()),
                Some("active"),
                false,
            ),
            ("ended", Some(user_id.as_str()), Some("ended"), false),
            ("closed", Some(user_id.as_str()), Some("closed"), false),
            (
                "cancelled",
                Some(user_id.as_str()),
                Some("cancelled"),
                false,
            ),
            ("deleting", Some(user_id.as_str()), Some("deleting"), false),
            ("active", Some(user_id.as_str()), Some("active"), true),
        ] {
            let session_id = format!("runs-it-slot-{case}-{}", Uuid::new_v4());
            let run_id = format!("runs-it-slot-run-{case}-{}", Uuid::new_v4());
            if let (Some(stored_owner), Some(status)) = (stored_owner, status) {
                sqlx::query(
                    "INSERT INTO agent_sessions
                     (user_id, session_id, status, created_at, updated_at, last_active_at)
                     VALUES (?, ?, ?, NOW(6), NOW(6), NOW(6))",
                )
                .bind(stored_owner)
                .bind(&session_id)
                .bind(status)
                .execute(pool.get())
                .await
                .expect("insert exact-session execution-slot fixture");
            }

            let mut tx = pool
                .get()
                .begin()
                .await
                .expect("begin execution-slot fixture");
            let acquired = store
                .acquire_session_execution_slot_tx(&mut tx, &user_id, &session_id, &run_id)
                .await
                .expect("evaluate exact-session execution-slot admission");
            assert_eq!(acquired, expected, "unexpected admission for {case}");
            tx.commit().await.expect("commit execution-slot fixture");
            let slot_count: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM agent_session_execution_slots
                 WHERE user_id = ? AND session_id = ?",
            )
            .bind(&user_id)
            .bind(&session_id)
            .fetch_one(pool.get())
            .await
            .expect("load exact-session execution slot");
            assert_eq!(
                slot_count,
                if expected { 1 } else { 0 },
                "slot leak for {case}"
            );

            sqlx::query(
                "DELETE FROM agent_session_execution_slots WHERE user_id = ? AND session_id = ?",
            )
            .bind(&user_id)
            .bind(&session_id)
            .execute(pool.get())
            .await
            .expect("clean exact-session execution slot");
            if let Some(stored_owner) = stored_owner {
                sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
                    .bind(stored_owner)
                    .bind(&session_id)
                    .execute(pool.get())
                    .await
                    .expect("clean exact-session fixture");
            }
        }
    }

