    #[test]
    fn run_record_row_decode_rejects_invalid_numeric_database_values() {
        for column in [
            "depth",
            "run_generation",
            "retry_count",
            "total_prompt_tokens",
            "total_completion_tokens",
            "total_tool_calls",
        ] {
            assert_run_db_error_mentions(
                decode_run_record_from_row(&FakeRunStateRow::with_i64(column, -1)),
                column,
            );
        }

        assert_run_db_error_mentions(
            decode_run_record_from_row(&FakeRunStateRow::with_i64("last_event_idx", -2)),
            "last_event_idx",
        );
        assert_eq!(
            decode_run_record_from_row(&FakeRunStateRow::with_i64("last_event_idx", -1))
                .unwrap()
                .last_event_idx,
            -1
        );
        assert_run_db_error_mentions(
            decode_run_record_from_row(&FakeRunStateRow::with_i64(
                "depth",
                i64::from(u32::MAX) + 1,
            )),
            "depth",
        );
        assert_run_db_error_mentions(
            decode_run_record_from_row(&FakeRunStateRow::with_i64("work_graph_revision", 0)),
            "work_graph_revision",
        );
        assert_run_db_error_mentions(
            decode_run_record_from_row(&FakeRunStateRow::with_i64("work_item_revision", 0)),
            "work_item_revision",
        );
    }

