    #[tokio::test]
    async fn in_memory_run_start_claim_is_atomic_for_concurrent_same_session_retries() {
        let store = Arc::new(InMemoryRunStateStore::new());
        let barrier = Arc::new(tokio::sync::Barrier::new(2));

        let claim = |store: Arc<InMemoryRunStateStore>, barrier: Arc<tokio::sync::Barrier>| async move {
            let mut record = durable_run_record("exact-run-1");
            record.session_id = "exact-session-1".to_string();
            barrier.wait().await;
            store.claim_run_start(record, Some("exact-session-1")).await
        };
        let (first, second) = tokio::join!(
            claim(Arc::clone(&store), Arc::clone(&barrier)),
            claim(Arc::clone(&store), Arc::clone(&barrier)),
        );
        let outcomes = [first.expect("first claim"), second.expect("second claim")];

        assert_eq!(
            outcomes
                .iter()
                .filter(|outcome| matches!(outcome, DurableRunStartClaim::Started { .. }))
                .count(),
            1
        );
        assert_eq!(
            outcomes
                .iter()
                .filter(|outcome| {
                    **outcome
                        == DurableRunStartClaim::Existing {
                            session_id: "exact-session-1".to_string(),
                            start_request_fingerprint: None,
                        }
                })
                .count(),
            1
        );
        assert_eq!(store.runs.read().await.len(), 1);
    }

    #[tokio::test]
    async fn in_memory_run_start_claim_rejects_concurrent_session_mismatch_atomically() {
        let store = Arc::new(InMemoryRunStateStore::new());
        let barrier = Arc::new(tokio::sync::Barrier::new(2));

        let claim = |session_id: &'static str,
                     store: Arc<InMemoryRunStateStore>,
                     barrier: Arc<tokio::sync::Barrier>| async move {
            let mut record = durable_run_record("exact-run-2");
            record.session_id = session_id.to_string();
            barrier.wait().await;
            (
                session_id,
                store
                    .claim_run_start(record, Some(session_id))
                    .await
                    .expect("run start claim"),
            )
        };
        let (first, second) = tokio::join!(
            claim("exact-session-a", Arc::clone(&store), Arc::clone(&barrier)),
            claim("exact-session-b", Arc::clone(&store), Arc::clone(&barrier)),
        );
        let outcomes = [first, second];
        let winning_session = outcomes
            .iter()
            .find_map(|(session_id, outcome)| {
                matches!(outcome, DurableRunStartClaim::Started { .. }).then_some(*session_id)
            })
            .expect("one claim starts the run");
        let bound_session = outcomes
            .iter()
            .find_map(|(_, outcome)| match outcome {
                DurableRunStartClaim::SessionMismatch { bound_session_id } => {
                    Some(bound_session_id.as_str())
                }
                DurableRunStartClaim::Started { .. } | DurableRunStartClaim::Existing { .. } => {
                    None
                }
            })
            .expect("one claim rejects the mismatched session");

        assert_eq!(bound_session, winning_session);
        assert_eq!(
            store
                .load_run("u1", "exact-run-2")
                .await
                .expect("load claimed run")
                .expect("claimed run exists")
                .session_id,
            winning_session
        );
    }

    #[test]
    fn in_memory_terminal_status_is_immutable_including_delegated() {
        for terminal in [
            STATUS_COMPLETED,
            STATUS_DELEGATED,
            STATUS_FAILED,
            STATUS_CANCELLED,
        ] {
            let mut slots = std::collections::HashMap::new();
            let mut run = durable_run_record(&format!("{terminal}-terminal"));
            run.status = terminal.into();

            apply_in_memory_status_transition(&mut slots, &mut run, terminal, None, None, None)
                .expect("idempotent terminal replay must succeed");
            let error = apply_in_memory_status_transition(
                &mut slots,
                &mut run,
                STATUS_RUNNING,
                None,
                None,
                None,
            )
            .expect_err("terminal run must not resurrect");
            assert!(error.contains("terminal state immutability violated"));
            assert_eq!(run.status, terminal);
        }

        let mut active = durable_run_record("active");
        ensure_terminal_status_immutable(&active, STATUS_COMPLETED)
            .expect("non-terminal runs remain transitionable");
        active.status = STATUS_WAITING.into();
        ensure_terminal_status_immutable(&active, STATUS_FAILED)
            .expect("waiting recovery can still settle terminally");
    }

