    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_checkpoint_waits_for_canonical_run_lock_before_child_row_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("checkpoint-lock-u-{}", Uuid::new_v4());
        let session_id = format!("checkpoint-lock-s-{}", Uuid::new_v4());
        let run_id = format!("checkpoint-lock-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store
            .insert_run(run)
            .await
            .expect("insert checkpoint lock run");
        let checkpoint =
            r#"{"version":"checkpoint_v2","graceful":true,"last_batch_id":"canonical-lock"}"#;
        assert!(
            store
                .save_checkpoint(&user_id, &session_id, &run_id, checkpoint)
                .await
                .expect("create checkpoint child row")
        );

        let mut held = pool
            .get()
            .begin()
            .await
            .expect("begin canonical lock holder");
        store
            .load_run_metadata_for_exact_session_tx(&mut held, &user_id, &session_id, &run_id)
            .await
            .expect("lock run canonically")
            .expect("checkpoint run exists");
        let save = store.save_checkpoint(&user_id, &session_id, &run_id, checkpoint);
        tokio::pin!(save);
        assert!(
            tokio::time::timeout(Duration::from_millis(100), &mut save)
                .await
                .is_err(),
            "checkpoint writer must wait behind the canonical run lock"
        );
        tokio::time::timeout(
            Duration::from_millis(500),
            sqlx::query(
                "SELECT checkpoint_id FROM run_checkpoints
                 WHERE user_id = ? AND run_id = ? AND idempotency_key = ? FOR UPDATE",
            )
            .bind(&user_id)
            .bind(&run_id)
            .bind(format!("checkpoint:{run_id}:resume:canonical-lock"))
            .fetch_one(&mut *held),
        )
        .await
        .expect("blocked checkpoint writer must not hold the child row before the run lock")
        .expect("lock existing checkpoint child from canonical holder");
        held.rollback()
            .await
            .expect("release canonical checkpoint locks");
        assert!(
            tokio::time::timeout(Duration::from_secs(2), &mut save)
                .await
                .expect("checkpoint completes after canonical lock release")
                .expect("checkpoint save succeeds")
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup checkpoint lock slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup checkpoint lock session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_generic_append_commit_ack_loss_recovers_exact_batch_without_duplicates_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("append-ack-u-{}", Uuid::new_v4());
        let session_id = format!("append-ack-s-{}", Uuid::new_v4());
        let run_id = format!("append-ack-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert append ACK run");
        let events = [
            json!({
                "event_type": "agent_progress",
                "idempotency_key": format!("append:{run_id}:0"),
                "data": {"step": 0}
            }),
            json!({
                "event_type": "agent_progress",
                "idempotency_key": format!("append:{run_id}:1"),
                "data": {"step": 1}
            }),
        ];

        store
            .clone()
            .with_generic_append_commit_ack_loss_once()
            .append_events_batch(&user_id, &session_id, &run_id, &events)
            .await
            .expect("exact committed append must survive a lost acknowledgement");
        store
            .append_events_batch(&user_id, &session_id, &run_id, &events)
            .await
            .expect("exact append replay is idempotent");
        let durable = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        assert_eq!(durable.last_event_idx, 2);
        assert_eq!(durable.events.len(), 3);
        assert_eq!(durable.events[0]["index"], 0);
        assert_eq!(durable.events[1]["index"], 1);
        assert_eq!(durable.events[2]["index"], 2);

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup append ACK slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup append ACK session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_generic_append_ack_loss_missing_or_conflicting_proof_fails_closed_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("append-ambiguous-u-{}", Uuid::new_v4());
        let session_id = format!("append-ambiguous-s-{}", Uuid::new_v4());
        let missing_run_id = format!("append-missing-r-{}", Uuid::new_v4());
        let conflict_run_id = format!("append-conflict-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        for run_id in [&missing_run_id, &conflict_run_id] {
            let mut run = durable_run_record(run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            run.parent_run_id = Some("nonblocking-test-parent".to_string());
            store
                .insert_run(run)
                .await
                .expect("insert ambiguous append run");
        }
        let missing_event = json!({
            "event_type": "agent_progress",
            "idempotency_key": format!("missing:{missing_run_id}"),
            "data": {"case": "missing"}
        });
        let missing_error = store
            .clone()
            .with_generic_append_commit_ack_loss_missing_once()
            .append_event(&user_id, &session_id, &missing_run_id, missing_event)
            .await
            .expect_err("missing attempt rows cannot prove an ambiguous commit");
        assert!(missing_error.contains("ambiguous"), "{missing_error}");
        let missing = store
            .load_run(&user_id, &missing_run_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(missing.last_event_idx, 0);
        assert_eq!(missing.events.len(), 1);
        assert_eq!(extract_event_type(&missing.events[0]), "run_created");

        let conflict_event = json!({
            "event_type": "agent_progress",
            "idempotency_key": format!("conflict:{conflict_run_id}"),
            "data": {"case": "conflict"}
        });
        let conflict_error = store
            .clone()
            .with_generic_append_commit_ack_loss_conflicting_proof_once()
            .append_event(
                &user_id,
                &session_id,
                &conflict_run_id,
                conflict_event.clone(),
            )
            .await
            .expect_err("conflicting attempt proof cannot acknowledge an ambiguous commit");
        assert!(conflict_error.contains("ambiguous"), "{conflict_error}");
        store
            .append_event(&user_id, &session_id, &conflict_run_id, conflict_event)
            .await
            .expect("exact retry observes the one committed row without duplication");
        let conflict = store
            .load_run(&user_id, &conflict_run_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(conflict.last_event_idx, 1);
        assert_eq!(conflict.events.len(), 2);

        for run_id in [&missing_run_id, &conflict_run_id] {
            cleanup_database_run_fixture(&pool, &user_id, run_id).await;
        }
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup ambiguous append session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_cross_session_same_run_id_is_rejected_without_success_or_update_side_effect_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("cross-session-u-{}", Uuid::new_v4());
        let session_a = format!("cross-session-a-{}", Uuid::new_v4());
        let session_b = format!("cross-session-b-{}", Uuid::new_v4());
        let run_id = format!("cross-session-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_a).await;
        insert_active_database_session_fixture(&pool, &user_id, &session_b).await;
        let mut original = durable_run_record(&run_id);
        original.user_id = user_id.clone();
        original.session_id = session_a.clone();
        original.events = vec![json!({
            "event_type": "run_started",
            "idempotency_key": format!("cross-session:{run_id}:started"),
            "data": {"session_id": session_a}
        })];
        store
            .insert_run(original)
            .await
            .expect("insert original run");
        let before: (String, String, i64, String) = sqlx::query_as(
            "SELECT session_id, status, last_event_idx,
                    DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s.%f')
             FROM agent_runs WHERE user_id = ? AND run_id = ?",
        )
        .bind(&user_id)
        .bind(&run_id)
        .fetch_one(pool.get())
        .await
        .expect("snapshot original run");

        let mut conflicting = durable_run_record(&run_id);
        conflicting.user_id = user_id.clone();
        conflicting.session_id = session_b.clone();
        conflicting.status = STATUS_FAILED.to_string();
        let outcome = store
            .claim_run_start(conflicting, Some(&session_b))
            .await
            .expect("cross-session identity conflict is a typed outcome");
        assert_eq!(
            outcome,
            DurableRunStartClaim::SessionMismatch {
                bound_session_id: session_a.clone()
            }
        );
        let after: (String, String, i64, String) = sqlx::query_as(
            "SELECT session_id, status, last_event_idx,
                    DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s.%f')
             FROM agent_runs WHERE user_id = ? AND run_id = ?",
        )
        .bind(&user_id)
        .bind(&run_id)
        .fetch_one(pool.get())
        .await
        .expect("reload original run");
        assert_eq!(
            after, before,
            "conflicting create must not touch the winner"
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*) FROM agent_session_execution_slots
                 WHERE user_id = ? AND session_id = ?",
            )
            .bind(&user_id)
            .bind(&session_b)
            .fetch_one(pool.get())
            .await
            .expect("check losing session slot"),
            0
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup cross-session slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup cross-session sessions");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_interaction_frontier_ack_loss_and_stale_owner_generation_control_epoch_fail_closed_on_matrixone()
     {
        let (_, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("frontier-fence-u-{}", Uuid::new_v4());
        let session_id = format!("frontier-fence-s-{}", Uuid::new_v4());
        let ack_run_id = format!("frontier-ack-r-{}", Uuid::new_v4());
        let stale_run_id = format!("frontier-stale-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let store = DatabaseRunStateStore::new(pool.clone()).with_owner_pod_id("frontier-owner");
        for run_id in [&ack_run_id, &stale_run_id] {
            let mut run = durable_run_record(run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            run.parent_run_id = Some("nonblocking-frontier-parent".to_string());
            store.insert_run(run).await.expect("insert frontier run");
            let required = approval_required_event(
                if run_id == &ack_run_id {
                    "ack"
                } else {
                    "stale"
                },
                "bash",
                &session_id,
            );
            assert_eq!(
                store
                    .register_guarded_interaction_batch(
                        AtomicRunInteractionBatchRegistrationRequest {
                            user_id: &user_id,
                            run_id,
                            expected_session_id: &session_id,
                            expected_control_epoch: -1,
                            expected_owner_generation: 0,
                            events: std::slice::from_ref(&required),
                        },
                    )
                    .await
                    .expect("register frontier"),
                AtomicRunInteractionBatchRegistration::Registered
            );
        }
        assert_eq!(
            store
                .clone()
                .with_interaction_wait_commit_ack_loss_once()
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &ack_run_id,
                    expected_session_id: &session_id,
                    request_id: "ack",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .expect("exact wait ACK loss reconciles"),
            DurableRunInteractionWaitOutcome::Waiting
        );
        let ack_run = store
            .load_run(&user_id, &ack_run_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(ack_run.status, STATUS_WAITING);
        assert_eq!(
            ack_run
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "interaction_wait_started")
                .count(),
            1
        );

        let request = AtomicRunInteractionWaitRequest {
            user_id: &user_id,
            run_id: &stale_run_id,
            expected_session_id: &session_id,
            request_id: "stale",
            kind: DurableRunInteractionKind::Approval,
            expected_control_epoch: -1,
            expected_owner_generation: 0,
        };
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    expected_owner_generation: 1,
                    ..request
                })
                .await
                .expect("stale generation is a resolved fence"),
            DurableRunInteractionWaitOutcome::OwnerGenerationMismatch {
                actual_owner_generation: 0
            }
        );
        assert_eq!(
            DatabaseRunStateStore::new(pool.clone())
                .with_owner_pod_id("stale-owner")
                .begin_run_interaction_wait(request)
                .await
                .expect("stale owner is a resolved fence"),
            DurableRunInteractionWaitOutcome::OwnerMismatch {
                actual_owner_pod_id: Some("frontier-owner".to_string())
            }
        );
        store
            .append_event(
                &user_id,
                &session_id,
                &stale_run_id,
                json!({
                    "event_type": "user_intent",
                    "idempotency_key": format!("frontier-guidance:{stale_run_id}"),
                    "data": {"intent_id": "newer-guidance"}
                }),
            )
            .await
            .expect("append newer control epoch");
        assert_eq!(
            store
                .begin_run_interaction_wait(request)
                .await
                .expect("stale control epoch is superseded"),
            DurableRunInteractionWaitOutcome::Superseded {
                user_intent_event_index: 2
            }
        );
        let future_error = store
            .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                expected_control_epoch: 99,
                ..request
            })
            .await
            .expect_err("future control epoch cannot be fabricated");
        assert!(
            future_error.contains("ahead of durable run"),
            "{future_error}"
        );
        sqlx::query(
            "UPDATE agent_runs SET owner_lease_expires_at = NOW(6) - INTERVAL 1 SECOND
             WHERE user_id = ? AND run_id = ?",
        )
        .bind(&user_id)
        .bind(&stale_run_id)
        .execute(pool.get())
        .await
        .expect("expire frontier owner lease");
        assert_eq!(
            store
                .begin_run_interaction_wait(request)
                .await
                .expect("expired lease is a resolved fence"),
            DurableRunInteractionWaitOutcome::OwnerLeaseExpired
        );
        let stale_run = store
            .load_run(&user_id, &stale_run_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(stale_run.status, STATUS_RUNNING);
        assert_eq!(
            stale_run
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "interaction_wait_started")
                .count(),
            0
        );

        for run_id in [&ack_run_id, &stale_run_id] {
            cleanup_database_run_fixture(&pool, &user_id, run_id).await;
        }
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup frontier sessions");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_later_approval_callback_queues_and_promotes_at_exact_frontier_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("frontier-order-u-{}", Uuid::new_v4());
        let session_id = format!("frontier-order-s-{}", Uuid::new_v4());
        let run_id = format!("frontier-order-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store
            .insert_run(run)
            .await
            .expect("insert frontier-order run");
        let required = [
            approval_required_event("frontier-a", "write_file", &session_id),
            approval_required_event("frontier-b", "bash", &session_id),
        ];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &required,
                },)
                .await
                .expect("register complete approval batch"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        let later_error = store
            .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                user_id: &user_id,
                run_id: &run_id,
                expected_session_id: &session_id,
                request_id: "frontier-b",
                kind: DurableRunInteractionKind::Approval,
                expected_control_epoch: -1,
                expected_owner_generation: 0,
            })
            .await
            .expect_err("a later manifest item cannot become the execution frontier");
        assert!(
            later_error.contains("frontier-a must settle first"),
            "{later_error}"
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    request_id: "frontier-a",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .expect("open first exact frontier"),
            DurableRunInteractionWaitOutcome::Waiting
        );
        assert!(matches!(
            store
                .clone()
                .with_interaction_commit_ack_loss_once()
                .resolve_run_interaction(
                    &user_id,
                    &session_id,
                    &run_id,
                    "frontier-b",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "frontier-b",
                        "outcome": "denied",
                        "decision": "deny",
                        "tool": "bash",
                        "approval_kind": "standard"
                    }),
                )
                .await
                .expect("queued decision ACK loss reconciles"),
            DurableRunInteractionResolveOutcome::Queued(_)
        ));
        let restarted_store =
            DatabaseRunStateStore::new(pool.clone()).with_owner_pod_id("runs-it-pod");
        assert!(matches!(
            restarted_store
                .resolve_run_interaction(
                    &user_id,
                    &session_id,
                    &run_id,
                    "frontier-b",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "frontier-b",
                        "outcome": "denied",
                        "decision": "deny",
                        "tool": "bash",
                        "approval_kind": "standard"
                    }),
                )
                .await
                .expect("restart replays exact queued decision"),
            DurableRunInteractionResolveOutcome::Queued(_)
        ));
        let still_waiting = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        assert_eq!(still_waiting.status, STATUS_WAITING);
        assert_eq!(still_waiting.waiting_for.as_deref(), Some("tool_approval"));
        assert_eq!(
            still_waiting
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "run_resumed")
                .count(),
            0,
            "a queued later sibling must not resume the first frontier"
        );
        assert_eq!(
            still_waiting
                .events
                .iter()
                .filter(|event| {
                    extract_event_type(event) == APPROVAL_DECISION_QUEUED_EVENT_TYPE
                })
                .count(),
            1
        );
        assert!(matches!(
            store
                .resolve_run_interaction(
                    &user_id,
                    &session_id,
                    &run_id,
                    "frontier-a",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "frontier-a",
                        "outcome": "approved",
                        "decision": "allow",
                        "tool": "write_file",
                        "approval_kind": "standard"
                    }),
                )
                .await
                .expect("resolve actual frontier"),
            DurableRunInteractionResolveOutcome::Resolved(_)
        ));
        let resumed = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        assert_eq!(resumed.status, STATUS_RUNNING);
        assert_eq!(resumed.waiting_for, None);
        assert_eq!(
            resumed
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "run_resumed")
                .count(),
            1
        );
        let promoted = restarted_store
            .clone()
            .with_interaction_wait_commit_ack_loss_once()
            .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                user_id: &user_id,
                run_id: &run_id,
                expected_session_id: &session_id,
                request_id: "frontier-b",
                kind: DurableRunInteractionKind::Approval,
                expected_control_epoch: -1,
                expected_owner_generation: 0,
            })
            .await
            .expect("queued later sibling promotes at exact frontier");
        let DurableRunInteractionWaitOutcome::AlreadyResolved(promoted) = promoted else {
            panic!("queued later sibling was not promoted: {promoted:?}");
        };
        assert_eq!(promoted.pointer("/data/decision"), Some(&json!("deny")));
        assert_eq!(
            promoted.pointer("/data/_durable_resolution/disposition"),
            Some(&json!("resumed"))
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup frontier-order slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup frontier-order session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_queued_approval_never_promotes_after_authority_loss_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("queued-loss-u-{}", Uuid::new_v4());
        for mode in ["cancel", "owner_transfer", "lease_loss", "guidance"] {
            let session_id = format!("ql-{mode}-s-{}", Uuid::new_v4());
            let run_id = format!("ql-{mode}-r-{}", Uuid::new_v4());
            let request_id = format!("queued-loss-{mode}");
            insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
            let mut run = durable_run_record(&run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            store.insert_run(run).await.expect("insert queued-loss run");
            let required = [approval_required_event(&request_id, "bash", &session_id)];
            assert_eq!(
                store
                    .register_guarded_interaction_batch(
                        AtomicRunInteractionBatchRegistrationRequest {
                            user_id: &user_id,
                            run_id: &run_id,
                            expected_session_id: &session_id,
                            expected_control_epoch: -1,
                            expected_owner_generation: 0,
                            events: &required,
                        },
                    )
                    .await
                    .expect("register queued-loss approval"),
                AtomicRunInteractionBatchRegistration::Registered
            );
            assert!(matches!(
                store
                    .resolve_run_interaction(
                        &user_id,
                        &session_id,
                        &run_id,
                        &request_id,
                        DurableRunInteractionKind::Approval,
                        json!({
                            "request_id": request_id,
                            "outcome": "approved",
                            "decision": "allow",
                            "tool": "bash",
                            "approval_kind": "standard",
                        }),
                    )
                    .await
                    .expect("queue approval before frontier"),
                DurableRunInteractionResolveOutcome::Queued(_)
            ));
            match mode {
                "cancel" => {
                    assert!(
                        store
                            .update_run_status_with_event_if_current(
                                &user_id,
                                &session_id,
                                &run_id,
                                &[STATUS_RUNNING],
                                STATUS_CANCELLED,
                                None,
                                None,
                                json!({
                                    "event_type": "run_finished",
                                    "idempotency_key": format!("{run_id}:cancelled"),
                                    "data": {
                                        "status": STATUS_CANCELLED,
                                        "cancelled": true,
                                        "cancellation_origin": "runtime",
                                    },
                                }),
                            )
                            .await
                            .expect("cancel queued approval run")
                    );
                }
                "owner_transfer" => {
                    sqlx::query(
                        "UPDATE agent_runs SET owner_pod_id = ?, run_generation = 1,
                             owner_lease_expires_at = NOW(6) + INTERVAL 5 MINUTE
                         WHERE user_id = ? AND session_id = ? AND run_id = ?",
                    )
                    .bind("replacement-owner")
                    .bind(&user_id)
                    .bind(&session_id)
                    .bind(&run_id)
                    .execute(pool.get())
                    .await
                    .expect("transfer queued approval owner");
                }
                "lease_loss" => {
                    sqlx::query(
                        "UPDATE agent_runs SET owner_lease_expires_at = NOW(6) - INTERVAL 1 SECOND
                         WHERE user_id = ? AND session_id = ? AND run_id = ?",
                    )
                    .bind(&user_id)
                    .bind(&session_id)
                    .bind(&run_id)
                    .execute(pool.get())
                    .await
                    .expect("expire queued approval lease");
                }
                "guidance" => {
                    store
                        .append_event(
                            &user_id,
                            &session_id,
                            &run_id,
                            json!({
                                "event_type": "user_intent",
                                "idempotency_key": format!("{run_id}:guidance"),
                                "data": {"intent_id": "new-guidance"},
                            }),
                        )
                        .await
                        .expect("append queued approval guidance");
                }
                _ => unreachable!(),
            }
            let outcome = store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    request_id: &request_id,
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: if mode == "owner_transfer" { 1 } else { 0 },
                })
                .await
                .expect("terminalize queued authority loss");
            let DurableRunInteractionWaitOutcome::AlreadyResolved(event) = outcome else {
                panic!("queued {mode} authority loss was not terminalized: {outcome:?}");
            };
            assert_ne!(
                event.pointer("/data/_durable_resolution/disposition"),
                Some(&json!("resumed"))
            );
            let resumed: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM agent_run_events
                 WHERE user_id = ? AND run_id = ? AND interaction_request_id = ?
                   AND event_type = 'run_resumed'",
            )
            .bind(&user_id)
            .bind(&run_id)
            .bind(&request_id)
            .fetch_one(pool.get())
            .await
            .expect("count forbidden queued resume");
            assert_eq!(resumed, 0, "{mode} queued approval must not resume");
            cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
            sqlx::query(
                "DELETE FROM agent_session_execution_slots WHERE user_id = ? AND session_id = ?",
            )
            .bind(&user_id)
            .bind(&session_id)
            .execute(pool.get())
            .await
            .expect("cleanup queued-loss slot");
            sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
                .bind(&user_id)
                .bind(&session_id)
                .execute(pool.get())
                .await
                .expect("cleanup queued-loss session");
        }
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_stale_approval_callback_is_durable_without_resume_and_terminal_closure_precedes_terminal_event_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("approval-authority-u-{}", Uuid::new_v4());
        let stale_session = format!("approval-authority-stale-s-{}", Uuid::new_v4());
        let terminal_session = format!("approval-auth-term-s-{}", Uuid::new_v4());
        let stale_run = format!("approval-authority-stale-r-{}", Uuid::new_v4());
        let terminal_run = format!("approval-auth-term-r-{}", Uuid::new_v4());
        for (session_id, run_id) in [
            (&stale_session, &stale_run),
            (&terminal_session, &terminal_run),
        ] {
            insert_active_database_session_fixture(&pool, &user_id, session_id).await;
            let mut run = durable_run_record(run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            store
                .insert_run(run)
                .await
                .expect("insert approval fixture");
        }

        let stale_required = [approval_required_event(
            "stale-callback",
            "bash",
            &stale_session,
        )];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: &user_id,
                    run_id: &stale_run,
                    expected_session_id: &stale_session,
                    expected_control_epoch: 0,
                    expected_owner_generation: 0,
                    events: &stale_required,
                },)
                .await
                .expect("register stale callback approval"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &stale_run,
                    expected_session_id: &stale_session,
                    request_id: "stale-callback",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: 0,
                    expected_owner_generation: 0,
                })
                .await
                .expect("open stale callback frontier"),
            DurableRunInteractionWaitOutcome::Waiting
        );
        sqlx::query(
            "UPDATE agent_runs SET run_generation = 1
             WHERE user_id = ? AND session_id = ? AND run_id = ?",
        )
        .bind(&user_id)
        .bind(&stale_session)
        .bind(&stale_run)
        .execute(pool.get())
        .await
        .expect("rotate stale callback authority");
        assert!(matches!(
            store
                .resolve_run_interaction(
                    &user_id,
                    &stale_session,
                    &stale_run,
                    "stale-callback",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "stale-callback",
                        "outcome": "approved",
                        "decision": "allow",
                        "tool": "bash",
                        "approval_kind": "standard"
                    }),
                )
                .await
                .expect("record stale callback without resume"),
            DurableRunInteractionResolveOutcome::AuthorityLost {
                reason: DurableRunInteractionAuthorityLoss::OwnerGenerationMismatch {
                    actual_owner_generation: 1
                },
                ..
            }
        ));
        let stale = store.load_run(&user_id, &stale_run).await.unwrap().unwrap();
        assert_eq!(stale.status, STATUS_WAITING);
        assert!(stale.events.iter().any(|event| {
            extract_event_type(event) == "approval_resolved"
                && extract_interaction_request_id(event).as_deref() == Some("stale-callback")
        }));
        assert!(
            stale
                .events
                .iter()
                .all(|event| extract_event_type(event) != "run_resumed")
        );

        let terminal_required = [
            approval_required_event("terminal-done", "bash", &terminal_session),
            approval_required_event("terminal-pending", "git", &terminal_session),
        ];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: &user_id,
                    run_id: &terminal_run,
                    expected_session_id: &terminal_session,
                    expected_control_epoch: 0,
                    expected_owner_generation: 0,
                    events: &terminal_required,
                },)
                .await
                .expect("register terminal closure approvals"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &terminal_run,
                    expected_session_id: &terminal_session,
                    request_id: "terminal-done",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: 0,
                    expected_owner_generation: 0,
                })
                .await
                .expect("open terminal approval frontier"),
            DurableRunInteractionWaitOutcome::Waiting
        );
        assert!(matches!(
            store
                .resolve_run_interaction(
                    &user_id,
                    &terminal_session,
                    &terminal_run,
                    "terminal-done",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "terminal-done",
                        "outcome": "approved",
                        "decision": "allow",
                        "tool": "bash",
                        "approval_kind": "standard"
                    }),
                )
                .await
                .expect("resolve completed sibling"),
            DurableRunInteractionResolveOutcome::Resolved(_)
        ));
        assert!(
            store
                .update_run_status_with_event_if_current(
                    &user_id,
                    &terminal_session,
                    &terminal_run,
                    &[STATUS_RUNNING],
                    STATUS_CANCELLED,
                    None,
                    None,
                    json!({
                        "event_type": "run_finished",
                        "idempotency_key": format!("terminal-closure:{terminal_run}"),
                        "data": {
                            "status": STATUS_CANCELLED,
                            "cancelled": true,
                            "cancellation_origin": "runtime",
                        }
                    }),
                )
                .await
                .expect("terminal closure transition")
        );
        let terminal = store
            .load_run(&user_id, &terminal_run)
            .await
            .unwrap()
            .unwrap();
        let pending_resolution_index = terminal
            .events
            .iter()
            .position(|event| {
                extract_event_type(event) == "approval_resolved"
                    && extract_interaction_request_id(event).as_deref() == Some("terminal-pending")
            })
            .expect("pending approval is durably closed");
        let terminal_index = terminal
            .events
            .iter()
            .position(|event| extract_event_type(event) == "run_finished")
            .expect("terminal event exists");
        assert!(pending_resolution_index < terminal_index);
        assert_eq!(
            terminal.events.last().map(extract_event_type).as_deref(),
            Some("run_finished")
        );
        assert_eq!(
            terminal
                .events
                .iter()
                .filter(|event| {
                    extract_event_type(event) == "approval_resolved"
                        && extract_interaction_request_id(event).as_deref() == Some("terminal-done")
                })
                .count(),
            1
        );
        assert!(
            terminal.events[pending_resolution_index]
                .pointer("/data/decision")
                .is_some_and(|decision| decision == "deny")
        );
        let resumed = terminal
            .events
            .iter()
            .filter(|event| extract_event_type(event) == "run_resumed")
            .collect::<Vec<_>>();
        assert_eq!(resumed.len(), 1);
        assert_eq!(
            extract_interaction_request_id(resumed[0]).as_deref(),
            Some("terminal-done")
        );

        for run_id in [&stale_run, &terminal_run] {
            cleanup_database_run_fixture(&pool, &user_id, run_id).await;
        }
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup approval authority slots");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup approval authority sessions");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_atomic_terminal_settlement_closes_pending_approval_before_terminal_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let suffix = Uuid::new_v4();
        let user_id = format!("atomic-term-u-{suffix}");
        let session_id = format!("atomic-term-s-{suffix}");
        let run_id = format!("atomic-term-r-{suffix}");
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store
            .insert_run(run)
            .await
            .expect("insert atomic terminal run");
        let required = [approval_required_event(
            "atomic-terminal-approval",
            "bash",
            &session_id,
        )];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &required,
                },)
                .await
                .expect("register pending atomic terminal approval"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        let pre_terminal = store
            .load_run(&user_id, &run_id)
            .await
            .expect("load pre-terminal transaction frontier")
            .expect("atomic terminal run exists");
        assert_eq!(
            pre_terminal.events.last().map(extract_event_type),
            Some("approval_required".to_string())
        );
        let closure_event_idx = pre_terminal.last_event_idx + 1;
        let terminal_event_idx = closure_event_idx + 1;

        let terminal_events = [json!({
            "event_type": "run_finished",
            "idempotency_key": format!("atomic-terminal-finished:{run_id}"),
            "data": {"status": STATUS_COMPLETED},
        })];
        let mut tx = pool
            .get()
            .begin()
            .await
            .expect("begin direct terminal settlement transaction");
        let commit = store
            .settle_terminal_in_existing_transaction(
                &mut tx,
                AtomicRunTerminalSettlementRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    expected_statuses: &[STATUS_RUNNING],
                    expected_owner_generation: 0,
                    status: STATUS_COMPLETED,
                    waiting_for: None,
                    error_message: None,
                    events: &terminal_events,
                    prompt_tokens: 0,
                    completion_tokens: 0,
                    tool_calls: 0,
                },
            )
            .await
            .expect("settle terminal in existing transaction")
            .expect("exact terminal authority");
        tx.commit()
            .await
            .expect("commit direct terminal settlement transaction");

        assert_eq!(commit.event_receipts.len(), 1);
        assert_eq!(commit.event_receipts[0].event_idx, terminal_event_idx);
        assert_eq!(commit.last_event_idx, terminal_event_idx);
        let rows = sqlx::query(
            "SELECT event_idx, event_type FROM agent_run_events
             WHERE user_id = ? AND session_id = ? AND run_id = ?
             ORDER BY event_idx ASC",
        )
        .bind(&user_id)
        .bind(&session_id)
        .bind(&run_id)
        .fetch_all(pool.get())
        .await
        .expect("load direct terminal event cut");
        let facts = rows
            .iter()
            .map(|row| {
                Ok::<_, String>((
                    row.try_get::<i64, _>("event_idx")
                        .map_err(|error| error.to_string())?,
                    row.try_get::<String, _>("event_type")
                        .map_err(|error| error.to_string())?,
                ))
            })
            .collect::<Result<Vec<_>, _>>()
            .expect("decode direct terminal event cut");
        assert!(
            facts
                .iter()
                .enumerate()
                .all(|(offset, (event_idx, _))| *event_idx == offset as i64),
            "the durable event stream must remain contiguous and unique"
        );
        assert_eq!(
            &facts[facts.len() - 2..],
            &[
                (closure_event_idx, "approval_resolved".to_string()),
                (terminal_event_idx, "run_finished".to_string()),
            ],
            "the same transaction must append closure immediately before terminal truth"
        );
        let durable = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        assert_eq!(durable.status, STATUS_COMPLETED);
        assert_eq!(durable.last_event_idx, terminal_event_idx);
        let closure = durable
            .events
            .iter()
            .find(|event| extract_event_type(event) == "approval_resolved")
            .expect("approval closure committed before terminal");
        assert_eq!(
            closure
                .pointer("/data/_durable_resolution/actual_status")
                .and_then(serde_json::Value::as_str),
            Some(STATUS_COMPLETED)
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup atomic terminal slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup atomic terminal session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_terminal_statuses_close_all_interactions_and_replay_authority_loss_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("term-all-u-{}", Uuid::new_v4());
        for status in [STATUS_CANCELLED, STATUS_FAILED, STATUS_COMPLETED] {
            let suffix = Uuid::new_v4();
            let session_id = format!("term-all-s-{suffix}");
            let run_id = format!("term-all-r-{suffix}");
            let approval_id = format!("approval-{status}");
            let ask_user_id = format!("ask-user-{status}");
            insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
            let mut run = durable_run_record(&run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            store
                .insert_run(run)
                .await
                .expect("insert terminal interaction run");
            let approval = [approval_required_event(&approval_id, "bash", &session_id)];
            let ask_user = [ask_user_prompted_event(&ask_user_id, &session_id)];
            for events in [approval.as_slice(), ask_user.as_slice()] {
                assert_eq!(
                    store
                        .register_guarded_interaction_batch(
                            AtomicRunInteractionBatchRegistrationRequest {
                                user_id: &user_id,
                                run_id: &run_id,
                                expected_session_id: &session_id,
                                expected_control_epoch: -1,
                                expected_owner_generation: 0,
                                events,
                            },
                        )
                        .await
                        .expect("register terminal interaction"),
                    AtomicRunInteractionBatchRegistration::Registered
                );
            }
            let terminal_event = if status == STATUS_CANCELLED {
                json!({
                    "event_type": "run_finished",
                    "idempotency_key": format!("term-all:{run_id}"),
                    "data": {
                        "status": STATUS_CANCELLED,
                        "cancelled": true,
                        "cancellation_origin": "runtime",
                    },
                })
            } else {
                json!({
                    "event_type": "run_finished",
                    "idempotency_key": format!("term-all:{run_id}"),
                    "data": {"status": status},
                })
            };
            assert!(
                store
                    .update_run_status_with_event_if_current(
                        &user_id,
                        &session_id,
                        &run_id,
                        &[STATUS_RUNNING],
                        status,
                        None,
                        None,
                        terminal_event,
                    )
                    .await
                    .expect("commit terminal interaction closure"),
                "terminal transition should commit for status {status}"
            );
            let terminal = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
            let terminal_index = terminal
                .events
                .iter()
                .position(|event| extract_event_type(event) == "run_finished")
                .unwrap();
            for (event_type, request_id) in [
                ("approval_resolved", approval_id.as_str()),
                ("ask_user_resolved", ask_user_id.as_str()),
            ] {
                let (index, event) = terminal
                    .events
                    .iter()
                    .enumerate()
                    .find(|(_, event)| {
                        extract_event_type(event) == event_type
                            && extract_interaction_request_id(event).as_deref() == Some(request_id)
                    })
                    .expect("terminal interaction resolution");
                assert!(index < terminal_index);
                assert_eq!(
                    event
                        .pointer("/data/_durable_resolution/disposition")
                        .and_then(serde_json::Value::as_str),
                    Some("authority_lost")
                );
                assert_eq!(
                    event
                        .pointer("/data/_durable_resolution/actual_status")
                        .and_then(serde_json::Value::as_str),
                    Some(status)
                );
            }
            assert!(
                terminal
                    .events
                    .iter()
                    .all(|event| extract_event_type(event) != "run_resumed")
            );
            let event_count = terminal.events.len();
            for _ in 0..2 {
                for (request_id, kind, response) in [
                    (
                        approval_id.as_str(),
                        DurableRunInteractionKind::Approval,
                        json!({
                            "request_id": approval_id,
                            "outcome": "approved",
                            "decision": "allow",
                            "tool": "bash",
                            "approval_kind": "standard",
                        }),
                    ),
                    (
                        ask_user_id.as_str(),
                        DurableRunInteractionKind::AskUser,
                        json!({
                            "request_id": ask_user_id,
                            "outcome": "submitted",
                            "answers": {"answers": []},
                        }),
                    ),
                ] {
                    assert!(matches!(
                        store
                            .resolve_run_interaction(
                                &user_id,
                                &session_id,
                                &run_id,
                                request_id,
                                kind,
                                response,
                            )
                            .await
                            .expect("replay terminal authority loss"),
                        DurableRunInteractionResolveOutcome::AuthorityLost {
                            reason: DurableRunInteractionAuthorityLoss::Inactive { status: ref durable_status },
                            ..
                        } if durable_status == status
                    ));
                }
            }
            assert_eq!(
                store
                    .load_run(&user_id, &run_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .events
                    .len(),
                event_count
            );
            cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        }
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup terminal interaction slots");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup terminal interaction sessions");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_local_projection_patches_canonicalize_without_payload_conflict_on_matrixone()
    {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("projection-patches-u-{}", Uuid::new_v4());
        let session_id = format!("projection-patches-s-{}", Uuid::new_v4());
        let run_id = format!("projection-patches-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert projection run");

        store
            .append_event(
                &user_id,
                &session_id,
                &run_id,
                make_event("tool_call_end", json!({"ok": true})),
            )
            .await
            .expect("append event metadata projection patch");
        assert!(
            store
                .update_run_usage(&user_id, &session_id, &run_id, 21, 13, 5)
                .await
                .expect("publish usage projection patch")
        );

        let authoritative = store
            .load_run(&user_id, &run_id)
            .await
            .expect("load authoritative run")
            .expect("authoritative run exists");
        let locally_patched = store
            .load_run_projection(&user_id, &run_id)
            .await
            .expect("load locally patched projection")
            .expect("locally patched projection exists");
        let expected = build_run_display_projection(
            &authoritative,
            authoritative.events.last().map(extract_event_type),
            None,
        );
        assert_eq!(
            classify_run_display_projection_relation(&locally_patched, &expected),
            RunDisplayProjectionRelation::HashCanonicalization
        );
        assert!(run_display_projection_payload_matches(
            &locally_patched,
            &expected
        ));

        store
            .sync_projection_for_user(&user_id, &session_id, &run_id)
            .await
            .expect("canonicalize full projection hash");
        let canonical = store
            .load_run_projection(&user_id, &run_id)
            .await
            .expect("load canonical projection")
            .expect("canonical projection exists");
        assert_eq!(
            classify_run_display_projection_relation(&canonical, &expected),
            RunDisplayProjectionRelation::Canonical
        );
        assert!(run_display_projection_payload_matches(
            &canonical, &expected
        ));
        assert_eq!(
            canonical.latest_event_type.as_deref(),
            Some("tool_call_end")
        );
        assert_eq!(canonical.total_prompt_tokens, 21);
        assert_eq!(canonical.total_completion_tokens, 13);
        assert_eq!(canonical.total_tool_calls, 5);

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup projection patch slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup projection patch session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_concurrent_sibling_callbacks_preserve_authoritative_frontier_projection_on_matrixone()
     {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("projection-frontier-u-{}", Uuid::new_v4());
        let session_id = format!("projection-frontier-s-{}", Uuid::new_v4());
        let run_id = format!("projection-frontier-r-{}", Uuid::new_v4());
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert projection run");
        assert!(
            store
                .save_checkpoint(
                    &user_id,
                    &session_id, &run_id,
                    r#"{"version":"checkpoint_v2","graceful":true,"last_batch_id":"projection-frontier"}"#,
                )
                .await
                .expect("save projection checkpoint")
        );
        let required = [
            approval_required_event("projection-frontier-a", "write_file", &session_id),
            approval_required_event("projection-frontier-b", "bash", &session_id),
            approval_required_event("projection-frontier-c", "python", &session_id),
        ];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &required,
                },)
                .await
                .expect("register projection approval batch"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    request_id: "projection-frontier-a",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .expect("begin exact projection frontier"),
            DurableRunInteractionWaitOutcome::Waiting
        );

        let callback = |request_id: &'static str, tool: &'static str, decision: &'static str| {
            let store = store.clone();
            let user_id = user_id.clone();
            let session_id = session_id.clone();
            let run_id = run_id.clone();
            async move {
                store
                    .resolve_run_interaction(
                        &user_id,
                        &session_id,
                        &run_id,
                        request_id,
                        DurableRunInteractionKind::Approval,
                        json!({
                            "request_id": request_id,
                            "outcome": if decision == "allow" { "approved" } else { "denied" },
                            "decision": decision,
                            "tool": tool,
                            "approval_kind": "standard"
                        }),
                    )
                    .await
            }
        };
        let (frontier, sibling_b, sibling_c) =
            tokio::time::timeout(Duration::from_secs(3), async {
                tokio::join!(
                    callback("projection-frontier-a", "write_file", "allow"),
                    callback("projection-frontier-b", "bash", "deny"),
                    callback("projection-frontier-c", "python", "deny")
                )
            })
            .await
            .expect("concurrent sibling callbacks must not deadlock");
        let outcomes = [frontier, sibling_b, sibling_c]
            .into_iter()
            .map(|outcome| outcome.expect("persist concurrent callback"))
            .collect::<Vec<_>>();
        assert_eq!(
            outcomes
                .iter()
                .filter(|outcome| matches!(
                    outcome,
                    DurableRunInteractionResolveOutcome::Resolved(_)
                ))
                .count(),
            1,
            "only the open frontier may resume the run: {outcomes:?}"
        );
        assert_eq!(
            outcomes
                .iter()
                .filter(|outcome| matches!(outcome, DurableRunInteractionResolveOutcome::Queued(_)))
                .count(),
            2,
            "sibling callbacks remain durable until their own frontier opens: {outcomes:?}"
        );

        assert!(
            store
                .update_run_usage(&user_id, &session_id, &run_id, 21, 13, 5)
                .await
                .expect("publish monotonic usage")
        );
        let _ = store
            .update_run_usage(&user_id, &session_id, &run_id, 3, 2, 1)
            .await
            .expect("stale usage is a resolved no-op");
        let authoritative = store
            .load_run(&user_id, &run_id)
            .await
            .expect("load authoritative projection run")
            .expect("projection run exists");
        assert_eq!(authoritative.status, STATUS_RUNNING);
        assert_eq!(authoritative.waiting_for, None);
        assert_eq!(authoritative.total_prompt_tokens, 21);
        assert_eq!(authoritative.total_completion_tokens, 13);
        assert_eq!(authoritative.total_tool_calls, 5);
        let canonical_before_conflict = store
            .load_run_projection(&user_id, &run_id)
            .await
            .expect("load canonical projection before conflict")
            .expect("canonical projection exists before conflict");

        // Model a delayed same-frontier writer from an already-committed
        // sibling callback. The repair path must discard this payload and
        // rebuild from the locked durable frontier, not accept last-writer.
        sqlx::query(
            "UPDATE run_display_projections
             SET status = 'waiting', waiting_for = 'tool_approval',
                 error_message = 'stale sibling', latest_event_type = 'approval_resolved',
                 latest_checkpoint_id = NULL, latest_checkpoint_kind = NULL,
                 latest_checkpoint_version = NULL, total_prompt_tokens = 0,
                 total_completion_tokens = 0, total_tool_calls = 0,
                 projection_hash = ?
             WHERE user_id = ? AND run_id = ?",
        )
        .bind("0".repeat(64))
        .bind(&user_id)
        .bind(&run_id)
        .execute(pool.get())
        .await
        .expect("inject same-frontier projection conflict");
        let injected = store
            .load_run_projection(&user_id, &run_id)
            .await
            .expect("load injected projection conflict")
            .expect("injected projection exists");
        assert_eq!(
            classify_run_display_projection_relation(&injected, &canonical_before_conflict),
            RunDisplayProjectionRelation::PayloadConflict
        );
        store
            .sync_projection_for_user(&user_id, &session_id, &run_id)
            .await
            .expect("repair same-frontier conflict from authority");
        store
            .patch_run_projection_event_metadata_for_user(
                &user_id,
                &session_id,
                &run_id,
                authoritative.last_event_idx - 1,
                "stale_sibling_callback",
            )
            .await;

        let projection = store
            .load_run_projection(&user_id, &run_id)
            .await
            .expect("load final projection")
            .expect("final projection exists");
        assert_eq!(projection.status, authoritative.status);
        assert_eq!(projection.waiting_for, authoritative.waiting_for);
        assert_eq!(projection.error_message, authoritative.error_message);
        assert_eq!(
            projection.projection_event_idx,
            authoritative.last_event_idx
        );
        assert_eq!(
            projection.latest_event_type,
            authoritative.events.last().map(extract_event_type)
        );
        assert_eq!(projection.total_prompt_tokens, 21);
        assert_eq!(projection.total_completion_tokens, 13);
        assert_eq!(projection.total_tool_calls, 5);
        assert_eq!(
            projection.latest_checkpoint_version.as_deref(),
            Some("checkpoint_v2")
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup projection frontier slot");
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup projection frontier session");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_different_users_do_not_share_run_write_head_of_line_lock_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_a = format!("no-hol-a-u-{}", Uuid::new_v4());
        let user_b = format!("no-hol-b-u-{}", Uuid::new_v4());
        let session_a = format!("no-hol-a-s-{}", Uuid::new_v4());
        let session_a_peer = format!("no-hol-a-peer-s-{}", Uuid::new_v4());
        let session_b = format!("no-hol-b-s-{}", Uuid::new_v4());
        let run_a = format!("no-hol-a-r-{}", Uuid::new_v4());
        let run_a_peer = format!("no-hol-a-peer-r-{}", Uuid::new_v4());
        let run_b = format!("no-hol-b-r-{}", Uuid::new_v4());
        for (user_id, session_id, run_id) in [
            (&user_a, &session_a, &run_a),
            (&user_a, &session_a_peer, &run_a_peer),
            (&user_b, &session_b, &run_b),
        ] {
            insert_active_database_session_fixture(&pool, user_id, session_id).await;
            let mut run = durable_run_record(run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            store.insert_run(run).await.expect("insert no-HOL run");
        }

        let mut held = pool.get().begin().await.expect("begin held user-A lock");
        store
            .load_run_metadata_for_exact_session_tx(&mut held, &user_a, &session_a, &run_a)
            .await
            .expect("hold user-A canonical lock")
            .expect("user-A run exists");
        let (same_session_scope, different_user_scope) =
            tokio::time::timeout(Duration::from_secs(3), async {
                tokio::join!(
                    async {
                        tokio::join!(
                            store.append_event(
                                &user_a,
                                &session_a_peer,
                                &run_a_peer,
                                json!({
                                    "event_type": "agent_progress",
                                    "idempotency_key": format!("no-hol:{run_a_peer}:0"),
                                    "data": {"scope": "same-user-different-session", "attempt": 0}
                                }),
                            ),
                            store.append_event(
                                &user_a,
                                &session_a_peer,
                                &run_a_peer,
                                json!({
                                    "event_type": "agent_progress",
                                    "idempotency_key": format!("no-hol:{run_a_peer}:1"),
                                    "data": {"scope": "same-user-different-session", "attempt": 1}
                                }),
                            ),
                            store.append_event(
                                &user_a,
                                &session_a_peer,
                                &run_a_peer,
                                json!({
                                    "event_type": "agent_progress",
                                    "idempotency_key": format!("no-hol:{run_a_peer}:2"),
                                    "data": {"scope": "same-user-different-session", "attempt": 2}
                                }),
                            ),
                        )
                    },
                    async {
                        tokio::join!(
                            store.append_event(
                                &user_b,
                                &session_b,
                                &run_b,
                                json!({
                                    "event_type": "agent_progress",
                                    "idempotency_key": format!("no-hol:{run_b}:0"),
                                    "data": {"scope": "different-user", "attempt": 0}
                                }),
                            ),
                            store.append_event(
                                &user_b,
                                &session_b,
                                &run_b,
                                json!({
                                    "event_type": "agent_progress",
                                    "idempotency_key": format!("no-hol:{run_b}:1"),
                                    "data": {"scope": "different-user", "attempt": 1}
                                }),
                            ),
                            store.append_event(
                                &user_b,
                                &session_b,
                                &run_b,
                                json!({
                                    "event_type": "agent_progress",
                                    "idempotency_key": format!("no-hol:{run_b}:2"),
                                    "data": {"scope": "different-user", "attempt": 2}
                                }),
                            ),
                        )
                    },
                )
            })
            .await
            .expect(
                "same-user peer sessions and different users must not share user-A's held lock",
            );
        for outcome in [
            same_session_scope.0,
            same_session_scope.1,
            same_session_scope.2,
        ] {
            outcome.expect("same-user different-session append succeeds without global HOL");
        }
        for outcome in [
            different_user_scope.0,
            different_user_scope.1,
            different_user_scope.2,
        ] {
            outcome.expect("different-user append succeeds without global HOL");
        }
        held.rollback().await.expect("release user-A lock");

        for (user_id, run_id) in [(&user_a, &run_a), (&user_a, &run_a_peer), (&user_b, &run_b)] {
            cleanup_database_run_fixture(&pool, user_id, run_id).await;
        }
        for user_id in [&user_a, &user_b] {
            sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
                .bind(user_id)
                .execute(pool.get())
                .await
                .expect("cleanup no-HOL slot");
            sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
                .bind(user_id)
                .execute(pool.get())
                .await
                .expect("cleanup no-HOL session");
        }
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_256_concurrent_appends_across_users_and_sessions_are_exact_and_contiguous_on_matrixone()
     {
        const USERS: usize = 16;
        const SESSIONS_PER_USER: usize = 4;
        const APPENDS_PER_SESSION: usize = 4;
        const EXPECTED_RUNS: i64 = (USERS * SESSIONS_PER_USER) as i64;
        const EXPECTED_EVENTS: i64 = (USERS * SESSIONS_PER_USER * APPENDS_PER_SESSION) as i64;

        let (store, pool) = setup_database_run_state_store_it().await;
        let prefix = format!("append-stress-{}", Uuid::new_v4());
        let mut fixtures = Vec::with_capacity(EXPECTED_RUNS as usize);
        for user_index in 0..USERS {
            let user_id = format!("{prefix}-u{user_index}");
            for session_index in 0..SESSIONS_PER_USER {
                let session_id = format!("{prefix}-u{user_index}-s{session_index}");
                let run_id = format!("{prefix}-r{user_index}-{session_index}");
                insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
                let mut run = durable_run_record(&run_id);
                run.user_id = user_id.clone();
                run.session_id = session_id.clone();
                store.insert_run(run).await.expect("insert stress run");
                fixtures.push((user_id.clone(), session_id, run_id));
            }
        }

        let mut jobs = tokio::task::JoinSet::new();
        for (user_id, session_id, run_id) in &fixtures {
            for append_index in 0..APPENDS_PER_SESSION {
                let store = store.clone();
                let user_id = user_id.clone();
                let session_id = session_id.clone();
                let run_id = run_id.clone();
                jobs.spawn(async move {
                    store
                        .append_event(
                            &user_id,
                            &session_id,
                            &run_id,
                            json!({
                                "event_type": "agent_progress",
                                "idempotency_key": format!("{run_id}:stress:{append_index}"),
                                "data": {"append_index": append_index}
                            }),
                        )
                        .await
                });
            }
        }
        while let Some(outcome) = jobs.join_next().await {
            outcome
                .expect("stress append task remains live")
                .expect("stress append succeeds");
        }

        let run_like = format!("{prefix}-r%");
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*) FROM agent_runs
                 WHERE run_id LIKE ? AND last_event_idx = 4",
            )
            .bind(&run_like)
            .fetch_one(pool.get())
            .await
            .expect("count contiguous stress runs"),
            EXPECTED_RUNS
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*) FROM agent_run_events
                 WHERE run_id LIKE ? AND event_type = 'agent_progress'",
            )
            .bind(&run_like)
            .fetch_one(pool.get())
            .await
            .expect("count exact stress events"),
            EXPECTED_EVENTS
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*) FROM (
                   SELECT user_id, run_id
                   FROM agent_run_events
                   WHERE run_id LIKE ? AND event_type = 'agent_progress'
                   GROUP BY user_id, run_id
                   HAVING COUNT(*) <> 4 OR MIN(event_idx) <> 1 OR MAX(event_idx) <> 4
                      OR COUNT(DISTINCT event_idx) <> 4
                 ) AS non_contiguous_runs",
            )
            .bind(&run_like)
            .fetch_one(pool.get())
            .await
            .expect("detect stress gaps or duplicates"),
            0
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*)
                 FROM agent_run_events event
                 LEFT JOIN agent_runs run
                   ON run.user_id = event.user_id
                  AND run.session_id = event.session_id
                  AND run.run_id = event.run_id
                 WHERE event.run_id LIKE ? AND event.event_type = 'agent_progress'
                   AND run.run_id IS NULL",
            )
            .bind(&run_like)
            .fetch_one(pool.get())
            .await
            .expect("detect orphan stress events"),
            0
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*)
                 FROM run_display_projections projection
                 INNER JOIN agent_runs run
                   ON run.user_id = projection.user_id
                  AND run.session_id = projection.session_id
                  AND run.run_id = projection.run_id
                 WHERE projection.run_id LIKE ? AND projection.projection_event_idx = 4",
            )
            .bind(&run_like)
            .fetch_one(pool.get())
            .await
            .expect("count monotonic stress projections"),
            EXPECTED_RUNS
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*)
                 FROM run_display_projections projection
                 LEFT JOIN agent_runs run
                   ON run.user_id = projection.user_id
                  AND run.session_id = projection.session_id
                  AND run.run_id = projection.run_id
                 WHERE projection.run_id LIKE ? AND run.run_id IS NULL",
            )
            .bind(&run_like)
            .fetch_one(pool.get())
            .await
            .expect("detect cross-owner stress projections"),
            0
        );

        for (user_id, _, run_id) in &fixtures {
            cleanup_database_run_fixture(&pool, user_id, run_id).await;
        }
        for user_index in 0..USERS {
            let user_id = format!("{prefix}-u{user_index}");
            sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
                .bind(&user_id)
                .execute(pool.get())
                .await
                .expect("cleanup stress slots");
            sqlx::query("DELETE FROM agent_sessions WHERE user_id = ?")
                .bind(&user_id)
                .execute(pool.get())
                .await
                .expect("cleanup stress sessions");
        }
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_interaction_registration_commit_ack_loss_recovers_exact_batch_on_matrixone() {
        let (_, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("registration-ack-u-{}", Uuid::new_v4());
        let run_id = format!("registration-ack-r-{}", Uuid::new_v4());
        let session_id = format!("registration-ack-s-{}", Uuid::new_v4());
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;

        let store = DatabaseRunStateStore::new(pool.clone())
            .with_owner_pod_id("interaction-registration-ack-owner")
            .with_interaction_registration_commit_ack_loss_once();
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store
            .insert_run(run)
            .await
            .expect("insert registration ACK-loss run");
        let events = [
            approval_required_event("registration-ack-a", "bash", &session_id),
            approval_required_event("registration-ack-b", "git", &session_id),
        ];
        let request = AtomicRunInteractionBatchRegistrationRequest {
            user_id: &user_id,
            run_id: &run_id,
            expected_session_id: &session_id,
            expected_control_epoch: -1,
            expected_owner_generation: 0,
            events: &events,
        };
        assert_eq!(
            store
                .register_guarded_interaction_batch(request)
                .await
                .expect("lost registration commit ACK must reconcile exact durable facts"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .register_guarded_interaction_batch(request)
                .await
                .expect("exact registration retry remains idempotent"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        let durable = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        let approvals = durable
            .events
            .iter()
            .filter(|event| extract_event_type(event) == "approval_required")
            .collect::<Vec<_>>();
        assert_eq!(approvals.len(), 2);
        assert_eq!(
            approvals
                .iter()
                .filter_map(|event| extract_interaction_request_id(event))
                .collect::<Vec<_>>(),
            ["registration-ack-a", "registration-ack-b"]
        );
        assert_eq!(
            approvals[0]["data"]["registration_batch_id"],
            approvals[1]["data"]["registration_batch_id"]
        );
        assert_eq!(approvals[0]["data"]["registration_batch_index"], 0);
        assert_eq!(approvals[1]["data"]["registration_batch_index"], 1);
        assert_eq!(
            approvals[1]["index"].as_i64(),
            approvals[0]["index"].as_i64().map(|index| index + 1)
        );

        let subset = [events[1].clone()];
        let subset_error = store
            .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                events: &subset,
                ..request
            })
            .await
            .expect_err("a subset retry cannot masquerade as the complete provider batch");
        assert!(
            subset_error.contains("immutable approval registration conflict"),
            "{subset_error}"
        );

        let conflict = [approval_required_event(
            "registration-ack-a",
            "python",
            &session_id,
        )];
        let error = store
            .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                events: &conflict,
                ..request
            })
            .await
            .expect_err("same immutable identity with a new payload must fail closed");
        assert!(
            error.contains("immutable approval registration conflict"),
            "{error}"
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup registration ACK-loss execution slot");
    }

    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_interaction_commit_ack_loss_recovers_exact_resolution_on_matrixone() {
        let (_, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("acku-{}", Uuid::new_v4());
        let run_id = format!("ackr-{}", Uuid::new_v4());
        let session_id = format!("acks-{}", Uuid::new_v4());
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;

        let store = DatabaseRunStateStore::new(pool.clone())
            .with_owner_pod_id("interaction-ack-owner")
            .with_interaction_commit_ack_loss_once();
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert ACK-loss run");
        let required = [approval_required_event(
            "approval-ack-loss",
            "bash",
            &session_id,
        )];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    expected_control_epoch: 0,
                    expected_owner_generation: 0,
                    events: &required,
                },)
                .await
                .expect("register ACK-loss approval"),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: &user_id,
                    run_id: &run_id,
                    expected_session_id: &session_id,
                    request_id: "approval-ack-loss",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: 0,
                    expected_owner_generation: 0,
                })
                .await
                .expect("open ACK-loss approval frontier"),
            DurableRunInteractionWaitOutcome::Waiting
        );
        let response = json!({
            "request_id": "approval-ack-loss",
            "outcome": "approved",
            "decision": "allow",
            "tool": "bash",
            "approval_kind": "standard",
        });
        let outcome = store
            .resolve_run_interaction(
                &user_id,
                &session_id,
                &run_id,
                "approval-ack-loss",
                DurableRunInteractionKind::Approval,
                response.clone(),
            )
            .await
            .expect("lost commit ACK must reconcile through exact durable identity");
        assert!(matches!(
            outcome,
            DurableRunInteractionResolveOutcome::Idempotent(_)
        ));
        let durable = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        assert_eq!(durable.status, STATUS_RUNNING);
        assert_eq!(durable.waiting_for, None);
        assert_eq!(
            durable
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "approval_resolved")
                .count(),
            1
        );
        assert_eq!(
            durable
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "run_resumed")
                .count(),
            1
        );

        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_session_execution_slots WHERE user_id = ?")
            .bind(&user_id)
            .execute(pool.get())
            .await
            .expect("cleanup ACK-loss execution slot");
    }

