    #[test]
    fn turn_phase_has_one_bounded_public_shape_for_live_and_replay() {
        let expected = json!({
            "type": "turn_phase",
            "schema_version": 1,
            "phase": "turn_intent_admission",
            "round_index": 0,
            "attempt_index": 0,
            "outcome": "decided",
            "duration_ms": 5_021,
        });
        let live = transform_run_event_for_client(json!({
            "type": "turn_phase",
            "schema_version": 1,
            "phase": "turn_intent_admission",
            "round_index": 0,
            "outcome": "decided",
            "duration_ms": 5_021,
            "internal_model": "must not cross the client boundary",
        }));
        let replay = transform_run_event_for_client(make_event(
            "turn_phase",
            json!({
                "schema_version": 1,
                "phase": "turn_intent_admission",
                "round_index": 0,
                "outcome": "decided",
                "duration_ms": 5_021,
                "internal_model": "must not cross the client boundary",
            }),
        ));

        assert_eq!(live, expected);
        assert_eq!(replay, expected);
        assert_eq!(
            transform_run_event_for_client(json!({
                "type": "turn_phase",
                "schema_version": 1,
                "phase": "model_inference",
                "round_index": 1,
                "attempt_index": 1,
                "outcome": "succeeded",
                "duration_ms": 73,
            })),
            json!({
                "type": "turn_phase",
                "schema_version": 1,
                "phase": "model_inference",
                "round_index": 1,
                "attempt_index": 1,
                "outcome": "succeeded",
                "duration_ms": 73,
            }),
            "a measured provider phase remains available after the typed projection"
        );
        assert_eq!(
            transform_run_event_for_client(json!({
                "type": "turn_phase",
                "schema_version": 1,
                "phase": "unrecognized_phase",
                "round_index": 0,
                "outcome": "decided",
                "duration_ms": 5_021,
            })),
            serde_json::Value::Null,
            "unknown internal phases must not become accidental public protocol"
        );
        assert_eq!(
            transform_run_event_for_client(json!({
                "type": "turn_phase",
                "schema_version": 1,
                "phase": "model_inference",
                "round_index": 0,
                "outcome": "decided",
                "duration_ms": 1,
            })),
            serde_json::Value::Null,
            "typed phase/outcome contracts reject impossible telemetry rather than presenting a lie"
        );
    }

    #[test]
    fn large_tool_results_are_bounded_on_the_external_client_surface() {
        let output = "界".repeat(EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES);
        let original_bytes = serde_json::to_string(&serde_json::Value::String(output.clone()))
            .expect("serialize test result")
            .len();

        let transformed = transform_run_event_for_client(make_event(
            "tool_result",
            json!({
                "tool_call_id": "call-large",
                "name": "read_catalog_file_pages",
                "output": output,
                "success": true,
            }),
        ));

        assert_eq!(transformed["type"], "tool_call_end");
        assert_eq!(transformed["call_id"], "call-large");
        assert_eq!(transformed["result_truncated"], true);
        assert_eq!(transformed["result_bytes"], original_bytes);
        assert!(transformed.get("evidence_ref").is_none());
        assert_eq!(
            transformed["result_integrity"]["content_sha256"],
            transformed["result_sha256"]
        );
        assert_eq!(transformed["result_integrity"]["sha256_encoding"], "json");
        assert_eq!(
            transformed["result"]["type"],
            "astra.external_tool_result_summary.v1"
        );
        assert_eq!(transformed["result"]["truncated"], true);
        assert_eq!(transformed["result"]["original_bytes"], original_bytes);
        let preview = transformed["result"]["preview"]
            .as_str()
            .expect("summary preview");
        assert!(preview.len() <= EXTERNAL_TOOL_RESULT_PREVIEW_MAX_BYTES);
        assert!(preview.is_char_boundary(preview.len()));
        assert!(
            serde_json::to_vec(&transformed)
                .expect("serialize transformed event")
                .len()
                < 16 * 1024
        );
    }

    #[test]
    fn large_lifecycle_result_preserves_fanout_identity_on_external_surface() {
        let result = json!({
            "status": "completed",
            "group_id": "review-group",
            "target_count": 2,
            "results": [{"result": "x".repeat(EXTERNAL_TOOL_RESULT_INLINE_MAX_BYTES * 2)}],
            "fanout": {
                "group_id": "review-group",
                "target_count": 2,
                "slots": [
                    {"slot_index": 0, "agent_id": "a", "run_id": "run-a", "status": "completed"},
                    {"slot_index": 1, "agent_id": "b", "run_id": "run-b", "status": "completed"}
                ]
            },
            "work_unit_observation": {
                "id": "review-group",
                "kind": "agent_fanout",
                "status": "completed",
                "revision": 3,
                "mode": "current",
                "wake_policy": "none"
            }
        })
        .to_string();
        let transformed = transform_run_event_for_client(json!({
            "type": "tool_call_end",
            "call_id": "call-fanout",
            "tool": "agent_fanout",
            "result": result,
            "success": true,
        }));

        assert_eq!(transformed["success"], true);
        assert_eq!(transformed["result"]["group_id"], "review-group");
        assert_eq!(transformed["result"]["target_count"], 2);
        assert_eq!(
            transformed["result"]["work_unit_observation"]["kind"],
            "agent_fanout"
        );
        assert!(transformed["result"].get("results").is_none());
        assert!(encoded_json_len(&transformed) <= EXTERNAL_TOOL_EVENT_MAX_BYTES);
    }

