    fn guidance_admission_request<'a>(
        run_id: &'a str,
        intent_id: &'a str,
        event: &'a serde_json::Value,
        process_local_execution_live: bool,
    ) -> AtomicRunGuidanceAdmissionRequest<'a> {
        AtomicRunGuidanceAdmissionRequest {
            user_id: "u1",
            run_id,
            expected_session_id: "s1",
            intent_id,
            event,
            process_local_execution_live,
        }
    }

    #[tokio::test]
    async fn atomic_guidance_duplicate_precedes_fence_and_binds_immutable_payload() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("guidance-duplicate"))
            .await
            .unwrap();
        let event = user_intent_event("intent-exact");
        assert_eq!(
            store
                .admit_run_guidance(guidance_admission_request(
                    "guidance-duplicate",
                    "intent-exact",
                    &event,
                    true,
                ))
                .await
                .unwrap(),
            AtomicRunGuidanceAdmission::Committed { event_index: 0 }
        );
        store
            .append_event(
                "u1",
                "s1",
                "guidance-duplicate",
                make_event("user_intent_settlement_fenced", json!({})),
            )
            .await
            .unwrap();
        assert_eq!(
            store
                .admit_run_guidance(guidance_admission_request(
                    "guidance-duplicate",
                    "intent-exact",
                    &event,
                    false,
                ))
                .await
                .unwrap(),
            AtomicRunGuidanceAdmission::Duplicate { event_index: 0 }
        );
        let mut conflicting = event.clone();
        conflicting["data"]["input"] = json!({"content": "different immutable guidance"});
        assert_eq!(
            store
                .admit_run_guidance(guidance_admission_request(
                    "guidance-duplicate",
                    "intent-exact",
                    &conflicting,
                    false,
                ))
                .await
                .unwrap(),
            AtomicRunGuidanceAdmission::IdentityConflict
        );
    }

    #[tokio::test]
    async fn atomic_guidance_rechecks_fence_after_a_stale_snapshot_barrier() {
        let store = std::sync::Arc::new(InMemoryRunStateStore::new());
        store
            .insert_run(durable_run_record("guidance-fence-barrier"))
            .await
            .unwrap();
        let snapshot_observed = std::sync::Arc::new(tokio::sync::Barrier::new(2));
        let fence_committed = std::sync::Arc::new(tokio::sync::Barrier::new(2));
        let submitter = {
            let store = store.clone();
            let snapshot_observed = snapshot_observed.clone();
            let fence_committed = fence_committed.clone();
            tokio::spawn(async move {
                let stale = store
                    .load_run_guidance_admission(
                        "u1",
                        "guidance-fence-barrier",
                        "intent-after-fence",
                    )
                    .await
                    .unwrap()
                    .unwrap();
                assert!(!stale.settlement_fenced);
                snapshot_observed.wait().await;
                fence_committed.wait().await;
                let event = user_intent_event("intent-after-fence");
                store
                    .admit_run_guidance(guidance_admission_request(
                        "guidance-fence-barrier",
                        "intent-after-fence",
                        &event,
                        true,
                    ))
                    .await
                    .unwrap()
            })
        };
        snapshot_observed.wait().await;
        store
            .append_event(
                "u1",
                "s1",
                "guidance-fence-barrier",
                make_event("user_intent_settlement_fenced", json!({})),
            )
            .await
            .unwrap();
        fence_committed.wait().await;
        assert_eq!(
            submitter.await.unwrap(),
            AtomicRunGuidanceAdmission::SettlementFenced
        );
        let run = store
            .load_run("u1", "guidance-fence-barrier")
            .await
            .unwrap()
            .unwrap();
        assert!(
            !run.events
                .iter()
                .any(|event| extract_event_type(event) == "user_intent")
        );
    }

    #[tokio::test]
    async fn atomic_guidance_rechecks_lease_after_a_stale_snapshot_barrier() {
        let store = std::sync::Arc::new(InMemoryRunStateStore::new());
        let mut run = durable_run_record("guidance-lease-barrier");
        run.owner_pod_id = Some("local-owner".to_string());
        run.owner_lease_expires_at =
            Some((chrono::Utc::now() + chrono::Duration::minutes(2)).to_rfc3339());
        store.insert_run(run).await.unwrap();
        let snapshot = store
            .load_run_guidance_admission("u1", "guidance-lease-barrier", "intent-after-expiry")
            .await
            .unwrap()
            .unwrap();
        assert!(snapshot.owner_lease_live);
        {
            let mut runs = store.runs.write().await;
            runs.get_mut("guidance-lease-barrier")
                .unwrap()
                .owner_lease_expires_at =
                Some((chrono::Utc::now() - chrono::Duration::minutes(2)).to_rfc3339());
        }
        let event = user_intent_event("intent-after-expiry");
        assert!(matches!(
            store
                .admit_run_guidance(guidance_admission_request(
                    "guidance-lease-barrier",
                    "intent-after-expiry",
                    &event,
                    false,
                ))
                .await
                .unwrap(),
            AtomicRunGuidanceAdmission::ConsumerNotLive { .. }
        ));
        let run = store
            .load_run("u1", "guidance-lease-barrier")
            .await
            .unwrap()
            .unwrap();
        assert!(
            !run.events
                .iter()
                .any(|event| extract_event_type(event) == "user_intent")
        );
    }

    #[tokio::test]
    async fn concurrent_guidance_and_settlement_fence_have_a_valid_linearized_order() {
        for attempt in 0..32 {
            let store = std::sync::Arc::new(InMemoryRunStateStore::new());
            let run_id = format!("guidance-fence-race-{attempt}");
            store.insert_run(durable_run_record(&run_id)).await.unwrap();
            let event = user_intent_event("intent-race");
            let start = std::sync::Arc::new(tokio::sync::Barrier::new(3));
            let guidance = {
                let store = store.clone();
                let run_id = run_id.clone();
                let event = event.clone();
                let start = start.clone();
                tokio::spawn(async move {
                    start.wait().await;
                    store
                        .admit_run_guidance(guidance_admission_request(
                            &run_id,
                            "intent-race",
                            &event,
                            true,
                        ))
                        .await
                        .unwrap()
                })
            };
            let fence = {
                let store = store.clone();
                let run_id = run_id.clone();
                let start = start.clone();
                tokio::spawn(async move {
                    start.wait().await;
                    store
                        .transition_user_intent_admission(
                            AtomicRunUserIntentAdmissionTransitionRequest {
                                user_id: "u1",
                                run_id: &run_id,
                                expected_session_id: "s1",
                                expected_owner_generation: 0,
                                transition: RunUserIntentAdmissionTransition::Fence,
                            },
                        )
                        .await
                        .unwrap()
                })
            };
            start.wait().await;
            let outcome = guidance.await.unwrap();
            assert!(matches!(
                fence.await.unwrap(),
                AtomicRunUserIntentAdmissionTransition::Changed { .. }
            ));
            let run = store.load_run("u1", &run_id).await.unwrap().unwrap();
            let intent_position = run
                .events
                .iter()
                .position(|event| extract_event_type(event) == "user_intent");
            let fence_position = run
                .events
                .iter()
                .position(|event| extract_event_type(event) == "user_intent_settlement_fenced")
                .unwrap();
            match outcome {
                AtomicRunGuidanceAdmission::Committed { event_index } => {
                    assert!(intent_position.is_some_and(|index| index < fence_position));
                    assert!(matches!(
                        store
                            .apply_run_user_intents(AtomicRunUserIntentApplyRequest {
                                user_id: "u1",
                                run_id: &run_id,
                                expected_session_id: "s1",
                                expected_owner_generation: 0,
                                source_event_indices: &[event_index],
                            })
                            .await
                            .unwrap(),
                        AtomicRunUserIntentApply::Applied { .. }
                    ));
                }
                AtomicRunGuidanceAdmission::SettlementFenced => {
                    assert!(intent_position.is_none())
                }
                other => panic!("unexpected race outcome: {other:?}"),
            }
        }
    }

    fn edge_tool_request_event(request_id: &str, tool: &str) -> serde_json::Value {
        json!({
            "event_type": "tool_request",
            "idempotency_key": format!("edge-tool-request:{request_id}"),
            "data": {
                "request_id": request_id,
                "tool": tool,
                "arguments": {"path": "/workspace/output.txt"}
            }
        })
    }

    fn guarded_tool_request<'a>(
        run_id: &'a str,
        action_id: &'a str,
        tool_request_event: &'a serde_json::Value,
    ) -> AtomicRunToolRequestCommitRequest<'a> {
        AtomicRunToolRequestCommitRequest {
            action: AtomicRunActionAdmissionRequest {
                user_id: "u1",
                run_id,
                expected_session_id: "s1",
                action_id,
                expected_control_epoch: -1,
                expected_owner_generation: 0,
            },
            tool_request_event,
        }
    }

    fn ack_recovery_receipt() -> AtomicRunToolRequestCommitReceipt {
        AtomicRunToolRequestCommitReceipt {
            action_event_index: 7,
            tool_request_event_index: 8,
            tool_request_event_hash: "exact-request-hash".to_string(),
        }
    }

    fn ack_authority_snapshot(
        status: &str,
        generation: u64,
        owner_pod_id: Option<&str>,
        lease_active: bool,
    ) -> RunExecutionAuthoritySnapshot {
        RunExecutionAuthoritySnapshot {
            status: status.to_string(),
            owner_generation: generation,
            owner_pod_id: owner_pod_id.map(ToString::to_string),
            owner_lease_active: lease_active,
            cancellation_requested: false,
        }
    }

