    #[tokio::test]
    async fn guarded_tool_request_commits_authority_and_outbox_as_one_replayable_pair() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("guarded-edge-pair"))
            .await
            .unwrap();
        let event = edge_tool_request_event("write-a", "write_file");
        let request = guarded_tool_request("guarded-edge-pair", "turn:1:round:0:edge:a", &event);

        let first = store.commit_guarded_tool_request(request).await.unwrap();
        assert!(matches!(
            first,
            AtomicRunToolRequestCommitOutcome::Committed(AtomicRunToolRequestCommitReceipt {
                action_event_index: 0,
                tool_request_event_index: 1,
                ..
            })
        ));
        let replay = store.commit_guarded_tool_request(request).await.unwrap();
        assert!(matches!(
            replay,
            AtomicRunToolRequestCommitOutcome::AlreadyCommitted(
                AtomicRunToolRequestCommitReceipt {
                    action_event_index: 0,
                    tool_request_event_index: 1,
                    ..
                }
            )
        ));
        let run = store
            .load_run("u1", "guarded-edge-pair")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(run.last_event_idx, 1);
        assert_eq!(
            run.events
                .iter()
                .map(extract_event_type)
                .collect::<Vec<_>>(),
            [ACTION_ADMISSION_GRANTED_EVENT_TYPE, "tool_request"]
        );
    }

