    #[tokio::test]
    async fn cancelled_action_before_suspension_free_commit_never_publishes_a_grant() {
        let store = Arc::new(InMemoryRunStateStore::new());
        store
            .insert_run(durable_run_record("action-projection-cancel"))
            .await
            .unwrap();

        // Hold the canonical run lock so begin_action can acquire its per-run
        // authority fence but cannot enter the suspension-free mutation.
        let runs_guard = store.runs.write().await;
        let action_fence = store.action_fence_for("u1", "action-projection-cancel");
        let action_store = Arc::clone(&store);
        let action = tokio::spawn(async move {
            action_store
                .begin_action(action_admission_request("action-projection-cancel"))
                .await
        });
        let reached_precommit = tokio::time::timeout(std::time::Duration::from_secs(1), async {
            loop {
                if action_fence.try_lock().is_err() {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await;
        assert!(
            reached_precommit.is_ok(),
            "action never reached precommit wait"
        );

        action.abort();
        assert!(action.await.unwrap_err().is_cancelled());
        drop(runs_guard);

        let run = store
            .load_run("u1", "action-projection-cancel")
            .await
            .unwrap()
            .unwrap();
        assert!(
            run.events.is_empty(),
            "cancellation before the no-suspension commit section must not strand an action grant"
        );
    }

    #[tokio::test]
    async fn atomic_action_admission_accepts_observed_intent_and_replays_exact_start() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("action-observed-intent"))
            .await
            .unwrap();
        store
            .append_event(
                "u1",
                "s1",
                "action-observed-intent",
                user_intent_event("intent-observed"),
            )
            .await
            .unwrap();
        let mut request = action_admission_request("action-observed-intent");
        request.expected_control_epoch = 0;

        let started = store.begin_action(request).await.unwrap();
        assert_eq!(
            started,
            AtomicRunActionAdmission::Started { event_index: 1 }
        );
        assert!(started.is_fresh_grant());
        assert!(AtomicRunActionAdmission::AckRecoveredStarted { event_index: 1 }.is_fresh_grant());
        let replay = store.begin_action(request).await.unwrap();
        assert_eq!(
            replay,
            AtomicRunActionAdmission::AlreadyStarted { event_index: 1 }
        );
        assert!(
            !replay.is_fresh_grant(),
            "a pre-existing durable start must never replay an external side effect"
        );
        let run = store
            .load_run("u1", "action-observed-intent")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            run.events
                .iter()
                .filter(|event| {
                    extract_event_type(event) == ACTION_ADMISSION_GRANTED_EVENT_TYPE
                })
                .count(),
            1
        );
    }

    #[tokio::test]
    async fn concurrent_action_and_user_intent_have_one_linearized_winner() {
        let store = Arc::new(InMemoryRunStateStore::new());
        store
            .insert_run(durable_run_record("action-race"))
            .await
            .unwrap();
        let barrier = Arc::new(tokio::sync::Barrier::new(3));

        let action_store = Arc::clone(&store);
        let action_barrier = Arc::clone(&barrier);
        let action = tokio::spawn(async move {
            action_barrier.wait().await;
            action_store
                .begin_action(action_admission_request("action-race"))
                .await
                .unwrap()
        });
        let intent_store = Arc::clone(&store);
        let intent_barrier = Arc::clone(&barrier);
        let intent = tokio::spawn(async move {
            intent_barrier.wait().await;
            intent_store
                .update_run_status_with_events_if_current(
                    "u1",
                    "s1",
                    "action-race",
                    &[STATUS_RUNNING],
                    None,
                    STATUS_RUNNING,
                    None,
                    None,
                    &[user_intent_event("intent-race")],
                )
                .await
                .unwrap()
        });
        barrier.wait().await;
        let (action_outcome, intent_committed) = tokio::join!(action, intent);
        let action_outcome = action_outcome.unwrap();
        assert!(intent_committed.unwrap());

        let run = store.load_run("u1", "action-race").await.unwrap().unwrap();
        let action_index = run
            .events
            .iter()
            .position(|event| extract_event_type(event) == ACTION_ADMISSION_GRANTED_EVENT_TYPE);
        let intent_index = run
            .events
            .iter()
            .position(|event| extract_event_type(event) == "user_intent")
            .expect("intent committed");
        match action_outcome {
            AtomicRunActionAdmission::Started { event_index } => {
                assert_eq!(Some(event_index as usize), action_index);
                assert!(action_index.unwrap() < intent_index);
            }
            AtomicRunActionAdmission::Superseded {
                user_intent_event_index,
            } => {
                assert_eq!(user_intent_event_index as usize, intent_index);
                assert!(action_index.is_none());
            }
            other => panic!("unexpected race outcome: {other:?}"),
        }
    }

    #[tokio::test]
    async fn atomic_action_admission_rejects_inactive_and_stale_owner() {
        let store = InMemoryRunStateStore::new();
        let mut waiting = durable_run_record("action-inactive");
        waiting.status = STATUS_WAITING.to_string();
        store.insert_run(waiting).await.unwrap();
        assert_eq!(
            store
                .begin_action(action_admission_request("action-inactive"))
                .await
                .unwrap(),
            AtomicRunActionAdmission::Inactive {
                status: STATUS_WAITING.to_string()
            }
        );

        let owner_store = InMemoryRunStateStore::new();
        let mut recovered = durable_run_record("action-stale-owner");
        recovered.run_generation = 2;
        owner_store.insert_run(recovered).await.unwrap();
        assert_eq!(
            owner_store
                .begin_action(action_admission_request("action-stale-owner"))
                .await
                .unwrap(),
            AtomicRunActionAdmission::OwnerGenerationMismatch {
                actual_owner_generation: 2
            }
        );

        let expired_store = InMemoryRunStateStore::new();
        let mut expired = durable_run_record("action-expired-owner");
        expired.owner_pod_id = Some("expired-pod".to_string());
        expired.owner_lease_expires_at =
            Some((chrono::Utc::now() - chrono::Duration::seconds(1)).to_rfc3339());
        expired_store.insert_run(expired).await.unwrap();
        let error = expired_store
            .begin_action(action_admission_request("action-expired-owner"))
            .await
            .expect_err("expired owner lease must fail closed");
        assert!(error.contains("owner lease expired"));
        assert!(
            expired_store
                .load_run("u1", "action-expired-owner")
                .await
                .unwrap()
                .unwrap()
                .events
                .is_empty()
        );
    }

    #[tokio::test]
    async fn late_action_projection_patch_cannot_overwrite_equal_index_pause() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("action-projection-race"))
            .await
            .unwrap();
        assert_eq!(
            store
                .begin_action(action_admission_request("action-projection-race"))
                .await
                .unwrap(),
            AtomicRunActionAdmission::Started { event_index: 0 }
        );
        let stale_running = store
            .load_run("u1", "action-projection-race")
            .await
            .unwrap()
            .unwrap();
        assert!(
            store
                .update_run_status_if_current(RunStatusCasRequest {
                    user_id: "u1",
                    expected_session_id: "s1",
                    run_id: "action-projection-race",
                    expected_statuses: &[STATUS_RUNNING],
                    status: STATUS_PAUSED,
                    waiting_for: None,
                    error_message: None,
                },)
                .await
                .unwrap()
        );

        // Model a delayed post-commit admission projection racing after the
        // equal-index pause projection. It may refresh event metadata only.
        store
            .sync_projection_event_metadata(
                &stale_running,
                stale_running.last_event_idx,
                ACTION_ADMISSION_GRANTED_EVENT_TYPE,
            )
            .await;
        let projection = store
            .load_run_projection("u1", "action-projection-race")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(projection.status, STATUS_PAUSED);
        assert_eq!(projection.waiting_for, None);
        assert_eq!(projection.projection_event_idx, 0);
        assert_eq!(
            projection.latest_event_type.as_deref(),
            Some(ACTION_ADMISSION_GRANTED_EVENT_TYPE)
        );
    }

