    #[tokio::test]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_atomic_action_admission_orders_intent_races_and_ack_retries_on_matrixone() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let user_id = format!("runs-it-action-user-{}", Uuid::new_v4());

        let insert_run = |run_id: &str, session_id: &str| {
            let mut record = durable_run_record(run_id);
            record.user_id = user_id.clone();
            record.session_id = session_id.to_string();
            record.root_run_id = Some(run_id.to_string());
            record.ancestor_path = Some(run_id.to_string());
            record
        };

        let action_first_run = format!("runs-it-action-first-{}", Uuid::new_v4());
        let action_first_session = format!("runs-it-action-s1-{}", Uuid::new_v4());
        cleanup_database_run_fixture(&pool, &user_id, &action_first_run).await;
        insert_active_database_session_fixture(&pool, &user_id, &action_first_session).await;
        store
            .insert_run(insert_run(&action_first_run, &action_first_session))
            .await
            .expect("insert action-first run");
        let action_first_request = AtomicRunActionAdmissionRequest {
            user_id: &user_id,
            run_id: &action_first_run,
            expected_session_id: &action_first_session,
            action_id: "tool-batch-action-first",
            expected_control_epoch: -1,
            expected_owner_generation: 0,
        };
        let started = store
            .begin_action(action_first_request)
            .await
            .expect("admit action before guidance");
        assert_eq!(
            started,
            AtomicRunActionAdmission::Started { event_index: 1 }
        );
        assert!(started.is_fresh_grant());
        // Simulate the caller retrying after losing the first response. A
        // pre-existing fact is observable but never authorizes replay.
        let ack_loss_retry = store
            .begin_action(action_first_request)
            .await
            .expect("reconcile exact action retry");
        assert_eq!(
            ack_loss_retry,
            AtomicRunActionAdmission::AlreadyStarted { event_index: 1 }
        );
        assert!(!ack_loss_retry.is_fresh_grant());

        let intent_first_run = format!("runs-it-intent-first-{}", Uuid::new_v4());
        let intent_first_session = format!("runs-it-intent-s1-{}", Uuid::new_v4());
        cleanup_database_run_fixture(&pool, &user_id, &intent_first_run).await;
        insert_active_database_session_fixture(&pool, &user_id, &intent_first_session).await;
        store
            .insert_run(insert_run(&intent_first_run, &intent_first_session))
            .await
            .expect("insert intent-first run");
        assert!(
            store
                .update_run_status_with_events_if_current(
                    &user_id,
                    &intent_first_session,
                    &intent_first_run,
                    &[STATUS_RUNNING],
                    Some(0),
                    STATUS_RUNNING,
                    None,
                    None,
                    &[user_intent_event("matrix-intent-first")],
                )
                .await
                .expect("commit user intent first")
        );
        assert_eq!(
            store
                .begin_action(AtomicRunActionAdmissionRequest {
                    user_id: &user_id,
                    run_id: &intent_first_run,
                    expected_session_id: &intent_first_session,
                    action_id: "tool-batch-intent-first",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .expect("intent must supersede stale action"),
            AtomicRunActionAdmission::Superseded {
                user_intent_event_index: 1
            }
        );

        let race_run = format!("runs-it-action-race-{}", Uuid::new_v4());
        let race_session = format!("runs-it-action-race-session-{}", Uuid::new_v4());
        cleanup_database_run_fixture(&pool, &user_id, &race_run).await;
        insert_active_database_session_fixture(&pool, &user_id, &race_session).await;
        store
            .insert_run(insert_run(&race_run, &race_session))
            .await
            .expect("insert race run");
        let action = store.begin_action(AtomicRunActionAdmissionRequest {
            user_id: &user_id,
            run_id: &race_run,
            expected_session_id: &race_session,
            action_id: "tool-batch-race",
            expected_control_epoch: -1,
            expected_owner_generation: 0,
        });
        let expected_running = [STATUS_RUNNING];
        let race_intent_events = [user_intent_event("matrix-intent-race")];
        let intent = store.update_run_status_with_events_if_current(
            &user_id,
            &race_session,
            &race_run,
            &expected_running,
            Some(0),
            STATUS_RUNNING,
            None,
            None,
            &race_intent_events,
        );
        let (action_outcome, intent_outcome) = tokio::join!(action, intent);
        let action_outcome = action_outcome.expect("race action outcome");
        assert!(intent_outcome.expect("race intent outcome"));
        let race = store
            .load_run(&user_id, &race_run)
            .await
            .expect("load race run")
            .expect("race run exists");
        let action_index = race
            .events
            .iter()
            .position(|event| extract_event_type(event) == ACTION_ADMISSION_GRANTED_EVENT_TYPE);
        let intent_index = race
            .events
            .iter()
            .position(|event| extract_event_type(event) == "user_intent")
            .expect("race intent exists");
        match action_outcome {
            AtomicRunActionAdmission::Started { event_index } => {
                assert_eq!(Some(event_index as usize), action_index);
                assert!(action_index.unwrap() < intent_index);
            }
            AtomicRunActionAdmission::Superseded {
                user_intent_event_index,
            } => {
                assert_eq!(user_intent_event_index as usize, intent_index);
                assert!(action_index.is_none());
            }
            other => panic!("unexpected Matrix action race outcome: {other:?}"),
        }
        assert_eq!(
            store
                .begin_action(AtomicRunActionAdmissionRequest {
                    user_id: &user_id,
                    run_id: &race_run,
                    expected_session_id: &race_session,
                    action_id: "stale-owner-action",
                    expected_control_epoch: race.last_event_idx,
                    expected_owner_generation: 99,
                })
                .await
                .expect("stale owner outcome"),
            AtomicRunActionAdmission::OwnerGenerationMismatch {
                actual_owner_generation: 0
            }
        );

        for (run_id, session_id) in [
            (&action_first_run, &action_first_session),
            (&intent_first_run, &intent_first_session),
            (&race_run, &race_session),
        ] {
            cleanup_database_run_fixture(&pool, &user_id, run_id).await;
            sqlx::query(
                "DELETE FROM agent_session_execution_slots WHERE user_id = ? AND session_id = ?",
            )
            .bind(&user_id)
            .bind(session_id)
            .execute(pool.get())
            .await
            .expect("clean action admission execution slot");
        }
    }

    #[tokio::test]
    async fn append_events_batch_stores_events_in_order() {
        let store = InMemoryRunStateStore::new();
        let run = durable_run_record("batch-order");
        store.insert_run(run).await.unwrap();

        let events = vec![
            make_event("tool_call", json!({"tool": "read_file"})),
            make_event("tool_result", json!({"output": "hello"})),
            make_event("text_delta", json!({"chunk": "done"})),
        ];
        store
            .append_events_batch("u1", "s1", "batch-order", &events)
            .await
            .unwrap();

        let loaded = store.load_run("u1", "batch-order").await.unwrap().unwrap();
        assert_eq!(loaded.events.len(), 3);
        assert_eq!(loaded.events[0]["event_type"], "tool_call");
        assert_eq!(loaded.events[1]["event_type"], "tool_result");
        assert_eq!(loaded.events[2]["event_type"], "text_delta");
        assert_eq!(loaded.last_event_idx, 2);
    }

    #[tokio::test]
    async fn run_interaction_resolution_is_atomic_idempotent_and_conflict_safe() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("interaction-resolution"))
            .await
            .unwrap();
        let required = approval_required_event("approval-1", "bash", "s1");
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id: "interaction-resolution",
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: std::slice::from_ref(&required),
                },)
                .await
                .unwrap(),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: "u1",
                    expected_session_id: "s1",
                    run_id: "interaction-resolution",
                    request_id: "approval-1",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .unwrap(),
            DurableRunInteractionWaitOutcome::Waiting
        );
        let approved = json!({
            "request_id": "approval-1",
            "outcome": "approved",
            "decision": "allow",
            "tool": "bash",
            "approval_kind": "standard"
        });
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "interaction-resolution",
                    "approval-1",
                    DurableRunInteractionKind::Approval,
                    approved.clone(),
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Resolved(_)
        ));
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "interaction-resolution",
                    "approval-1",
                    DurableRunInteractionKind::Approval,
                    approved,
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Idempotent(_)
        ));
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "interaction-resolution",
                    "approval-1",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "approval-1",
                        "outcome": "denied",
                        "decision": "deny",
                        "tool": "bash",
                        "approval_kind": "standard"
                    }),
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Conflict(_)
        ));
        let run = store
            .load_run("u1", "interaction-resolution")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(run.status, STATUS_RUNNING);
        assert_eq!(run.waiting_for, None);
        assert_eq!(
            run.events
                .iter()
                .filter(|event| extract_event_type(event) == "approval_resolved")
                .count(),
            1
        );
        assert_eq!(run.events.last().unwrap()["event_type"], "run_resumed");
    }

    #[tokio::test]
    async fn approval_registration_is_an_exact_contiguous_set_and_rejects_duplicate_input() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("approval-exact-set"))
            .await
            .unwrap();
        let duplicate_request = [
            approval_required_event("duplicate", "bash", "s1"),
            approval_required_event("duplicate", "git", "s1"),
        ];
        assert!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id: "approval-exact-set",
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &duplicate_request,
                },)
                .await
                .unwrap_err()
                .contains("duplicate request_id")
        );
        let mut duplicate_key = [
            approval_required_event("duplicate-key-a", "bash", "s1"),
            approval_required_event("duplicate-key-b", "git", "s1"),
        ];
        duplicate_key[1]["idempotency_key"] = duplicate_key[0]["idempotency_key"].clone();
        assert!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id: "approval-exact-set",
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &duplicate_key,
                },)
                .await
                .unwrap_err()
                .contains("duplicate idempotency_key")
        );

        let first = [approval_required_event("exact-a", "bash", "s1")];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id: "approval-exact-set",
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &first,
                },)
                .await
                .unwrap(),
            AtomicRunInteractionBatchRegistration::Registered
        );
        let partial = [
            approval_required_event("exact-a", "bash", "s1"),
            approval_required_event("exact-b", "git", "s1"),
        ];
        let error = store
            .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                user_id: "u1",
                run_id: "approval-exact-set",
                expected_session_id: "s1",
                expected_control_epoch: -1,
                expected_owner_generation: 0,
                events: &partial,
            })
            .await
            .unwrap_err();
        assert!(
            error.contains("partial approval registration")
                || error.contains("immutable approval registration conflict")
        );
        let durable = store
            .load_run("u1", "approval-exact-set")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            durable
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "approval_required")
                .count(),
            1
        );

        let exact_store = InMemoryRunStateStore::new();
        exact_store
            .insert_run(durable_run_record("approval-exact-subset"))
            .await
            .unwrap();
        let complete = [
            approval_required_event("complete-a", "bash", "s1"),
            approval_required_event("complete-b", "git", "s1"),
        ];
        let complete_request = AtomicRunInteractionBatchRegistrationRequest {
            user_id: "u1",
            run_id: "approval-exact-subset",
            expected_session_id: "s1",
            expected_control_epoch: -1,
            expected_owner_generation: 0,
            events: &complete,
        };
        assert_eq!(
            exact_store
                .register_guarded_interaction_batch(complete_request)
                .await
                .unwrap(),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            exact_store
                .register_guarded_interaction_batch(complete_request)
                .await
                .unwrap(),
            AtomicRunInteractionBatchRegistration::Registered
        );
        let subset = [complete[1].clone()];
        assert!(
            exact_store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    events: &subset,
                    ..complete_request
                },)
                .await
                .unwrap_err()
                .contains("immutable approval registration conflict")
        );
        let durable = exact_store
            .load_run("u1", "approval-exact-subset")
            .await
            .unwrap()
            .unwrap();
        let registrations = durable
            .events
            .iter()
            .filter(|event| extract_event_type(event) == "approval_required")
            .collect::<Vec<_>>();
        assert_eq!(registrations.len(), 2);
        assert_eq!(registrations[0]["data"]["registration_batch_index"], 0);
        assert_eq!(registrations[1]["data"]["registration_batch_index"], 1);
        assert_eq!(
            registrations[0]["data"]["registration_batch_id"],
            registrations[1]["data"]["registration_batch_id"]
        );
    }

