    #[tokio::test]
    async fn terminal_transition_closes_only_unresolved_interactions_without_resuming() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("approval-terminal-close"))
            .await
            .unwrap();
        let required = [
            approval_required_event("terminal-complete", "bash", "s1"),
            approval_required_event("terminal-pending", "git", "s1"),
        ];
        store
            .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                user_id: "u1",
                run_id: "approval-terminal-close",
                expected_session_id: "s1",
                expected_control_epoch: -1,
                expected_owner_generation: 0,
                events: &required,
            })
            .await
            .unwrap();
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "approval-terminal-close",
                    "terminal-complete",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "terminal-complete",
                        "outcome": "approved",
                        "decision": "allow",
                        "tool": "bash",
                        "approval_kind": "standard",
                    }),
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Queued(_)
        ));
        assert!(
            store
                .update_run_status_with_event_if_current(
                    "u1",
                    "s1",
                    "approval-terminal-close",
                    &[STATUS_RUNNING],
                    STATUS_CANCELLED,
                    None,
                    None,
                    json!({
                        "event_type": "run_finished",
                        "idempotency_key": "terminal-close:run-finished",
                        "data": {
                            "status": STATUS_CANCELLED,
                            "cancelled": true,
                            "cancellation_origin": "runtime"
                        }
                    }),
                )
                .await
                .unwrap()
        );
        let durable = store
            .load_run("u1", "approval-terminal-close")
            .await
            .unwrap()
            .unwrap();
        let resolved = durable
            .events
            .iter()
            .filter(|event| extract_event_type(event) == "approval_resolved")
            .collect::<Vec<_>>();
        assert_eq!(resolved.len(), 2);
        assert_eq!(
            resolved
                .iter()
                .filter(|event| {
                    extract_interaction_request_id(event).as_deref() == Some("terminal-complete")
                })
                .count(),
            1,
            "terminal closure must resolve a queued pre-frontier sibling exactly once"
        );
        assert!(resolved.iter().any(|event| {
            extract_interaction_request_id(event).as_deref() == Some("terminal-pending")
                && event
                    .pointer("/data/decision")
                    .and_then(serde_json::Value::as_str)
                    == Some("deny")
        }));
        assert!(
            durable
                .events
                .iter()
                .all(|event| extract_event_type(event) != "run_resumed")
        );
        let closure_index = durable
            .events
            .iter()
            .position(|event| {
                extract_event_type(event) == "approval_resolved"
                    && extract_interaction_request_id(event).as_deref() == Some("terminal-pending")
            })
            .unwrap();
        let terminal_index = durable
            .events
            .iter()
            .position(|event| extract_event_type(event) == "run_finished")
            .unwrap();
        assert!(closure_index < terminal_index);
        assert_eq!(
            durable.events.last().map(extract_event_type).as_deref(),
            Some("run_finished")
        );
    }

    #[tokio::test]
    async fn every_terminal_status_closes_approval_and_ask_user_with_stable_authority_loss() {
        for status in [STATUS_CANCELLED, STATUS_FAILED, STATUS_COMPLETED] {
            let run_id = format!("terminal-interactions-{status}");
            let approval_id = format!("approval-{status}");
            let ask_user_id = format!("ask-user-{status}");
            let store = InMemoryRunStateStore::new();
            store.insert_run(durable_run_record(&run_id)).await.unwrap();
            let approval = [approval_required_event(&approval_id, "bash", "s1")];
            let ask_user = [ask_user_prompted_event(&ask_user_id, "s1")];
            for (kind, events) in [
                (DurableRunInteractionKind::Approval, approval.as_slice()),
                (DurableRunInteractionKind::AskUser, ask_user.as_slice()),
            ] {
                assert_eq!(
                    store
                        .register_guarded_interaction_batch(
                            AtomicRunInteractionBatchRegistrationRequest {
                                user_id: "u1",
                                run_id: &run_id,
                                expected_session_id: "s1",
                                expected_control_epoch: -1,
                                expected_owner_generation: 0,
                                events,
                            },
                        )
                        .await
                        .unwrap(),
                    AtomicRunInteractionBatchRegistration::Registered,
                    "register {kind:?} before {status}"
                );
            }
            let terminal_data = if status == STATUS_CANCELLED {
                json!({
                    "status": status,
                    "cancelled": true,
                    "cancellation_origin": "runtime",
                })
            } else {
                json!({"status": status})
            };
            assert!(
                store
                    .update_run_status_with_event_if_current(
                        "u1",
                        "s1",
                        &run_id,
                        &[STATUS_RUNNING],
                        status,
                        None,
                        None,
                        json!({
                            "event_type": "run_finished",
                            "idempotency_key": format!("terminal-interactions:{status}"),
                            "data": terminal_data,
                        }),
                    )
                    .await
                    .unwrap()
            );

            let terminal = store.load_run("u1", &run_id).await.unwrap().unwrap();
            let closure_indices = [
                ("approval_resolved", approval_id.as_str()),
                ("ask_user_resolved", ask_user_id.as_str()),
            ]
            .map(|(event_type, request_id)| {
                let (index, event) = terminal
                    .events
                    .iter()
                    .enumerate()
                    .find(|(_, event)| {
                        extract_event_type(event) == event_type
                            && extract_interaction_request_id(event).as_deref() == Some(request_id)
                    })
                    .expect("terminal interaction closure");
                assert_eq!(
                    event
                        .pointer("/data/_durable_resolution/disposition")
                        .and_then(serde_json::Value::as_str),
                    Some("authority_lost")
                );
                assert_eq!(
                    event
                        .pointer("/data/_durable_resolution/authority_loss/kind")
                        .and_then(serde_json::Value::as_str),
                    Some("inactive")
                );
                assert_eq!(
                    event
                        .pointer("/data/_durable_resolution/authority_loss/status")
                        .and_then(serde_json::Value::as_str),
                    Some(status)
                );
                assert_eq!(
                    event
                        .pointer("/data/_durable_resolution/actual_status")
                        .and_then(serde_json::Value::as_str),
                    Some(status),
                    "receipt snapshot must describe the planned terminal cut"
                );
                assert!(
                    event
                        .pointer("/data/_durable_resolution/actual_waiting_for")
                        .is_some_and(serde_json::Value::is_null)
                );
                index
            });
            let terminal_index = terminal
                .events
                .iter()
                .position(|event| extract_event_type(event) == "run_finished")
                .unwrap();
            assert!(
                closure_indices
                    .into_iter()
                    .all(|index| index < terminal_index)
            );
            assert!(
                terminal
                    .events
                    .iter()
                    .all(|event| extract_event_type(event) != "run_resumed")
            );
            assert_eq!(terminal.last_event_idx, terminal.events.len() as i64 - 1);

            let approval_response = json!({
                "request_id": approval_id,
                "outcome": "approved",
                "decision": "allow",
                "tool": "bash",
                "approval_kind": "standard",
            });
            let ask_user_response = json!({
                "request_id": ask_user_id,
                "outcome": "submitted",
                "answers": {"answers": []},
            });
            let event_count = terminal.events.len();
            for _ in 0..2 {
                for (request_id, kind, response) in [
                    (
                        approval_id.as_str(),
                        DurableRunInteractionKind::Approval,
                        approval_response.clone(),
                    ),
                    (
                        ask_user_id.as_str(),
                        DurableRunInteractionKind::AskUser,
                        ask_user_response.clone(),
                    ),
                ] {
                    assert!(matches!(
                        store
                            .resolve_run_interaction(
                                "u1",
                                "s1",
                                &run_id,
                                request_id,
                                kind,
                                response,
                            )
                            .await
                            .unwrap(),
                        DurableRunInteractionResolveOutcome::AuthorityLost {
                            reason: DurableRunInteractionAuthorityLoss::Inactive { status: ref durable_status },
                            ..
                        } if durable_status == status
                    ));
                }
            }
            assert_eq!(
                store
                    .load_run("u1", &run_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .events
                    .len(),
                event_count,
                "late identical retries must not append after {status}"
            );
        }
    }

    #[tokio::test]
    async fn approval_callback_records_but_cannot_resume_after_owner_generation_loss() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("approval-authority-loss"))
            .await
            .unwrap();
        let required = [approval_required_event("authority-a", "bash", "s1")];
        store
            .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                user_id: "u1",
                run_id: "approval-authority-loss",
                expected_session_id: "s1",
                expected_control_epoch: -1,
                expected_owner_generation: 0,
                events: &required,
            })
            .await
            .unwrap();
        store
            .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                user_id: "u1",
                run_id: "approval-authority-loss",
                expected_session_id: "s1",
                request_id: "authority-a",
                kind: DurableRunInteractionKind::Approval,
                expected_control_epoch: -1,
                expected_owner_generation: 0,
            })
            .await
            .unwrap();
        store
            .runs
            .write()
            .await
            .get_mut("approval-authority-loss")
            .unwrap()
            .run_generation = 1;
        let outcome = store
            .resolve_run_interaction(
                "u1",
                "s1",
                "approval-authority-loss",
                "authority-a",
                DurableRunInteractionKind::Approval,
                json!({
                    "request_id": "authority-a",
                    "outcome": "approved",
                    "decision": "allow",
                    "tool": "bash",
                    "approval_kind": "standard",
                }),
            )
            .await
            .unwrap();
        assert!(matches!(
            outcome,
            DurableRunInteractionResolveOutcome::AuthorityLost {
                reason: DurableRunInteractionAuthorityLoss::OwnerGenerationMismatch {
                    actual_owner_generation: 1
                },
                ..
            }
        ));
        let durable = store
            .load_run("u1", "approval-authority-loss")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(durable.status, STATUS_WAITING);
        assert!(durable.events.iter().any(|event| {
            extract_event_type(event) == "approval_resolved"
                && extract_interaction_request_id(event).as_deref() == Some("authority-a")
        }));
        assert!(
            durable
                .events
                .iter()
                .all(|event| extract_event_type(event) != "run_resumed")
        );
    }

    #[tokio::test]
    async fn approval_callback_owner_and_lease_loss_are_durable_without_resume() {
        for (run_id, request_id, lose_owner) in [
            ("approval-owner-loss", "owner-loss", true),
            ("approval-lease-loss", "lease-loss", false),
        ] {
            let store = InMemoryRunStateStore::new();
            let mut run = durable_run_record(run_id);
            run.owner_pod_id = Some("initial-owner".to_string());
            run.owner_lease_expires_at = Some("2999-01-01T00:00:00Z".to_string());
            store.insert_run(run).await.unwrap();
            let required = [approval_required_event(request_id, "bash", "s1")];
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id,
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &required,
                })
                .await
                .unwrap();
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: "u1",
                    run_id,
                    expected_session_id: "s1",
                    request_id,
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .unwrap();
            {
                let mut runs = store.runs.write().await;
                let run = runs.get_mut(run_id).unwrap();
                if lose_owner {
                    run.owner_pod_id = Some("replacement-owner".to_string());
                } else {
                    run.owner_lease_expires_at = Some("1970-01-01T00:00:00Z".to_string());
                }
            }
            let outcome = store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    run_id,
                    request_id,
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": request_id,
                        "outcome": "approved",
                        "decision": "allow",
                        "tool": "bash",
                        "approval_kind": "standard",
                    }),
                )
                .await
                .unwrap();
            assert!(
                matches!(
                    (&outcome, lose_owner),
                    (
                        DurableRunInteractionResolveOutcome::AuthorityLost {
                            reason: DurableRunInteractionAuthorityLoss::OwnerMismatch { .. },
                            ..
                        },
                        true
                    ) | (
                        DurableRunInteractionResolveOutcome::AuthorityLost {
                            reason: DurableRunInteractionAuthorityLoss::OwnerLeaseExpired,
                            ..
                        },
                        false
                    )
                ),
                "unexpected authority outcome: {outcome:?}"
            );
            let durable = store.load_run("u1", run_id).await.unwrap().unwrap();
            assert_eq!(durable.status, STATUS_WAITING);
            assert!(durable.events.iter().any(|event| {
                extract_event_type(event) == "approval_resolved"
                    && extract_interaction_request_id(event).as_deref() == Some(request_id)
            }));
            assert!(
                durable
                    .events
                    .iter()
                    .all(|event| extract_event_type(event) != "run_resumed")
            );
        }
    }

