    #[tokio::test]
    async fn later_approval_callback_is_queued_until_its_exact_frontier_promotes_it() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("approval-frontier"))
            .await
            .unwrap();
        let required = [
            approval_required_event("approval-a", "bash", "s1"),
            approval_required_event("approval-b", "git", "s1"),
        ];
        assert_eq!(
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id: "approval-frontier",
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &required,
                },)
                .await
                .unwrap(),
            AtomicRunInteractionBatchRegistration::Registered
        );
        assert_eq!(
            store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: "u1",
                    expected_session_id: "s1",
                    run_id: "approval-frontier",
                    request_id: "approval-a",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
                .unwrap(),
            DurableRunInteractionWaitOutcome::Waiting
        );

        let later = json!({
            "request_id": "approval-b",
            "outcome": "approved",
            "decision": "allow",
            "tool": "git",
            "approval_kind": "standard",
        });
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "approval-frontier",
                    "approval-b",
                    DurableRunInteractionKind::Approval,
                    later.clone(),
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Queued(_)
        ));
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "approval-frontier",
                    "approval-b",
                    DurableRunInteractionKind::Approval,
                    later,
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Queued(_)
        ));
        let waiting = store
            .load_run("u1", "approval-frontier")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(waiting.status, STATUS_WAITING);
        assert_eq!(waiting.waiting_for.as_deref(), Some("tool_approval"));
        assert_eq!(
            waiting
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "run_resumed")
                .count(),
            0
        );
        assert_eq!(
            waiting
                .events
                .iter()
                .filter(|event| {
                    extract_event_type(event) == APPROVAL_DECISION_QUEUED_EVENT_TYPE
                })
                .count(),
            1,
            "exact callback retry must not duplicate the queued fact"
        );

        let frontier = json!({
            "request_id": "approval-a",
            "outcome": "denied",
            "decision": "deny",
            "tool": "bash",
            "approval_kind": "standard",
        });
        assert!(matches!(
            store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "approval-frontier",
                    "approval-a",
                    DurableRunInteractionKind::Approval,
                    frontier,
                )
                .await
                .unwrap(),
            DurableRunInteractionResolveOutcome::Resolved(_)
        ));
        let resumed = store
            .load_run("u1", "approval-frontier")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(resumed.status, STATUS_RUNNING);
        assert_eq!(resumed.waiting_for, None);
        assert_eq!(
            resumed
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "run_resumed")
                .count(),
            1
        );
        let promoted = store
            .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                user_id: "u1",
                expected_session_id: "s1",
                run_id: "approval-frontier",
                request_id: "approval-b",
                kind: DurableRunInteractionKind::Approval,
                expected_control_epoch: -1,
                expected_owner_generation: 0,
            })
            .await
            .unwrap();
        let DurableRunInteractionWaitOutcome::AlreadyResolved(promoted) = promoted else {
            panic!("queued approval was not promoted at its exact frontier: {promoted:?}");
        };
        assert_eq!(promoted.pointer("/data/decision"), Some(&json!("allow")));
        assert_eq!(
            promoted.pointer("/data/_durable_resolution/disposition"),
            Some(&json!("resumed"))
        );
        let promoted_run = store
            .load_run("u1", "approval-frontier")
            .await
            .unwrap()
            .unwrap();
        let b_facts = promoted_run
            .events
            .iter()
            .filter(|event| extract_interaction_request_id(event).as_deref() == Some("approval-b"))
            .map(extract_event_type)
            .collect::<Vec<_>>();
        assert_eq!(
            b_facts,
            vec![
                "approval_required",
                APPROVAL_DECISION_QUEUED_EVENT_TYPE,
                "interaction_wait_started",
                "approval_resolved",
                "run_resumed",
            ]
        );
    }

