    #[tokio::test]
    async fn approval_callback_and_frontier_race_converges_to_one_resumed_resolution() {
        let store = std::sync::Arc::new(InMemoryRunStateStore::new());
        store
            .insert_run(durable_run_record("approval-frontier-race"))
            .await
            .unwrap();
        let required = [approval_required_event("race-a", "bash", "s1")];
        store
            .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                user_id: "u1",
                run_id: "approval-frontier-race",
                expected_session_id: "s1",
                expected_control_epoch: -1,
                expected_owner_generation: 0,
                events: &required,
            })
            .await
            .unwrap();
        let callback_store = store.clone();
        let callback = tokio::spawn(async move {
            callback_store
                .resolve_run_interaction(
                    "u1",
                    "s1",
                    "approval-frontier-race",
                    "race-a",
                    DurableRunInteractionKind::Approval,
                    json!({
                        "request_id": "race-a",
                        "outcome": "approved",
                        "decision": "allow",
                        "tool": "bash",
                        "approval_kind": "standard",
                    }),
                )
                .await
        });
        let frontier_store = store.clone();
        let frontier = tokio::spawn(async move {
            frontier_store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: "u1",
                    run_id: "approval-frontier-race",
                    expected_session_id: "s1",
                    request_id: "race-a",
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                })
                .await
        });
        let (callback, frontier) = tokio::join!(callback, frontier);
        let callback = callback.unwrap().unwrap();
        let frontier = frontier.unwrap().unwrap();
        assert!(matches!(
            &callback,
            DurableRunInteractionResolveOutcome::Queued(_)
                | DurableRunInteractionResolveOutcome::Resolved(_)
                | DurableRunInteractionResolveOutcome::Idempotent(_)
        ));
        assert!(matches!(
            &frontier,
            DurableRunInteractionWaitOutcome::Waiting
                | DurableRunInteractionWaitOutcome::AlreadyResolved(_)
        ));
        if matches!(&callback, DurableRunInteractionResolveOutcome::Queued(_)) {
            assert!(matches!(
                store
                    .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                        user_id: "u1",
                        run_id: "approval-frontier-race",
                        expected_session_id: "s1",
                        request_id: "race-a",
                        kind: DurableRunInteractionKind::Approval,
                        expected_control_epoch: -1,
                        expected_owner_generation: 0,
                    })
                    .await
                    .unwrap(),
                DurableRunInteractionWaitOutcome::AlreadyResolved(_)
            ));
        }
        let durable = store
            .load_run("u1", "approval-frontier-race")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            durable
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "approval_resolved")
                .count(),
            1
        );
        assert_eq!(
            durable
                .events
                .iter()
                .filter(|event| extract_event_type(event) == "run_resumed")
                .count(),
            1
        );
        let resolution = durable
            .events
            .iter()
            .find(|event| extract_event_type(event) == "approval_resolved")
            .unwrap();
        assert_eq!(
            resolution.pointer("/data/_durable_resolution/disposition"),
            Some(&json!("resumed"))
        );
    }

    #[tokio::test]
    async fn queued_approval_is_terminalized_without_execution_after_authority_changes() {
        for mode in ["cancel", "owner_transfer", "lease_loss", "guidance"] {
            let run_id = format!("queued-authority-{mode}");
            let request_id = format!("queued-{mode}");
            let store = InMemoryRunStateStore::new();
            let mut run = durable_run_record(&run_id);
            if mode == "lease_loss" {
                run.owner_pod_id = Some("owner-a".to_string());
                run.owner_lease_expires_at =
                    Some((chrono::Utc::now() + chrono::Duration::minutes(5)).to_rfc3339());
            }
            store.insert_run(run).await.unwrap();
            let required = [approval_required_event(&request_id, "bash", "s1")];
            store
                .register_guarded_interaction_batch(AtomicRunInteractionBatchRegistrationRequest {
                    user_id: "u1",
                    run_id: &run_id,
                    expected_session_id: "s1",
                    expected_control_epoch: -1,
                    expected_owner_generation: 0,
                    events: &required,
                })
                .await
                .unwrap();
            assert!(matches!(
                store
                    .resolve_run_interaction(
                        "u1",
                        "s1",
                        &run_id,
                        &request_id,
                        DurableRunInteractionKind::Approval,
                        json!({
                            "request_id": request_id,
                            "outcome": "approved",
                            "decision": "allow",
                            "tool": "bash",
                            "approval_kind": "standard",
                        }),
                    )
                    .await
                    .unwrap(),
                DurableRunInteractionResolveOutcome::Queued(_)
            ));
            match mode {
                "cancel" => {
                    assert!(
                        store
                            .update_run_status_with_event_if_current(
                                "u1",
                                "s1",
                                &run_id,
                                &[STATUS_RUNNING],
                                STATUS_CANCELLED,
                                None,
                                None,
                                json!({
                                    "event_type": "run_finished",
                                    "idempotency_key": format!("{run_id}:cancelled"),
                                    "data": {
                                        "status": STATUS_CANCELLED,
                                        "cancelled": true,
                                        "cancellation_origin": "runtime",
                                    },
                                }),
                            )
                            .await
                            .unwrap()
                    );
                }
                "owner_transfer" => {
                    let mut runs = store.runs.write().await;
                    let run = runs.get_mut(&run_id).unwrap();
                    run.run_generation = 1;
                    run.owner_pod_id = Some("owner-b".to_string());
                    run.owner_lease_expires_at =
                        Some((chrono::Utc::now() + chrono::Duration::minutes(5)).to_rfc3339());
                }
                "lease_loss" => {
                    let mut runs = store.runs.write().await;
                    runs.get_mut(&run_id).unwrap().owner_lease_expires_at =
                        Some((chrono::Utc::now() - chrono::Duration::seconds(1)).to_rfc3339());
                }
                "guidance" => {
                    store
                        .append_event(
                            "u1",
                            "s1",
                            &run_id,
                            json!({
                                "event_type": "user_intent",
                                "idempotency_key": format!("{run_id}:guidance"),
                                "data": {"intent_id": "new-guidance"},
                            }),
                        )
                        .await
                        .unwrap();
                }
                _ => unreachable!(),
            }
            let outcome = store
                .begin_run_interaction_wait(AtomicRunInteractionWaitRequest {
                    user_id: "u1",
                    run_id: &run_id,
                    expected_session_id: "s1",
                    request_id: &request_id,
                    kind: DurableRunInteractionKind::Approval,
                    expected_control_epoch: -1,
                    expected_owner_generation: if mode == "owner_transfer" { 1 } else { 0 },
                })
                .await
                .unwrap();
            let DurableRunInteractionWaitOutcome::AlreadyResolved(event) = outcome else {
                panic!("queued {mode} approval was not terminalized: {outcome:?}");
            };
            assert_ne!(
                event.pointer("/data/_durable_resolution/disposition"),
                Some(&json!("resumed")),
                "{mode} must never promote queued execution"
            );
            let durable = store.load_run("u1", &run_id).await.unwrap().unwrap();
            assert!(durable.events.iter().all(|event| {
                extract_interaction_request_id(event).as_deref() != Some(request_id.as_str())
                    || extract_event_type(event) != "run_resumed"
            }));
        }
    }

