    #[test]
    fn interaction_batch_commit_recovery_requires_every_exact_event() {
        let events = [
            approval_required_event("approval-batch-ack-a", "bash", "session-ack"),
            approval_required_event("approval-batch-ack-b", "git", "session-ack"),
        ];
        let mut expected = events
            .iter()
            .enumerate()
            .map(|(offset, event)| {
                build_run_event_insert_row(
                    "u-ack",
                    "run-ack",
                    "session-ack",
                    Some("agent-ack"),
                    20 + offset as i64,
                    "pod-ack",
                    event,
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        for event in &mut expected {
            event.request_id = Some("approval-registration:test-batch".to_string());
        }
        let mut recovered = expected
            .iter()
            .map(|event| {
                (
                    event.idempotency_key.clone().unwrap(),
                    RecoveredInteractionBatchFact {
                        event_idx: event.event_idx,
                        event_hash: event.event_hash.clone(),
                        registration_batch_id: event.request_id.clone(),
                    },
                )
            })
            .collect::<HashMap<_, _>>();
        assert_eq!(
            classify_interaction_batch_commit_recovery(&expected, &recovered),
            InteractionBatchCommitRecovery::Exact
        );

        let first_key = expected[0].idempotency_key.clone().unwrap();
        recovered.get_mut(&first_key).unwrap().registration_batch_id =
            Some("approval-registration:other-batch".to_string());
        assert!(matches!(
            classify_interaction_batch_commit_recovery(&expected, &recovered),
            InteractionBatchCommitRecovery::Conflict { .. }
        ));
        recovered.get_mut(&first_key).unwrap().registration_batch_id =
            expected[0].request_id.clone();

        let missing_key = expected[1].idempotency_key.as_ref().unwrap();
        recovered.remove(missing_key);
        assert_eq!(
            classify_interaction_batch_commit_recovery(&expected, &recovered),
            InteractionBatchCommitRecovery::Missing {
                exact: 1,
                missing: 1
            }
        );

        recovered.insert(
            expected[1].idempotency_key.clone().unwrap(),
            RecoveredInteractionBatchFact {
                event_idx: expected[1].event_idx + 1,
                event_hash: expected[1].event_hash.clone(),
                registration_batch_id: expected[1].request_id.clone(),
            },
        );
        assert!(matches!(
            classify_interaction_batch_commit_recovery(&expected, &recovered),
            InteractionBatchCommitRecovery::Conflict { .. }
        ));

        let conflict_key = expected[0].idempotency_key.clone().unwrap();
        recovered.insert(
            conflict_key.clone(),
            RecoveredInteractionBatchFact {
                event_idx: expected[0].event_idx,
                event_hash: "different-hash".to_string(),
                registration_batch_id: expected[0].request_id.clone(),
            },
        );
        assert_eq!(
            classify_interaction_batch_commit_recovery(&expected, &recovered),
            InteractionBatchCommitRecovery::Conflict {
                idempotency_key: conflict_key
            }
        );
    }

