    #[test]
    fn interaction_commit_recovery_accepts_equivalent_concurrent_winner() {
        let (expected, _) = approval_recovery_fixture();
        let mut recovered = expected
            .iter()
            .enumerate()
            .map(|(offset, event)| {
                let payload: serde_json::Value = serde_json::from_str(&event.payload_json).unwrap();
                let winner = build_run_event_insert_row(
                    &event.user_id,
                    &event.run_id,
                    &event.session_id,
                    Some(&event.agent_id),
                    24 + offset as i64,
                    "pod-concurrent-winner",
                    &payload,
                )
                .unwrap();
                recovered_interaction_event(&winner)
            })
            .collect::<Vec<_>>();
        for event in &mut recovered {
            event.payload_json = format!("\n{}\n", event.payload_json);
            event.event_hash = sha256_hex(event.payload_json.as_bytes());
        }
        assert!(matches!(
            classify_interaction_commit_recovery(
                STATUS_RUNNING,
                None,
                25,
                "session-ack",
                &expected,
                &recovered,
            ),
            InteractionCommitRecovery::EquivalentConcurrentWinner(_)
        ));
    }

