    #[tokio::test]
    async fn orphan_cancellation_atomically_settles_all_active_statuses() {
        for (suffix, status, waiting_for) in [
            ("running", STATUS_RUNNING, None),
            ("waiting", STATUS_WAITING, Some("tool_approval")),
            ("paused", STATUS_PAUSED, Some("user_resume")),
        ] {
            let store = InMemoryRunStateStore::new();
            let run_id = format!("orphan-cancel-{suffix}");
            let mut run = durable_run_record(&run_id);
            run.status = status.to_string();
            run.waiting_for = waiting_for.map(ToString::to_string);
            run.events.push(json!({
                "event_type": "user_intent",
                "idempotency_key": format!("user_intent:{run_id}"),
                "index": 0,
                "data": {
                    "intent_id": format!("intent-{run_id}"),
                    "delivery": "guide_current_run",
                    "input": {"content": "preserve this guidance"}
                }
            }));
            run.last_event_idx = 0;
            store.insert_run(run).await.unwrap();
            assert!(store.request_run_cancellation("u1", &run_id).await.unwrap());

            assert!(
                store
                    .terminalize_orphaned_run_cancellation(AtomicOrphanRunCancellationRequest {
                        user_id: "u1",
                        run_id: &run_id,
                        expected_session_id: "s1",
                        expected_run_generation: 0,
                    },)
                    .await
                    .unwrap(),
                "{suffix}"
            );
            let cancelled = store.load_run("u1", &run_id).await.unwrap().unwrap();
            assert_eq!(cancelled.status, STATUS_CANCELLED, "{suffix}");
            assert!(cancelled.waiting_for.is_none(), "{suffix}");
            assert!(cancelled.owner_pod_id.is_none(), "{suffix}");
            assert!(cancelled.owner_lease_expires_at.is_none(), "{suffix}");
            assert_eq!(cancelled.events.len(), 3, "{suffix}");
            assert_eq!(
                cancelled.events[1]["event_type"], "user_intent_returned",
                "{suffix}"
            );
            assert_eq!(
                cancelled.events[2]["event_type"], "run_finished",
                "{suffix}"
            );
            assert_eq!(cancelled.events[2]["data"]["cancelled"], true, "{suffix}");
            assert_eq!(
                cancelled.events[2]["data"]["cancellation_origin"], "user",
                "{suffix}"
            );
            assert!(
                !store
                    .terminalize_orphaned_run_cancellation(AtomicOrphanRunCancellationRequest {
                        user_id: "u1",
                        run_id: &run_id,
                        expected_session_id: "s1",
                        expected_run_generation: 0,
                    },)
                    .await
                    .unwrap(),
                "{suffix} duplicate"
            );
            let replayed = store.load_run("u1", &run_id).await.unwrap().unwrap();
            assert_eq!(
                replayed
                    .events
                    .iter()
                    .filter(|event| event["event_type"] == "user_intent_returned")
                    .count(),
                1,
                "{suffix}"
            );
            assert!(
                store
                    .is_run_cancellation_requested("u1", &run_id)
                    .await
                    .unwrap(),
                "{suffix}"
            );
        }
    }

