    #[tokio::test]
    async fn recovery_claim_wins_action_fence_before_stale_orphan_cancellation() {
        let store = Arc::new(InMemoryRunStateStore::new());
        store
            .insert_run(durable_run_record("orphan-claim-race"))
            .await
            .unwrap();
        assert!(
            store
                .request_run_cancellation("u1", "orphan-claim-race")
                .await
                .unwrap()
        );
        let fence = store.action_fence_for("u1", "orphan-claim-race");
        let held = fence.lock_owned().await;

        let claim_store = Arc::clone(&store);
        let claim =
            tokio::spawn(
                async move { claim_store.claim_recoverable_active_runs(1).await.unwrap() },
            );
        tokio::task::yield_now().await;
        let cancel_store = Arc::clone(&store);
        let cancellation = tokio::spawn(async move {
            cancel_store
                .terminalize_orphaned_run_cancellation(AtomicOrphanRunCancellationRequest {
                    user_id: "u1",
                    run_id: "orphan-claim-race",
                    expected_session_id: "s1",
                    expected_run_generation: 0,
                })
                .await
                .unwrap()
        });
        tokio::task::yield_now().await;
        drop(held);

        let claimed = claim.await.unwrap();
        assert_eq!(claimed.len(), 1);
        assert_eq!(claimed[0].run_generation, 1);
        assert!(!cancellation.await.unwrap());
        let run = store
            .load_run("u1", "orphan-claim-race")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(run.status, STATUS_RUNNING);
        assert_eq!(run.run_generation, 1);
        assert!(run.events.is_empty());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_orphan_cancellation_is_atomic_and_enqueues_work_cancelled() {
        use crate::work::{GraphRevision, WorkBranchId, WorkId};

        let (store, pool) = setup_database_run_state_store_it().await;
        for (suffix, status, waiting_for, bind_work) in [
            ("running", STATUS_RUNNING, None, true),
            ("waiting", STATUS_WAITING, Some("tool_approval"), false),
            ("paused", STATUS_PAUSED, Some("user_resume"), false),
        ] {
            let nonce = Uuid::new_v4();
            let user_id = format!("orphan-cancel-user-{nonce}");
            let session_id = format!("orphan-cancel-session-{nonce}");
            let run_id = format!("orphan-cancel-run-{suffix}-{nonce}");
            let work_id = format!("orphan-work-{nonce}");
            let branch_id = format!("orphan-branch-{nonce}");
            cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
            insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
            if bind_work {
                sqlx::query(
                    "INSERT INTO work_runtime_event_outbox_slots
                     (owner_id, work_id, last_enqueued_event_seq,
                      last_projected_event_seq, has_pending)
                     VALUES (?, ?, 0, 0, 0)",
                )
                .bind(&user_id)
                .bind(&work_id)
                .execute(pool.get())
                .await
                .expect("seed Work runtime event slot");
            }

            let mut run = durable_run_record(&run_id);
            run.user_id = user_id.clone();
            run.session_id = session_id.clone();
            run.status = status.to_string();
            run.waiting_for = waiting_for.map(ToString::to_string);
            if bind_work {
                run.work_binding = Some(DurableWorkRunBinding::new(
                    WorkId::parse(&work_id).unwrap(),
                    WorkBranchId::parse(&branch_id).unwrap(),
                    GraphRevision::new(1).unwrap(),
                ));
            }
            store.insert_run(run).await.expect("insert active run");
            store
                .append_event(
                    &user_id,
                    &session_id,
                    &run_id,
                    json!({
                        "event_type": "user_intent",
                        "idempotency_key": format!("user_intent:{run_id}"),
                        "data": {
                            "intent_id": format!("intent-{run_id}"),
                            "delivery": "guide_current_run",
                            "input": {"content": "preserve this guidance"}
                        }
                    }),
                )
                .await
                .expect("append accepted user intent");
            assert!(
                store
                    .request_run_cancellation(&user_id, &run_id)
                    .await
                    .expect("persist user cancellation marker")
            );
            let request = AtomicOrphanRunCancellationRequest {
                user_id: &user_id,
                run_id: &run_id,
                expected_session_id: &session_id,
                expected_run_generation: 0,
            };
            assert!(
                !store
                    .terminalize_orphaned_run_cancellation(request)
                    .await
                    .expect("live owner must be rejected"),
                "{suffix}"
            );
            sqlx::query(
                "UPDATE agent_runs
                 SET owner_pod_id = NULL, owner_lease_expires_at = NULL
                 WHERE user_id = ? AND run_id = ?",
            )
            .bind(&user_id)
            .bind(&run_id)
            .execute(pool.get())
            .await
            .expect("orphan exact run generation");

            let terminalizer = if suffix == "paused" {
                store
                    .clone()
                    .with_orphan_cancellation_commit_ack_loss_once()
            } else {
                store.clone()
            };
            assert!(
                terminalizer
                    .terminalize_orphaned_run_cancellation(request)
                    .await
                    .expect("terminalize orphan"),
                "{suffix}"
            );
            let cancelled = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
            assert_eq!(cancelled.status, STATUS_CANCELLED, "{suffix}");
            assert!(cancelled.waiting_for.is_none(), "{suffix}");
            assert!(cancelled.owner_pod_id.is_none(), "{suffix}");
            assert!(cancelled.owner_lease_expires_at.is_none(), "{suffix}");
            assert_eq!(
                cancelled
                    .events
                    .iter()
                    .filter(|event| {
                        event["event_type"] == "run_finished" && event["data"]["cancelled"] == true
                    })
                    .count(),
                1,
                "{suffix}"
            );
            let terminal_tail = cancelled
                .events
                .iter()
                .rev()
                .take(2)
                .map(|event| event["event_type"].as_str().unwrap())
                .collect::<Vec<_>>();
            assert_eq!(
                terminal_tail,
                vec!["run_finished", "user_intent_returned"],
                "{suffix}"
            );
            assert_eq!(
                cancelled
                    .events
                    .iter()
                    .filter(|event| event["event_type"] == "user_intent_returned")
                    .count(),
                1,
                "{suffix}"
            );
            assert!(
                !store
                    .terminalize_orphaned_run_cancellation(request)
                    .await
                    .expect("duplicate orphan terminalization"),
                "{suffix}"
            );
            assert_eq!(
                store
                    .load_run(&user_id, &run_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .events
                    .iter()
                    .filter(|event| event["event_type"] == "user_intent_returned")
                    .count(),
                1,
                "{suffix}"
            );
            let slot_count: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM agent_session_execution_slots
                 WHERE user_id = ? AND session_id = ?",
            )
            .bind(&user_id)
            .bind(&session_id)
            .fetch_one(pool.get())
            .await
            .expect("read released session slot");
            assert_eq!(slot_count, 0, "{suffix}");
            if bind_work {
                let event_kind: String = sqlx::query_scalar(
                    "SELECT event_kind FROM work_runtime_event_outbox
                     WHERE owner_id = ? AND work_id = ?",
                )
                .bind(&user_id)
                .bind(&work_id)
                .fetch_one(pool.get())
                .await
                .expect("read Work cancellation outbox");
                assert_eq!(event_kind, "run_cancelled");
                sqlx::query(
                    "DELETE FROM work_runtime_event_outbox
                     WHERE owner_id = ? AND work_id = ?",
                )
                .bind(&user_id)
                .bind(&work_id)
                .execute(pool.get())
                .await
                .expect("clean Work cancellation outbox");
                sqlx::query(
                    "DELETE FROM work_runtime_event_outbox_slots
                     WHERE owner_id = ? AND work_id = ?",
                )
                .bind(&user_id)
                .bind(&work_id)
                .execute(pool.get())
                .await
                .expect("clean Work runtime slot");
            }
            cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
            sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
                .bind(&user_id)
                .bind(&session_id)
                .execute(pool.get())
                .await
                .expect("clean orphan cancellation session");
        }

        let nonce = Uuid::new_v4();
        let user_id = format!("orphan-race-user-{nonce}");
        let session_id = format!("orphan-race-session-{nonce}");
        let run_id = format!("orphan-race-run-{nonce}");
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert claim-race run");
        assert!(
            store
                .request_run_cancellation(&user_id, &run_id)
                .await
                .expect("persist claim-race cancellation marker")
        );
        sqlx::query(
            "UPDATE agent_runs SET owner_pod_id = NULL, owner_lease_expires_at = NULL
             WHERE user_id = ? AND run_id = ?",
        )
        .bind(&user_id)
        .bind(&run_id)
        .execute(pool.get())
        .await
        .expect("orphan claim-race run");

        let cancel =
            store.terminalize_orphaned_run_cancellation(AtomicOrphanRunCancellationRequest {
                user_id: &user_id,
                run_id: &run_id,
                expected_session_id: &session_id,
                expected_run_generation: 0,
            });
        let claim = sqlx::query(
            "UPDATE agent_runs
             SET owner_pod_id = 'racing-owner',
                 owner_lease_expires_at = DATE_ADD(NOW(6), INTERVAL 60000000 MICROSECOND),
                 run_generation = run_generation + 1,
                 updated_at = NOW(6)
             WHERE user_id = ? AND run_id = ? AND run_generation = 0
               AND status IN ('running', 'waiting', 'paused')
               AND (owner_pod_id IS NULL OR owner_lease_expires_at IS NULL
                    OR owner_lease_expires_at < NOW(6))",
        )
        .bind(&user_id)
        .bind(&run_id)
        .execute(pool.get());
        let (cancelled, claimed) = tokio::join!(cancel, claim);
        let cancelled = cancelled.expect("race cancellation");
        let claimed = claimed.expect("race claim").rows_affected() == 1;
        assert_ne!(cancelled, claimed, "exactly one authority must win the row");
        let durable = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        if cancelled {
            assert_eq!(durable.status, STATUS_CANCELLED);
            assert_eq!(durable.run_generation, 0);
            assert!(durable.owner_pod_id.is_none());
        } else {
            assert_eq!(durable.status, STATUS_RUNNING);
            assert_eq!(durable.run_generation, 1);
            assert_eq!(durable.owner_pod_id.as_deref(), Some("racing-owner"));
            assert!(durable.events.iter().all(|event| {
                event["event_type"] != "run_finished" || event["data"]["cancelled"] != true
            }));
        }
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
            .bind(&user_id)
            .bind(&session_id)
            .execute(pool.get())
            .await
            .expect("clean claim-race session");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[ignore = "requires MatrixOne DB: run with ASTRA_TEST_DB_IT=1"]
    async fn database_orphan_cancellation_is_bounded_while_run_row_is_locked() {
        let (store, pool) = setup_database_run_state_store_it().await;
        let nonce = Uuid::new_v4();
        let user_id = format!("orphan-bound-user-{nonce}");
        let session_id = format!("orphan-bound-session-{nonce}");
        let run_id = format!("orphan-bound-run-{nonce}");
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        insert_active_database_session_fixture(&pool, &user_id, &session_id).await;
        let mut run = durable_run_record(&run_id);
        run.user_id = user_id.clone();
        run.session_id = session_id.clone();
        store.insert_run(run).await.expect("insert bounded run");
        assert!(
            store
                .request_run_cancellation(&user_id, &run_id)
                .await
                .expect("persist bounded cancellation marker")
        );
        sqlx::query(
            "UPDATE agent_runs SET owner_pod_id = NULL, owner_lease_expires_at = NULL
             WHERE user_id = ? AND run_id = ?",
        )
        .bind(&user_id)
        .bind(&run_id)
        .execute(pool.get())
        .await
        .expect("orphan bounded run");

        let mut blocker = pool.get().begin().await.expect("begin row blocker");
        sqlx::query("SELECT run_id FROM agent_runs WHERE user_id = ? AND run_id = ? FOR UPDATE")
            .bind(&user_id)
            .bind(&run_id)
            .fetch_one(&mut *blocker)
            .await
            .expect("lock run row");
        let started = tokio::time::Instant::now();
        let blocked = tokio::time::timeout(
            Duration::from_secs(6),
            store.terminalize_orphaned_run_cancellation(AtomicOrphanRunCancellationRequest {
                user_id: &user_id,
                run_id: &run_id,
                expected_session_id: &session_id,
                expected_run_generation: 0,
            }),
        )
        .await
        .expect("store control deadline must beat the test guard");
        assert!(
            blocked.is_err(),
            "a locked row must not report cancellation success"
        );
        assert!(started.elapsed() < Duration::from_secs(6));
        blocker.rollback().await.expect("release row blocker");

        let durable = store.load_run(&user_id, &run_id).await.unwrap().unwrap();
        assert_eq!(durable.status, STATUS_RUNNING);
        assert!(
            durable
                .events
                .iter()
                .all(|event| event["event_type"] != "run_finished")
        );
        cleanup_database_run_fixture(&pool, &user_id, &run_id).await;
        sqlx::query("DELETE FROM agent_sessions WHERE user_id = ? AND session_id = ?")
            .bind(&user_id)
            .bind(&session_id)
            .execute(pool.get())
            .await
            .expect("clean bounded session");
    }

    #[tokio::test]
    async fn save_checkpoint_rejects_terminal_run_without_mutation() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("terminal-checkpoint"))
            .await
            .unwrap();
        store
            .update_run_status_with_event_if_current(
                "u1",
                "s1",
                "terminal-checkpoint",
                &[STATUS_RUNNING],
                STATUS_FAILED,
                None,
                Some("boom"),
                make_event("run_error", json!({"error": "boom"})),
            )
            .await
            .unwrap();

        let saved = store
            .save_checkpoint(
                "u1",
                "s1",
                "terminal-checkpoint",
                r#"{"version":"checkpoint_v2","graceful":true,"last_batch_id":"terminal"}"#,
            )
            .await
            .unwrap();

        assert!(!saved);
        let loaded = store
            .load_run("u1", "terminal-checkpoint")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(loaded.status, STATUS_FAILED);
        assert!(loaded.checkpoint_json.is_none());
        assert!(loaded.checkpoint_version.is_none());
        assert!(
            store
                .load_latest_checkpoint("u1", "terminal-checkpoint", None)
                .await
                .unwrap()
                .is_none()
        );
    }

    #[tokio::test]
    async fn status_with_events_transition_commits_event_batch() {
        let store = InMemoryRunStateStore::new();
        store
            .insert_run(durable_run_record("transition-batch"))
            .await
            .unwrap();

        let events = vec![
            make_event(
                "run_error",
                json!({"error": "boom", "error_code": "network", "error_kind": "network"}),
            ),
            make_event(
                "run_finished",
                json!({"status": "failed", "error_code": "network"}),
            ),
        ];
        let updated = store
            .update_run_status_with_events_if_current(
                "u1",
                "s1",
                "transition-batch",
                &[STATUS_RUNNING],
                None,
                STATUS_FAILED,
                None,
                Some("boom"),
                &events,
            )
            .await
            .unwrap();

        assert!(updated);
        let loaded = store
            .load_run("u1", "transition-batch")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(loaded.status, STATUS_FAILED);
        assert_eq!(loaded.error_code.as_deref(), Some("network"));
        assert_eq!(loaded.error_message.as_deref(), Some("boom"));
        assert_eq!(loaded.last_event_idx, 1);
        assert_eq!(loaded.events.len(), 2);
        assert_eq!(loaded.events[0]["event_type"], "run_error");
        assert_eq!(loaded.events[1]["event_type"], "run_finished");

        let projection = store
            .load_run_projection("u1", "transition-batch")
            .await
            .unwrap()
            .expect("transition should refresh projection");
        assert_eq!(projection.status, STATUS_FAILED);
        assert_eq!(
            projection.latest_event_type.as_deref(),
            Some("run_finished")
        );
    }

