    #[tokio::test]
    async fn user_intent_control_delta_skips_large_unrelated_and_malformed_history() {
        let store = InMemoryRunStateStore::new();
        let mut run = durable_run_record("intent-control-delta-tail");
        run.events = (0..34_000)
            .map(|index| {
                if index == 17_000 {
                    serde_json::Value::String("malformed unrelated durable payload".to_string())
                } else {
                    make_event("agent_progress", json!({"index": index}))
                }
            })
            .collect();
        run.events.push(json!({
            "event_type": "user_intent",
            "idempotency_key": "user_intent:intent-control-tail",
            "data": {
                "intent_id": "intent-control-tail",
                "delivery": "guide_current_run",
                "input": {"content": "only control payload"}
            }
        }));
        run.events
            .push(serde_json::Value::String("malformed tail".to_string()));
        run.events
            .push(make_event("reasoning_delta", json!({"chunk": "tail"})));
        run.last_event_idx = 34_002;
        store.insert_run(run).await.unwrap();

        let delta = store
            .load_user_intent_control_delta("u1", "intent-control-delta-tail", 0, 8)
            .await
            .unwrap()
            .expect("run exists");
        assert_eq!(delta.events.len(), 1);
        assert_eq!(delta.events[0]["index"], 34_000);
        assert_eq!(delta.page_cursor, 34_000);
        assert_eq!(delta.authoritative_last_event_idx, 34_002);
        assert!(!delta.has_more);
        assert!(delta.settled_source_indices.is_empty());
        assert_eq!(store.load_run_call_count(), 0);
    }

    #[tokio::test]
    async fn user_intent_control_delta_keyset_pages_do_not_skip_or_starve_control_events() {
        let store = InMemoryRunStateStore::new();
        let mut run = durable_run_record("intent-control-delta-pages");
        run.events = (0..5)
            .map(|index| {
                json!({
                    "index": index,
                    "event_type": "user_intent",
                    "idempotency_key": format!("user_intent:intent-page-{index}"),
                    "data": {
                        "intent_id": format!("intent-page-{index}"),
                        "delivery": "guide_current_run",
                        "input": {"content": format!("page {index}")}
                    }
                })
            })
            .collect();
        run.last_event_idx = 8;
        run.events.extend([
            make_event("reasoning_delta", json!({"index": 5})),
            make_event("reasoning_delta", json!({"index": 6})),
            make_event("reasoning_delta", json!({"index": 7})),
            make_event("reasoning_delta", json!({"index": 8})),
        ]);
        store.insert_run(run).await.unwrap();

        let first = store
            .load_user_intent_control_delta("u1", "intent-control-delta-pages", -1, 2)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(first.page_cursor, 1);
        assert!(first.has_more);
        let second = store
            .load_user_intent_control_delta(
                "u1",
                "intent-control-delta-pages",
                first.page_cursor,
                2,
            )
            .await
            .unwrap()
            .unwrap();
        assert_eq!(second.page_cursor, 3);
        assert!(second.has_more);
        let third = store
            .load_user_intent_control_delta(
                "u1",
                "intent-control-delta-pages",
                second.page_cursor,
                2,
            )
            .await
            .unwrap()
            .unwrap();
        assert_eq!(third.page_cursor, 4);
        assert_eq!(third.authoritative_last_event_idx, 8);
        assert!(!third.has_more);
        assert_eq!(
            first
                .events
                .iter()
                .chain(&second.events)
                .chain(&third.events)
                .filter_map(|event| event["index"].as_i64())
                .collect::<Vec<_>>(),
            vec![0, 1, 2, 3, 4]
        );
    }

